local changes=game.HttpService:JSONDecode([====[[{"path": ["ReplicatedStorage", "Shared", "EventDefinitions"], "source": "-- Shared event metadata. Only the server service decides which event is active.\nlocal EVENT_DURATION = 7 * 60\n\nlocal function normal(id, displayName, description, weight)\n\treturn {\n\t\tId = id,\n\t\tDisplayName = displayName,\n\t\tCategory = \"Normal\",\n\t\tDescription = description,\n\t\tWeight = weight,\n\t\tDuration = EVENT_DURATION,\n\t\tIsAutomatic = true,\n\t\tIsSecret = false,\n\t\tBuffs = {},\n\t\tImageId = \"\",\n\t\tDisplayEffects = {},\n\t}\nend\n\nlocal function secret(id, displayName, description)\n\treturn {\n\t\tId = id,\n\t\tDisplayName = displayName,\n\t\tCategory = \"Secret\",\n\t\tDescription = description,\n\t\tWeight = 0,\n\t\tDuration = EVENT_DURATION,\n\t\tIsAutomatic = false,\n\t\tIsSecret = true,\n\t\tBuffs = {},\n\t\tImageId = \"\",\n\t\tDisplayEffects = {},\n\t}\nend\n\nlocal definitions = {\n\tSunnySkies = normal(\"SunnySkies\", \"Sunny Skies\", \"Clear skies and warm sunlight.\", 18),\n\tRainyDay = normal(\"RainyDay\", \"Rainy Day\", \"A steady rain across the kingdom.\", 14),\n\tThunderstorm = normal(\"Thunderstorm\", \"Thunderstorm\", \"Dark clouds, thunder, and lightning.\", 9),\n\tSnowfall = normal(\"Snowfall\", \"Snowfall\", \"Soft snow falls over the world.\", 9),\n\tFoggy = normal(\"Foggy\", \"Foggy\", \"A thick mist settles over the land.\", 10),\n\tWindy = normal(\"Windy\", \"Windy\", \"Strong winds sweep through the biomes.\", 10),\n\tHeatwave = normal(\"Heatwave\", \"Heatwave\", \"Intense heat fills the air.\", 9),\n\tAurora = normal(\"Aurora\", \"Aurora\", \"Colorful lights shimmer overhead.\", 5),\n\tBloodMoon = normal(\"BloodMoon\", \"Blood Moon\", \"A crimson moon rises over the kingdom.\", 4),\n\tMeteorShower = normal(\"MeteorShower\", \"Meteor Shower\", \"Meteors streak across the night sky.\", 5),\n\tSpiritNight = normal(\"SpiritNight\", \"Spirit Night\", \"An eerie, mystical night arrives.\", 4),\n\tRainbow = normal(\"Rainbow\", \"Rainbow\", \"A bright rainbow spans the sky.\", 4),\n\tChaos = secret(\"Chaos\", \"Chaos\", \"An unpredictable disturbance takes hold.\"),\n\tInverted = secret(\"Inverted\", \"Inverted\", \"The world takes on an inverted theme.\"),\n\tNightmare = secret(\"Nightmare\", \"Nightmare\", \"A haunting nightmare atmosphere arrives.\"),\n\tVoid = secret(\"Void\", \"Void\", \"A mysterious void overtakes the sky.\"),\n\tGolden = secret(\"Golden\", \"Golden\", \"The kingdom glows with a golden theme.\"),\n\tAdminAbuse = secret(\"AdminAbuse\", \"Admin Abuse\", \"A special admin-controlled event theme.\"),\n}\n\n-- Structured server gameplay modifiers. A value of 1 is neutral.\n-- DisplayEffects below remain presentation text and are never parsed for gameplay.\nlocal gameplayBuffs = {\n\tSunnySkies = { CoinMultiplier = 1.5, PetLuckMultiplier = 1.10 },\n\tRainyDay = { CoinMultiplier = 1.25, CommonPetMultiplier = 1.15 },\n\tThunderstorm = { RarePetMultiplier = 1.5, MutationMultiplier = 1.25 },\n\tSnowfall = { CoinMultiplier = 2.0, IcePetMultiplier = 1.25 },\n\tFoggy = { ShinyMultiplier = 1.25 },\n\tWindy = { FlyingPetMultiplier = 1.5, MovementSpeedMultiplier = 1.25 },\n\tHeatwave = { CoinMultiplier = 2.0, DesertPetMultiplier = 1.25 },\n\tAurora = { ShinyMultiplier = 3.0, RarePetMultiplier = 1.5 },\n\tBloodMoon = { MutationMultiplier = 2.0, LegendaryPetMultiplier = 1.5 },\n\tMeteorShower = { RarePetMultiplier = 3.0 },\n\tSpiritNight = { MythicalPetMultiplier = 2.0 },\n\tRainbow = { GlobalLuckMultiplier = 2.0 },\n\tChaos = { CoinMultiplier = 5.0, PetLuckMultiplier = 5.0, ShinyMultiplier = 5.0, MutationMultiplier = 5.0, PetXPMultiplier = 5.0 },\n\tInverted = { RarePetMultiplier = 3.0 },\n\tNightmare = { LegendaryPetMultiplier = 10.0 },\n\tVoid = { MythicalPetMultiplier = 5.0, MutationMultiplier = 3.0 },\n\tGolden = { CoinMultiplier = 10.0, ShinyMultiplier = 5.0 },\n\tAdminAbuse = { CoinMultiplier = 5.0, PetLuckMultiplier = 3.0, RarePetMultiplier = 3.0, LegendaryPetMultiplier = 3.0, MythicalPetMultiplier = 3.0, ShinyMultiplier = 5.0, MutationMultiplier = 5.0, PetXPMultiplier = 3.0, MovementSpeedMultiplier = 1.5 },\n}\n\nfor id, buffs in pairs(gameplayBuffs) do\n\tdefinitions[id].Buffs = buffs\nend\n\n-- Presentation text only; some named pet types do not exist in game data yet.\nlocal display = {\n\tSunnySkies = { \"Beautiful weather has covered the kingdom!\", \"+50% Coins\", \"+10% Pet Luck\" },\n\tRainyDay = { \"Rain is falling across Animal Kingdom.\", \"+25% Coins\", \"+15% Common Pet Chance\" },\n\tThunderstorm = { \"Lightning crackles across the kingdom!\", \"+50% Rare Pet Chance\", \"+25% Mutation Chance\" },\n\tSnowfall = { \"Snow is covering the kingdom!\", \"2x Coins\", \"+25% Ice Pet Chance\" },\n\tFoggy = { \"A mysterious fog has rolled in.\", \"+25% Shiny Chance\", \"Special Fog Pets\" },\n\tWindy = { \"Powerful winds sweep across the kingdom.\", \"+50% Flying Pet Chance\", \"+25% Movement Speed\" },\n\tHeatwave = { \"The kingdom is heating up!\", \"2x Coins\", \"+25% Desert Pet Chance\" },\n\tAurora = { \"A magical aurora shines above the kingdom.\", \"3x Shiny Chance\", \"+50% Rare Pet Chance\" },\n\tBloodMoon = { \"The Blood Moon has risen...\", \"2x Mutation Chance\", \"+50% Legendary Pet Chance\" },\n\tMeteorShower = { \"Meteors are raining across the kingdom!\", \"3x Rare Pet Chance\", \"Meteor Pets\" },\n\tSpiritNight = { \"Spirits have awakened throughout the kingdom.\", \"2x Mythical Pet Chance\", \"Ghost Pets\" },\n\tRainbow = { \"A magical rainbow has appeared!\", \"2x Luck\", \"Improved Pet Chances\" },\n\tChaos = { \"Reality has completely broken.\", \"5x Everything\", \"Random Chaos Effects\" },\n\tInverted = { \"The kingdom has been turned upside down.\", \"3x Rare Pet Chance\", \"Strange Physics\" },\n\tNightmare = { \"A nightmare has consumed Animal Kingdom.\", \"10x Legendary Pet Chance\", \"Nightmare Pets\" },\n\tVoid = { \"The Void is consuming the kingdom.\", \"5x Mythical Pet Chance\", \"Mutation Storm\" },\n\tGolden = { \"Everything has turned to gold!\", \"10x Coins\", \"5x Shiny Chance\" },\n\tAdminAbuse = { \"The admins have lost control.\", \"Random Extreme Buffs\", \"Admin Chaos\" },\n}\n\nfor id, lines in pairs(display) do\n\tlocal definition = definitions[id]\n\tdefinition.Description = lines[1]\n\tdefinition.DisplayEffects = { lines[2], lines[3] }\nend\n\nreturn definitions\n"}, {"path": ["ServerScriptService", "AK_PlotAssignment"], "source": "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal PlotLocator = require(script.Parent.PlotLocator)\nlocal Teleports = require(script.Parent.AdminCommandCenter.Teleports)\n\nlocal playerPlots = {}\nlocal plotOwners = {}\nlocal joining = {}\nlocal initializedPlots = {}\nlocal remotes = ReplicatedStorage:FindFirstChild(\"AnimalKingdomRemotes\")\nif not remotes then\n\tremotes = Instance.new(\"Folder\")\n\tremotes.Name = \"AnimalKingdomRemotes\"\n\tremotes.Parent = ReplicatedStorage\nend\nlocal assignedRemote = remotes:FindFirstChild(\"AK_PlotAssigned\")\nif not assignedRemote then\n\tassignedRemote = Instance.new(\"RemoteEvent\")\n\tassignedRemote.Name = \"AK_PlotAssigned\"\n\tassignedRemote.Parent = remotes\nend\n\nlocal function getPlots()\n\treturn PlotLocator.getPlots()\nend\n\nlocal function getPlayerPlot(player)\n\treturn playerPlots[player]\nend\n\nlocal function findAvailablePlot()\n\tfor _, plot in ipairs(getPlots()) do\n\t\tif not plotOwners[plot] and plot:GetAttribute(\"Claimed\") ~= true then return plot end\n\tend\nend\n\nlocal function plotFootprint(plot)\n\tif plot:IsA(\"BasePart\") then return plot.CFrame, plot.Size, plot end\n\tlocal selected, score = nil, -math.huge\n\tfor _, part in ipairs(plot:GetDescendants()) do\n\t\tif part:IsA(\"BasePart\") and part.Size.X >= 10 and part.Size.Z >= 10 then\n\t\t\tlocal name = part.Name:lower()\n\t\t\tlocal floorName = name:find(\"floor\", 1, true) or name:find(\"ground\", 1, true)\n\t\t\t\tor name:find(\"base\", 1, true) or name:find(\"platform\", 1, true)\n\t\t\tlocal candidateScore = part.Size.X * part.Size.Z + (floorName and 1000000 or 0)\n\t\t\tif candidateScore > score then selected, score = part, candidateScore end\n\t\tend\n\tend\n\tif selected then return selected.CFrame, selected.Size, selected end\n\tlocal cf, size = PlotLocator.getBounds(plot)\n\treturn cf, size, nil\nend\n\nlocal function findSpawn(plot)\n\tlocal cf, size = plotFootprint(plot)\n\tfor _, name in ipairs({ \"PlotSpawn\", \"PlayerSpawn\", \"SpawnPoint\", \"Spawn\", \"SpawnLocation\" }) do\n\t\tlocal marker = plot:FindFirstChild(name, true)\n\t\tif marker and marker:IsA(\"BasePart\") and cf then\n\t\t\tlocal relative = cf:PointToObjectSpace(marker.Position)\n\t\t\tif math.abs(relative.X) <= size.X * 0.5 - 1 and math.abs(relative.Z) <= size.Z * 0.5 - 1 then\n\t\t\t\treturn marker\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal function ensureSpawn(plot)\n\tlocal marker = findSpawn(plot)\n\tlocal validExisting = marker ~= nil\n\tif not marker then\n\t\tlocal prior = plot:FindFirstChild(\"PlotSpawn\", true)\n\t\tif prior and prior:IsA(\"BasePart\") then marker = prior end\n\tend\n\tif marker and marker.Name ~= \"PlotSpawn\" then return marker end\n\tlocal isPriorGenerated = marker and plot:IsA(\"BasePart\") and marker.Transparency == 1 and not marker.CanCollide\n\t\tand marker.Size.X <= 1.1 and marker.Size.Y <= 1.1 and marker.Size.Z <= 1.1\n\tif marker and validExisting and not marker:GetAttribute(\"AKGeneratedPlotSpawn\") and not isPriorGenerated then return marker end\n\tlocal cf, size, floor = plotFootprint(plot)\n\tif not cf then return end\n\tlocal center = cf.Position\n\tlocal town = PlotLocator.getTown()\n\tlocal plaza = town and town:FindFirstChild(\"TownPlaza\", true)\n\tlocal townCenter = plaza and plaza:IsA(\"BasePart\") and plaza.Position or nil\n\tlocal outward = townCenter and Vector3.new(center.X - townCenter.X, 0, center.Z - townCenter.Z) or Vector3.zero\n\tif outward.Magnitude > 0.01 then outward = outward.Unit else outward = Vector3.zero end\n\tlocal horizontalOffset = outward * math.min(size.X, size.Z) * 0.18\n\tlocal desired = center + horizontalOffset\n\tlocal top = floor and floor.CanCollide and (floor.Position.Y + floor.Size.Y * 0.5) or nil\n\tif not top then\n\t\tlocal ray = RaycastParams.new()\n\t\tray.FilterType = Enum.RaycastFilterType.Exclude\n\t\tray.FilterDescendantsInstances = { plot }\n\t\tlocal hit = workspace:Raycast(desired + Vector3.new(0, math.max(120, size.Y + 50), 0), Vector3.new(0, -math.max(400, size.Y + 250), 0), ray)\n\t\ttop = hit and hit.Position.Y or center.Y + size.Y * 0.5\n\tend\n\tif not marker then\n\t\tmarker = Instance.new(\"Part\")\n\t\tmarker.Name = \"PlotSpawn\"\n\t\tmarker.Size = Vector3.new(1, 1, 1)\n\t\tmarker.Parent = plot\n\tend\n\tmarker.CFrame = CFrame.new(desired.X, top + 0.5, desired.Z)\n\tmarker.Anchored = true\n\tmarker.Transparency = 1\n\tmarker.CanCollide = false\n\tmarker.CanTouch = false\n\tmarker.CanQuery = false\n\tmarker:SetAttribute(\"AKGeneratedPlotSpawn\", true)\n\treturn marker\nend\n\nlocal function ownerDisplay(plot)\n\tlocal existing = plot:FindFirstChild(\"AK_PlotOwnerBillboard\", true)\n\tif existing and existing:IsA(\"BillboardGui\") then\n\t\tlocal label = existing:FindFirstChild(\"OwnerText\", true)\n\t\tif label and label:IsA(\"TextLabel\") then\n\t\t\texisting.Size = UDim2.fromOffset(210, 44)\n\t\t\texisting.StudsOffset = Vector3.zero\n\t\t\texisting.StudsOffsetWorldSpace = Vector3.new(0, 5, 0)\n\t\t\texisting.MaxDistance = 105\n\t\t\tlocal panel = label.Parent\n\t\t\tif panel:IsA(\"Frame\") then\n\t\t\t\tpanel.BackgroundColor3 = Color3.fromRGB(8, 24, 48)\n\t\t\t\tpanel.BackgroundTransparency = 0.18\n\t\t\tend\n\t\t\tlabel.TextColor3 = Color3.fromRGB(245, 248, 252)\n\t\t\tlabel.TextStrokeColor3 = Color3.fromRGB(25, 125, 255)\n\t\t\tlabel.TextStrokeTransparency = 0.2\n\t\t\treturn label, existing\n\t\tend\n\tend\n\tfor _, name in ipairs({ \"OwnerSign\", \"PlotSign\", \"PlotOwnerSign\", \"OwnerBillboard\" }) do\n\t\tlocal sign = plot:FindFirstChild(name, true)\n\t\tif sign then\n\t\t\tlocal label = sign:FindFirstChildWhichIsA(\"TextLabel\", true)\n\t\t\tlocal gui = label and label:FindFirstAncestorWhichIsA(\"LayerCollector\")\n\t\t\tif label and gui and (gui:IsA(\"BillboardGui\") or gui:IsA(\"SurfaceGui\")) then\n\t\t\t\tif gui:IsA(\"BillboardGui\") then\n\t\t\t\t\tgui.Size = UDim2.fromOffset(210, 44)\n\t\t\t\t\tgui.MaxDistance = 105\n\t\t\t\tend\n\t\t\t\treturn label, gui\n\t\t\tend\n\t\tend\n\tend\n\tlocal marker = ensureSpawn(plot)\n\tif not marker then return end\n\tlocal gui = Instance.new(\"BillboardGui\")\n\tgui.Name = \"AK_PlotOwnerBillboard\"\n\tgui.Size = UDim2.fromOffset(210, 44)\n\tgui.StudsOffsetWorldSpace = Vector3.new(0, 5, 0)\n\tgui.AlwaysOnTop = true\n\tgui.MaxDistance = 105\n\tgui.Enabled = false\n\tgui.Parent = marker\n\tlocal panel = Instance.new(\"Frame\")\n\tpanel.Size = UDim2.fromScale(1, 1)\n\tpanel.BackgroundColor3 = Color3.fromRGB(8, 24, 48)\n\tpanel.BackgroundTransparency = 0.18\n\tpanel.Parent = gui\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(0, 8)\n\tcorner.Parent = panel\n\tlocal stroke = Instance.new(\"UIStroke\")\n\tstroke.Color = Color3.fromRGB(25, 125, 255)\n\tstroke.Thickness = 2\n\tstroke.Parent = panel\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Name = \"OwnerText\"\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = 1\n\tlabel.Font = Enum.Font.GothamBold\n\tlabel.TextScaled = true\n\tlabel.TextColor3 = Color3.fromRGB(245, 248, 252)\n\tlabel.TextStrokeColor3 = Color3.fromRGB(25, 125, 255)\n\tlabel.TextStrokeTransparency = 0.2\n\tlabel.Parent = panel\n\tlocal padding = Instance.new(\"UIPadding\")\n\tpadding.PaddingLeft = UDim.new(0, 10)\n\tpadding.PaddingRight = UDim.new(0, 10)\n\tpadding.Parent = label\n\treturn label, gui\nend\n\nlocal function updateOwnerDisplay(plot, player)\n\t-- Clear any label saved from the previous version before showing ownership.\n\tfor _, descendant in ipairs(plot:GetDescendants()) do\n\t\tif descendant:IsA(\"TextLabel\") and descendant.Text == \"AVAILABLE PLOT\" then\n\t\t\tdescendant.Text = \"\"\n\t\t\tdescendant.Visible = false\n\t\tend\n\tend\n\tlocal label, gui = ownerDisplay(plot)\n\tif not label or not gui then return end\n\tlocal claimed = player ~= nil\n\tlabel.Text = claimed and player.Name or \"\"\n\tlabel.Visible = claimed\n\tgui.Enabled = claimed\nend\n\nlocal function preparePlots(plots)\n\tfor _, plot in ipairs(plots) do\n\t\tif not initializedPlots[plot] then\n\t\t\tinitializedPlots[plot] = true\n\t\t\tplot:SetAttribute(\"OwnerUserId\", 0)\n\t\t\tplot:SetAttribute(\"OwnerUsername\", \"\")\n\t\t\tplot:SetAttribute(\"Claimed\", false)\n\t\t\tensureSpawn(plot)\n\t\t\tupdateOwnerDisplay(plot, nil)\n\t\tend\n\tend\nend\n\nlocal function claimPlot(player, plot)\n\t-- No yield between the availability check and the two ownership writes.\n\tif plotOwners[plot] or plot:GetAttribute(\"Claimed\") == true or playerPlots[player] then return false end\n\tplotOwners[plot] = player\n\tplayerPlots[player] = plot\n\tplot:SetAttribute(\"OwnerUserId\", player.UserId)\n\tplot:SetAttribute(\"OwnerUsername\", player.Name)\n\tplot:SetAttribute(\"Claimed\", true)\n\tplayer:SetAttribute(\"PlotId\", plot.Name)\n\tplayer:SetAttribute(\"HasPlot\", true)\n\treturn true\nend\n\nlocal function releasePlot(player)\n\tlocal plot = playerPlots[player]\n\tif not plot then return end\n\tplayerPlots[player] = nil\n\tplotOwners[plot] = nil\n\tif plot.Parent then\n\t\tplot:SetAttribute(\"OwnerUserId\", 0)\n\t\tplot:SetAttribute(\"OwnerUsername\", \"\")\n\t\tplot:SetAttribute(\"Claimed\", false)\n\t\tupdateOwnerDisplay(plot, nil)\n\tend\n\tplayer:SetAttribute(\"PlotId\", \"\")\n\tplayer:SetAttribute(\"HasPlot\", false)\n\tprint(\"[PlotAssignment] Released \" .. plot.Name)\nend\n\nlocal function teleportCharacterToPlot(player, character)\n\tlocal plot = getPlayerPlot(player)\n\tif not plot or not plot.Parent then return end\n\tlocal root = character:WaitForChild(\"HumanoidRootPart\", 10)\n\tif not root or player.Character ~= character or not player:IsDescendantOf(Players) then return end\n\t-- Let Roblox finish its initial spawn placement before moving the character.\n\ttask.wait(0.15)\n\tif player.Character ~= character or getPlayerPlot(player) ~= plot then return end\n\tlocal marker = ensureSpawn(plot)\n\tif not marker then return end\n\tlocal moved, reason = Teleports.Near(player, marker.CFrame)\n\tif not moved then\n\t\twarn(\"[PlotAssignment] Safe spawn unavailable for \" .. player.Name .. \": \" .. tostring(reason))\n\t\treturn\n\tend\n\tprint(\"[PlotAssignment] Spawned \" .. player.Name .. \" at \" .. plot.Name)\nend\n\nlocal function assignPlayer(player)\n\tif joining[player] or getPlayerPlot(player) then return end\n\tjoining[player] = true\n\tlocal plots = getPlots()\n\tfor _ = 1, 20 do\n\t\tif #plots > 0 or not player:IsDescendantOf(Players) then break end\n\t\ttask.wait(1)\n\t\tplots = getPlots()\n\tend\n\tif not player:IsDescendantOf(Players) then joining[player] = nil; return end\n\tif #plots == 0 then\n\t\tjoining[player] = nil\n\t\twarn(\"[PlotAssignment] No player plots found; assignment unavailable for \" .. player.Name)\n\t\treturn\n\tend\n\tpreparePlots(plots)\n\tlocal plot = findAvailablePlot()\n\tif not plot or not claimPlot(player, plot) then\n\t\tjoining[player] = nil\n\t\tprint(\"[PlotAssignment] No available plots for \" .. player.Name)\n\t\tplayer:Kick(\"All Animal Kingdom plots in this server are currently claimed. Please join another server.\")\n\t\treturn\n\tend\n\tjoining[player] = nil\n\tlocal marker = ensureSpawn(plot)\n\tupdateOwnerDisplay(plot, player)\n\tprint(\"[PlotAssignment] Assigned \" .. plot.Name .. \" to \" .. player.Name)\n\tif marker then assignedRemote:FireClient(player, plot.Name, player.Name) end\n\tplayer.CharacterAdded:Connect(function(character)\n\t\ttask.defer(teleportCharacterToPlot, player, character)\n\tend)\n\tif player.Character then task.defer(teleportCharacterToPlot, player, player.Character) end\nend\n\nlocal plots = getPlots()\nlocal container = PlotLocator.getContainer()\nprint(\"[PlotAssignment] Found \" .. #plots .. \" plots at \" .. (container and container:GetFullName() or \"<not loaded>\"))\nfor _, plot in ipairs(plots) do print(\"[PlotAssignment] Plot: \" .. plot:GetFullName()) end\npreparePlots(plots)\nif #plots == 0 then\n\ttask.spawn(function()\n\t\tfor _ = 1, 30 do\n\t\t\ttask.wait(1)\n\t\t\tlocal loaded = getPlots()\n\t\t\tif #loaded > 0 then\n\t\t\t\tpreparePlots(loaded)\n\t\t\t\tlocal loadedContainer = PlotLocator.getContainer()\n\t\t\t\tprint(\"[PlotAssignment] Found \" .. #loaded .. \" plots at \" .. (loadedContainer and loadedContainer:GetFullName() or \"<unknown>\"))\n\t\t\t\tfor _, plot in ipairs(loaded) do print(\"[PlotAssignment] Plot: \" .. plot:GetFullName()) end\n\t\t\t\tbreak\n\t\t\tend\n\t\tend\n\tend)\nend\nPlayers.PlayerAdded:Connect(function(player)\n\ttask.spawn(assignPlayer, player)\nend)\nPlayers.PlayerRemoving:Connect(function(player)\n\tjoining[player] = nil\n\treleasePlot(player)\nend)\nfor _, player in ipairs(Players:GetPlayers()) do task.spawn(assignPlayer, player) end\n"}, {"path": ["ServerScriptService", "AK_TownVisualRuntime"], "source": "-- Runtime-only colored overlays for six approved Animal Kingdom town assets.\n-- Canonical buildings are read only and are used exclusively for GetBoundingBox().\n\nlocal ServerStorage = game:GetService(\"ServerStorage\")\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal RUNTIME_FOLDER_NAME = \"AK_RuntimeTownVisuals\"\nlocal EXPANSION = 1.002\nlocal MAX_RATIO_SPREAD = 0.03\nlocal CENTER_TOLERANCE = 0.01\nlocal SIZE_TOLERANCE = 0.05\nlocal ORIENTATION_DOT_TOLERANCE = 0.999999\n\ntype Style = { color: Color3, material: Enum.Material }\ntype AssetSpec = {\n\tname: string,\n\tsourceName: string,\n\ttargetPath: { string },\n\texpectedParts: number,\n\tpalette: { [string]: Style },\n}\n\nlocal function style(red: number, green: number, blue: number, material: Enum.Material): Style\n\treturn {\n\t\tcolor = Color3.fromRGB(red, green, blue),\n\t\tmaterial = material,\n\t}\nend\n\nlocal SPECS: { AssetSpec } = {\n\t{\n\t\tname = \"GeneralStore\",\n\t\tsourceName = \"GeneralStore_MaterialSplit\",\n\t\ttargetPath = { \"AnimalKingdomTown\", \"DecorativeBuildings\", \"GeneralStoreBuilding\" },\n\t\texpectedParts = 5,\n\t\tpalette = {\n\t\t\tWalls = style(238, 218, 179, Enum.Material.SmoothPlastic),\n\t\t\tTimber = style(117, 78, 52, Enum.Material.WoodPlanks),\n\t\t\tRoof = style(144, 82, 61, Enum.Material.Slate),\n\t\t\tStone = style(145, 139, 126, Enum.Material.Cobblestone),\n\t\t\tSage = style(105, 145, 96, Enum.Material.SmoothPlastic),\n\t\t},\n\t},\n\t{\n\t\tname = \"Blacksmith\",\n\t\tsourceName = \"Blacksmith_MaterialSplit\",\n\t\ttargetPath = { \"AnimalKingdomTown\", \"DecorativeBuildings\", \"BlacksmithBuilding\" },\n\t\texpectedParts = 5,\n\t\tpalette = {\n\t\t\tWalls = style(213, 187, 147, Enum.Material.SmoothPlastic),\n\t\t\tTimber = style(79, 55, 42, Enum.Material.WoodPlanks),\n\t\t\tRoof = style(68, 67, 64, Enum.Material.Slate),\n\t\t\tStone = style(145, 139, 126, Enum.Material.Cobblestone),\n\t\t\tForgeAccent = style(177, 91, 64, Enum.Material.SmoothPlastic),\n\t\t},\n\t},\n\t{\n\t\tname = \"CentralWell\",\n\t\tsourceName = \"Well_MaterialSplit\",\n\t\ttargetPath = { \"AnimalKingdomTown\", \"Decor\", \"CentralWell\" },\n\t\texpectedParts = 3,\n\t\tpalette = {\n\t\t\tStone = style(161, 154, 139, Enum.Material.Cobblestone),\n\t\t\tWood = style(117, 78, 52, Enum.Material.WoodPlanks),\n\t\t\tRoof = style(83, 82, 78, Enum.Material.Slate),\n\t\t},\n\t},\n\t{\n\t\tname = \"MarketStand1\",\n\t\tsourceName = \"MarketStand1_MaterialSplit\",\n\t\ttargetPath = { \"AnimalKingdomTown\", \"DisplayProps\", \"MarketStand1\" },\n\t\texpectedParts = 3,\n\t\tpalette = {\n\t\t\tWood = style(117, 78, 52, Enum.Material.WoodPlanks),\n\t\t\tCream = style(238, 218, 179, Enum.Material.SmoothPlastic),\n\t\t\tCanopy = style(105, 145, 96, Enum.Material.SmoothPlastic),\n\t\t},\n\t},\n\t{\n\t\tname = \"MarketStand2\",\n\t\tsourceName = \"MarketStand2_MaterialSplit\",\n\t\ttargetPath = { \"AnimalKingdomTown\", \"DisplayProps\", \"MarketStand2\" },\n\t\texpectedParts = 3,\n\t\tpalette = {\n\t\t\tWood = style(117, 78, 52, Enum.Material.WoodPlanks),\n\t\t\tCream = style(238, 218, 179, Enum.Material.SmoothPlastic),\n\t\t\tCanopy = style(170, 73, 70, Enum.Material.SmoothPlastic),\n\t\t},\n\t},\n\t{\n\t\tname = \"MarketCart\",\n\t\tsourceName = \"Cart_MaterialSplit\",\n\t\ttargetPath = { \"AnimalKingdomTown\", \"DisplayProps\", \"MarketCart\" },\n\t\texpectedParts = 4,\n\t\tpalette = {\n\t\t\tMainWood = style(177, 123, 77, Enum.Material.WoodPlanks),\n\t\t\tDarkWood = style(117, 78, 52, Enum.Material.WoodPlanks),\n\t\t\tWheelFrame = style(79, 55, 42, Enum.Material.WoodPlanks),\n\t\t\tAccent = style(177, 91, 64, Enum.Material.SmoothPlastic),\n\t\t},\n\t},\n}\n\nlocal ROLE_ORDER = {\n\t\"ForgeAccent\",\n\t\"WheelFrame\",\n\t\"MainWood\",\n\t\"DarkWood\",\n\t\"Canopy\",\n\t\"Accent\",\n\t\"Walls\",\n\t\"Timber\",\n\t\"Roof\",\n\t\"Stone\",\n\t\"Cream\",\n\t\"Sage\",\n\t\"Wood\",\n}\n\nlocal function semanticRole(partName: string, palette: { [string]: Style }): string?\n\tlocal normalized = string.lower(partName):gsub(\"[^%w]\", \"\")\n\tfor _, role in ROLE_ORDER do\n\t\tif palette[role] and string.find(normalized, string.lower(role), 1, true) then\n\t\t\treturn role\n\t\tend\n\tend\n\treturn nil\nend\n\nlocal function resolvePath(root: Instance, path: { string }): Instance?\n\tlocal current = root\n\tfor _, name in path do\n\t\tlocal nextInstance = current:FindFirstChild(name)\n\t\tif not nextInstance then return nil end\n\t\tcurrent = nextInstance\n\tend\n\treturn current\nend\n\nlocal function sourceMeshParts(source: Instance): { MeshPart }\n\tlocal result = {}\n\tfor _, descendant in source:GetDescendants() do\n\t\tif descendant:IsA(\"MeshPart\") then\n\t\t\ttable.insert(result, descendant)\n\t\telseif descendant:IsA(\"BasePart\") then\n\t\t\terror(string.format(\"AK_TownVisualRuntime source contains non-MeshPart geometry: %s\", descendant:GetFullName()))\n\t\tend\n\tend\n\treturn result\nend\n\nlocal function alignBoundingBox(model: Model, targetCFrame: CFrame, targetSize: Vector3)\n\tlocal sourceCFrame, sourceSize = model:GetBoundingBox()\n\tassert(sourceSize.X > 0 and sourceSize.Y > 0 and sourceSize.Z > 0, model.Name .. \" has an empty source bounding box\")\n\n\tlocal ratios = {\n\t\ttargetSize.X / sourceSize.X,\n\t\ttargetSize.Y / sourceSize.Y,\n\t\ttargetSize.Z / sourceSize.Z,\n\t}\n\ttable.sort(ratios)\n\tlocal medianRatio = ratios[2]\n\tlocal ratioSpread = (ratios[3] - ratios[1]) / math.max(medianRatio, 1e-9)\n\tassert(ratioSpread <= MAX_RATIO_SPREAD, string.format(\"%s is not proportional to canonical bounds (spread=%.6f)\", model.Name, ratioSpread))\n\n\tmodel:ScaleTo(model:GetScale() * medianRatio)\n\tlocal scaledCFrame = model:GetBoundingBox()\n\tmodel:PivotTo(targetCFrame * scaledCFrame:Inverse() * model:GetPivot())\n\tlocal matchedCFrame, matchedSize = model:GetBoundingBox()\n\tlocal matchedOrientation = matchedCFrame.RightVector:Dot(targetCFrame.RightVector) >= ORIENTATION_DOT_TOLERANCE\n\t\tand matchedCFrame.UpVector:Dot(targetCFrame.UpVector) >= ORIENTATION_DOT_TOLERANCE\n\t\tand matchedCFrame.LookVector:Dot(targetCFrame.LookVector) >= ORIENTATION_DOT_TOLERANCE\n\tassert((matchedCFrame.Position - targetCFrame.Position).Magnitude <= CENTER_TOLERANCE, model.Name .. \" failed canonical center alignment\")\n\tassert((matchedSize - targetSize).Magnitude <= SIZE_TOLERANCE, model.Name .. \" failed canonical size alignment\")\n\tassert(matchedOrientation, model.Name .. \" failed canonical orientation alignment\")\n\n\t-- The overlay is deliberately 0.2%% larger than the matched canonical visual.\n\tmodel:ScaleTo(model:GetScale() * EXPANSION)\n\tlocal expandedCFrame = model:GetBoundingBox()\n\tmodel:PivotTo(targetCFrame * expandedCFrame:Inverse() * model:GetPivot())\n\tlocal finalCFrame, finalSize = model:GetBoundingBox()\n\tassert((finalCFrame.Position - targetCFrame.Position).Magnitude <= CENTER_TOLERANCE, model.Name .. \" expansion recenter failed\")\n\tassert((finalSize - targetSize * EXPANSION).Magnitude <= SIZE_TOLERANCE, model.Name .. \" expansion size validation failed\")\nend\n\nlocal imports = ServerStorage:WaitForChild(\"AnimalKingdomTownNativeMaterialImports\", 15)\nif not imports then\n\twarn(\"[AK_TownVisualRuntime] Town material imports are absent; existing authored visuals preserved\")\n\treturn\nend\nlocal stagingFolder = Instance.new(\"Folder\")\nstagingFolder.Name = RUNTIME_FOLDER_NAME\n\nlocal totalMeshParts = 0\nlocal preparedModels = {}\n\n-- Build and validate every overlay before replacing the previous runtime folder.\nfor _, spec in SPECS do\n\tlocal canonical = resolvePath(Workspace, spec.targetPath)\n\tif not canonical or not canonical:IsA(\"Model\") or not canonical:FindFirstChildWhichIsA(\"BasePart\", true) then\n\t\twarn(\"[AK_TownVisualRuntime] Skipping absent or empty canonical model: \" .. spec.name)\n\t\tcontinue\n\tend\n\tlocal source = imports:FindFirstChild(spec.sourceName)\n\tassert(source and source:IsA(\"Model\"), \"AK_TownVisualRuntime missing native source Model \" .. spec.sourceName)\n\n\tlocal canonicalCFrame, canonicalSize = canonical:GetBoundingBox()\n\n\tlocal sourceParts = sourceMeshParts(source)\n\tassert(#sourceParts == spec.expectedParts, string.format(\"%s expected %d source MeshParts, found %d\", spec.name, spec.expectedParts, #sourceParts))\n\n\tlocal visual = Instance.new(\"Model\")\n\tvisual.Name = spec.name\n\tlocal seenRoles = {}\n\tfor _, sourcePart in sourceParts do\n\t\tassert(sourcePart.MeshId ~= \"\", spec.name .. \" has an empty source MeshId: \" .. sourcePart.Name)\n\t\tlocal role = semanticRole(sourcePart.Name, spec.palette)\n\t\tassert(role, spec.name .. \" has an unknown semantic MeshPart: \" .. sourcePart.Name)\n\t\tassert(not seenRoles[role], spec.name .. \" has duplicate semantic role: \" .. role)\n\t\tseenRoles[role] = true\n\n\t\tlocal roleStyle = spec.palette[role]\n\t\tlocal part = sourcePart:Clone()\n\t\tpart.Color = roleStyle.color\n\t\tpart.Material = roleStyle.material\n\t\tpart.Anchored = true\n\t\tpart.CanCollide = false\n\t\tpart.CanTouch = false\n\t\tpart.CanQuery = false\n\t\tpart.Parent = visual\n\tend\n\n\tlocal roleCount = 0\n\tfor _ in seenRoles do\n\t\troleCount += 1\n\tend\n\tassert(roleCount == spec.expectedParts, string.format(\"%s expected %d distinct semantic roles, found %d\", spec.name, spec.expectedParts, roleCount))\n\n\talignBoundingBox(visual, canonicalCFrame, canonicalSize)\n\tvisual:SetAttribute(\"AK_RuntimeTownVisual\", true)\n\tvisual.Parent = stagingFolder\n\ttotalMeshParts += #sourceParts\n\ttable.insert(preparedModels, { name = spec.name, parts = #sourceParts })\nend\n\nif #preparedModels == 0 then\n\tstagingFolder:Destroy()\n\treturn\nend\n\nlocal previousRuntime = Workspace:FindFirstChild(RUNTIME_FOLDER_NAME)\nif previousRuntime then\n\tpreviousRuntime:Destroy()\nend\nstagingFolder.Parent = Workspace\n\nfor _, result in preparedModels do\n\tprint(string.format(\"AK VISUAL CREATED | %s | Parts=%d\", result.name, result.parts))\nend\nprint(\"ANIMAL KINGDOM TOWN VISUALS READY\")\nprint(string.format(\"[AK_TownVisualRuntime] Prepared %d valid overlays / %d MeshParts\", #preparedModels, totalMeshParts))\n"}, {"path": ["ServerScriptService", "PlotLocator"], "source": "-- Shared runtime map lookup for plot assignment and the admin plot camera.\nlocal PlotLocator = {}\nlocal CONTAINERS = { \"PlayerPlots\", \"AnimalKingdomPlayerPlots\", \"Plots\", \"AnimalKingdomFuturePlayerPlots\" }\nlocal cachedContainer\n\n-- The admin status board reads plots every second. Rediscover only when map\n-- containers change instead of walking the entire decorated world each tick.\nlocal function invalidateContainer(instance)\n\tif table.find(CONTAINERS, instance.Name)\n\t\tor (instance.Parent and table.find(CONTAINERS, instance.Parent.Name)) then\n\t\tcachedContainer = nil\n\tend\nend\nworkspace.DescendantAdded:Connect(invalidateContainer)\nworkspace.DescendantRemoving:Connect(invalidateContainer)\n\nlocal function validPlot(instance)\n\tif not (instance:IsA(\"Model\") or instance:IsA(\"BasePart\")) then return false end\n\tif instance:IsA(\"SpawnLocation\") then return false end\n\tif instance:IsA(\"Model\") and not instance:FindFirstChildWhichIsA(\"BasePart\", true) then return false end\n\tif instance:GetAttribute(\"Feature\") == \"PlayerPlot\" then return true end\n\t-- The live folder contains sibling Plot1Floor, Plot1Fence, Plot1Spawn,\n\t-- and Plot1PetDisplay objects. Only the actual plot is an ownership slot.\n\treturn instance.Name:match(\"^Plot[%s_%-]*%d+$\") ~= nil\n\t\tor instance.Name:match(\"^Plot[%s_%-]*%d+Floor$\") ~= nil\n\t\tor instance.Name:match(\"^PlayerPlot[%s_%-]*%d+$\") ~= nil\n\t\tor instance.Name:match(\"^PlayerPlot[%s_%-]*%d+Floor$\") ~= nil\nend\n\nfunction PlotLocator.getContainer()\n\tif cachedContainer and cachedContainer:IsDescendantOf(workspace) and table.find(CONTAINERS, cachedContainer.Name) then\n\t\tfor _, child in ipairs(cachedContainer:GetChildren()) do\n\t\t\tif validPlot(child) then return cachedContainer end\n\t\tend\n\tend\n\tcachedContainer = nil\n\tlocal found = {}\n\tfor _, candidate in ipairs(workspace:GetDescendants()) do\n\t\tif (candidate:IsA(\"Folder\") or candidate:IsA(\"Model\")) and table.find(CONTAINERS, candidate.Name) then\n\t\t\tfor _, child in ipairs(candidate:GetChildren()) do\n\t\t\t\tif validPlot(child) then\n\t\t\t\t\tfound[candidate.Name] = found[candidate.Name] or candidate\n\t\t\t\t\tbreak\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tfor _, name in ipairs(CONTAINERS) do\n\t\tif found[name] then cachedContainer = found[name]; return cachedContainer end\n\tend\nend\n\nfunction PlotLocator.getPlots()\n\tlocal container = PlotLocator.getContainer()\n\tlocal plots = {}\n\tif container then\n\t\tfor _, child in ipairs(container:GetChildren()) do\n\t\t\tif validPlot(child) then table.insert(plots, child) end\n\t\tend\n\tend\n\ttable.sort(plots, function(a, b)\n\t\tlocal ai = tonumber(a.Name:match(\"%d+\")) or math.huge\n\t\tlocal bi = tonumber(b.Name:match(\"%d+\")) or math.huge\n\t\treturn ai == bi and a.Name < b.Name or ai < bi\n\tend)\n\treturn plots\nend\n\nfunction PlotLocator.getBounds(instance)\n\tif instance:IsA(\"BasePart\") then return instance.CFrame, instance.Size end\n\tif instance:IsA(\"Model\") and instance:FindFirstChildWhichIsA(\"BasePart\", true) then\n\t\treturn instance:GetBoundingBox()\n\tend\nend\n\nfunction PlotLocator.getCollectionBounds()\n\tlocal low, high\n\tfor _, plot in ipairs(PlotLocator.getPlots()) do\n\t\tlocal cf, size = PlotLocator.getBounds(plot)\n\t\tif cf then\n\t\t\tlocal half = size * 0.5\n\t\t\tfor _, x in ipairs({ -half.X, half.X }) do\n\t\t\t\tfor _, y in ipairs({ -half.Y, half.Y }) do\n\t\t\t\t\tfor _, z in ipairs({ -half.Z, half.Z }) do\n\t\t\t\t\t\tlocal point = cf:PointToWorldSpace(Vector3.new(x, y, z))\n\t\t\t\t\t\tlow = low and Vector3.new(math.min(low.X, point.X), math.min(low.Y, point.Y), math.min(low.Z, point.Z)) or point\n\t\t\t\t\t\thigh = high and Vector3.new(math.max(high.X, point.X), math.max(high.Y, point.Y), math.max(high.Z, point.Z)) or point\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tif low then return CFrame.new((low + high) * 0.5), high - low end\nend\n\nfunction PlotLocator.getTown()\n\treturn workspace:FindFirstChild(\"AnimalKingdomTown\")\nend\n\nreturn PlotLocator\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "AdminCommandService"], "source": "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\nlocal HttpService = game:GetService(\"HttpService\")\nlocal TextService = game:GetService(\"TextService\")\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\nlocal Definitions = require(ReplicatedStorage.Shared.AdminCommandDefinitions)\nlocal Events = require(ReplicatedStorage.Shared.EventDefinitions)\nlocal modules = ServerScriptService.AdminCommandCenter\nlocal Policy = require(modules.RequestPolicy)\nlocal PlotStatus = require(modules.PlotStatus)\nlocal Teleports = require(modules.Teleports)\nlocal RoomPanels = require(modules.RoomPanels)\nlocal ActivityLog = require(modules.ActivityLog)\n\nlocal Service = Knit.CreateService({Name=\"AdminCommandService\", Client={}})\nlocal WeatherAdmin, Weather\nlocal requestRemote, responseRemote, stateRemote, announcementRemote, cameraRemote\nlocal activity = ActivityLog.new(Definitions.ActivityLimit)\nlocal pending, busy, lastAnnouncement, roomPresence, spectators, respawning = {}, {}, {}, {}, {}, {}\nlocal announcementBusy = false\nlocal lastBroadcast = -math.huge\nlocal startedAt = workspace:GetServerTimeNow() - time()\nlocal destinationNames = {}\nfor _, destination in ipairs(Definitions.Destinations) do destinationNames[destination.Id] = destination.DisplayName end\n\nlocal function reply(player, message, ok)\n\tif player.Parent == Players then responseRemote:FireClient(player, {Kind=\"Result\", Message=message, Success=ok == true}) end\nend\n\nlocal function record(player, message)\n\tactivity:Add(player, message)\nend\n\nlocal function stopSpectating(admin, reason)\n\tlocal session = spectators[admin]\n\tif not session then return end\n\tspectators[admin] = nil\n\tif session.Connection then session.Connection:Disconnect() end\n\tif session.Root then pcall(admin.RemoveReplicationFocus, admin, session.Root) end\n\trecord(admin, \"stopped spectating \" .. session.Target.Name)\n\tif admin.Parent == Players then responseRemote:FireClient(admin, {Kind=\"SpectateStop\", Reason=reason}) end\nend\n\nlocal function startSpectating(admin, target)\n\tif admin == target then reply(admin, \"SELECT ANOTHER PLAYER\", false); return end\n\tlocal character = target.Character\n\tlocal root = character and character:FindFirstChild(\"HumanoidRootPart\")\n\tlocal humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n\tif not root or not root:IsA(\"BasePart\") or not humanoid or humanoid.Health <= 0 then reply(admin, \"TARGET CHARACTER NOT READY\", false); return end\n\tstopSpectating(admin)\n\tlocal session = {Target=target, Root=root}\n\tspectators[admin] = session\n\t-- Keep the distant subject replicated while the admin remains in the room.\n\tlocal focusOk = pcall(admin.AddReplicationFocus, admin, root)\n\tif workspace.StreamingEnabled and not focusOk then\n\t\tspectators[admin] = nil\n\t\treply(admin, \"SPECTATE STREAMING UNAVAILABLE\", false)\n\t\treturn\n\tend\n\tsession.Connection = target.CharacterRemoving:Connect(function() stopSpectating(admin, \"Target respawned\") end)\n\tcameraRemote:FireClient(admin, \"Close\")\n\tresponseRemote:FireClient(admin, {Kind=\"SpectateStart\", TargetUserId=target.UserId, Position=root.Position})\n\trecord(admin, \"started spectating \" .. target.Name)\nend\n\nlocal function confirmation(player, payload, title)\n\tlocal token = HttpService:GenerateGUID(false)\n\tpending[player] = {Token=token, Payload=table.clone(payload), Expires=os.clock()+Definitions.ConfirmationLifetime, QueueRevision=Weather.QueueRevision}\n\tresponseRemote:FireClient(player, {Kind=\"Confirm\", Token=token, Title=title, Lifetime=Definitions.ConfirmationLifetime})\nend\n\nlocal function sendState(player, roster, plots)\n\tstateRemote:FireClient(player, {\n\t\tAuthorized=true, InRoom=WeatherAdmin:IsInsideRoom(player), Players=roster, MaxPlayers=Players.MaxPlayers,\n\t\tServerStartedAt=startedAt, Plots=plots, Weather=Weather:GetCurrentState(), Activity=activity:Snapshot(),\n\t})\nend\n\nlocal function snapshot()\n\tlocal plotInfo, plots = PlotStatus.GetSnapshot()\n\tlocal roster = {}\n\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\tlocal plot = PlotStatus.GetPlayerPlot(player, plots)\n\t\ttable.insert(roster, {Username=player.Name, DisplayName=player.DisplayName, UserId=player.UserId, Plot=plot and plot.Name or \"\"})\n\tend\n\ttable.sort(roster, function(a,b) return a.Username:lower() < b.Username:lower() end)\n\treturn roster, plotInfo\nend\n\nlocal function broadcastAnnouncement(player, raw)\n\tlocal message = Policy.SanitizeMessage(raw, Definitions.MaxAnnouncementCharacters)\n\tif not message then reply(player, \"ENTER A MESSAGE OF 1\u2013150 CHARACTERS\", false); return end\n\tlocal now = os.clock()\n\tif announcementBusy or now-lastBroadcast < 2 or (lastAnnouncement[player] and now-lastAnnouncement[player] < 5) then\n\t\treply(player, \"PLEASE WAIT BEFORE SENDING ANOTHER ANNOUNCEMENT\", false)\n\t\treturn\n\tend\n\tlastAnnouncement[player] = now\n\tannouncementBusy = true\n\tlocal ok, filtered = pcall(function()\n\t\tlocal result = TextService:FilterStringAsync(message, player.UserId, Enum.TextFilterContext.PublicChat)\n\t\treturn result:GetNonChatStringForBroadcastAsync()\n\tend)\n\tannouncementBusy = false\n\tif not ok or type(filtered) ~= \"string\" or not filtered:match(\"%S\") then\n\t\treply(player, \"TEXT FILTER UNAVAILABLE \u2014 announcement was not sent\", false)\n\t\treturn\n\tend\n\t-- Filtering yields. Revalidate authority and membership before broadcasting.\n\tif player.Parent ~= Players or not WeatherAdmin:IsAuthorized(player) or not WeatherAdmin:IsInsideRoom(player) then return end\n\tlastBroadcast = os.clock()\n\tlocal formattedMessage = string.format('[Admin] \"%s\": \"%s\"', player.Name, filtered)\n\tannouncementRemote:FireAllClients({Message=formattedMessage})\n\trecord(player, formattedMessage)\n\tprint(formattedMessage)\n\treply(player, \"ANNOUNCEMENT SENT\", true)\nend\n\nlocal function execute(player, payload, confirmed)\n\tlocal action = payload.Action\n\tif action == \"GetState\" then sendState(player, snapshot()); return end\n\tif action == \"StopSpectating\" then stopSpectating(player); return end\n\tif action == \"Teleport\" and payload.Destination == \"AdminRoom\" then\n\t\tlocal ok, reason = Teleports.ToDestination(player, \"AdminRoom\", WeatherAdmin)\n\t\tif ok then stopSpectating(player); record(player, \"teleported to Admin Room\") end\n\t\treply(player, ok and \"RETURNED TO ADMIN ROOM\" or reason, ok)\n\t\treturn\n\tend\n\tif not WeatherAdmin:IsInsideRoom(player) then reply(player, \"RETURN TO ADMIN ROOM TO USE THIS CONTROL\", false); return end\n\tif action == \"Confirm\" then\n\t\tlocal request = pending[player]\n\t\tpending[player] = nil\n\t\tif not request or request.Token ~= payload.Token or os.clock() > request.Expires then reply(player, \"CONFIRMATION EXPIRED\", false); return end\n\t\tif request.Payload.Action == \"QueueEvent\" and request.QueueRevision ~= Weather.QueueRevision then\n\t\t\treply(player, \"QUEUE CHANGED \u2014 select the event again\", false)\n\t\t\treturn\n\t\tend\n\t\texecute(player, request.Payload, true)\n\t\treturn\n\tend\n\tif action == \"Announce\" then broadcastAnnouncement(player, payload.Message); return end\n\tif action == \"QueueEvent\" then\n\t\tif not confirmed and Weather.QueuedEventId ~= \"\" then\n\t\t\tconfirmation(player, payload, \"REPLACE \" .. Events[Weather.QueuedEventId].DisplayName:upper() .. \" WITH \" .. Events[payload.EventId].DisplayName:upper() .. \"?\")\n\t\t\treturn\n\t\tend\n\t\tif Weather:QueueEvent(payload.EventId) then\n\t\t\trecord(player, \"queued \" .. Events[payload.EventId].DisplayName)\n\t\t\treply(player, \"EVENT QUEUED \u2014 current event continues\", true)\n\t\tend\n\t\treturn\n\tend\n\tif action == \"ClearQueue\" then\n\t\tWeather:ClearQueue()\n\t\trecord(player, \"cleared event queue\")\n\t\treply(player, \"QUEUE CLEARED\", true)\n\t\treturn\n\tend\n\tif action == \"EmergencyReset\" then\n\t\tif not confirmed then confirmation(player, payload, \"RESET WEATHER?\\nEnds the event, clears the queue, and resumes the normal cycle.\"); return end\n\t\tWeather:EmergencyReset()\n\t\trecord(player, \"performed emergency weather reset\")\n\t\treply(player, \"WEATHER RESET \u2014 normal cycle resumed\", true)\n\t\treturn\n\tend\n\tif action == \"Teleport\" then\n\t\tlocal ok, reason = Teleports.ToDestination(player, payload.Destination, WeatherAdmin)\n\t\tif ok then\n\t\t\tstopSpectating(player)\n\t\t\tcameraRemote:FireClient(player, \"Close\")\n\t\t\trecord(player, \"teleported to \" .. destinationNames[payload.Destination])\n\t\tend\n\t\treply(player, ok and \"TELEPORTED\" or reason, ok)\n\t\treturn\n\tend\n\tlocal target = Players:GetPlayerByUserId(payload.TargetUserId)\n\tif not target or target.Parent ~= Players then reply(player, \"PLAYER LEFT THE SERVER\", false); return end\n\tif action == \"SpectatePlayer\" then startSpectating(player,target); return end\n\tif action == \"RespawnPlayer\" then\n\t\tif not confirmed then confirmation(player, payload, \"RESPAWN \" .. target.Name .. \"?\"); return end\n\t\tif respawning[target] then reply(player, \"PLAYER IS ALREADY RESPAWNING\", false); return end\n\t\trespawning[target] = true\n\t\tlocal ok = pcall(target.LoadCharacterAsync, target)\n\t\trespawning[target] = nil\n\t\tif ok then record(player, \"respawned \" .. target.Name) end\n\t\treply(player, ok and \"PLAYER RESPAWNED\" or \"RESPAWN FAILED \u2014 try again\", ok)\n\t\treturn\n\tend\n\tlocal ok, reason, message\n\tif action == \"TeleportToPlayer\" then\n\t\tok, reason = Teleports.ToPlayer(player, target)\n\t\tmessage = \"teleported to \" .. target.Name\n\telseif action == \"TeleportToPlot\" then\n\t\tok, reason = Teleports.ToPlot(player, target)\n\t\tmessage = \"teleported to \" .. target.Name .. \"'s plot\"\n\telseif action == \"ReturnPlayerToPlot\" then\n\t\tok, reason = Teleports.ToPlot(target, target)\n\t\tmessage = \"returned \" .. target.Name .. \" to their plot\"\n\telseif action == \"BringPlayer\" then\n\t\tif player == target then reply(player, \"SELECT ANOTHER PLAYER\", false); return end\n\t\tok, reason = Teleports.ToPlayer(target, player)\n\t\tmessage = \"brought \" .. target.Name .. \" to Admin Room\"\n\tend\n\tif ok then\n\t\trecord(player, message)\n\t\tif action == \"TeleportToPlayer\" or action == \"TeleportToPlot\" or player == target then\n\t\t\tstopSpectating(player)\n\t\t\tcameraRemote:FireClient(player, \"Close\")\n\t\tend\n\tend\n\treply(player, ok and \"ACTION COMPLETE\" or reason or \"ACTION UNAVAILABLE\", ok)\nend\n\nfunction Service:KnitInit()\n\tWeatherAdmin = Knit.GetService(\"WeatherAdminService\")\n\tWeather = Knit.GetService(\"WeatherEventService\")\nend\n\nfunction Service:KnitStart()\n\tReplicatedStorage:WaitForChild(\"WeatherState\")\n\tlocal remotes = ReplicatedStorage:WaitForChild(\"AnimalKingdomRemotes\")\n\tcameraRemote = remotes:WaitForChild(\"AdminCameraControl\")\n\tlocal function remote(name)\n\t\tlocal object = remotes:FindFirstChild(name)\n\t\tif not object then object = Instance.new(\"RemoteEvent\"); object.Name=name; object.Parent=remotes end\n\t\tassert(object:IsA(\"RemoteEvent\"), name .. \" must be a RemoteEvent\")\n\t\treturn object\n\tend\n\trequestRemote = remote(\"AdminCommandRequest\")\n\tresponseRemote = remote(\"AdminCommandResponse\")\n\tstateRemote = remote(\"AdminCommandState\")\n\tannouncementRemote = remote(\"GlobalAnnouncement\")\n\tlocal validate, forget = Policy.new(function(player) return WeatherAdmin:IsAuthorized(player) end, Definitions, Events)\n\trequestRemote.OnServerEvent:Connect(function(player, payload, ...)\n\t\tif busy[player] or not validate(player, payload, ...) then return end\n\t\t-- Group authorization may yield; another accepted request can become\n\t\t-- active before validation resumes.\n\t\tif busy[player] or player.Parent ~= Players then return end\n\t\tbusy[player] = true\n\t\tlocal ok, err = pcall(execute, player, payload, false)\n\t\tbusy[player] = nil\n\t\tif not ok then\n\t\t\twarn(\"[AdminCommand] Request failed: \" .. tostring(err))\n\t\t\treply(player, \"ACTION FAILED \u2014 please try again\", false)\n\t\tend\n\tend)\n\tWeatherAdmin.ActionRecorded.Event:Connect(record)\n\t-- A Phase 1 camera selection ends spectating without changing that controller.\n\tcameraRemote.OnServerEvent:Connect(function(player, command)\n\t\tif (command == \"Select\" or command == \"Exit\") and WeatherAdmin:IsAuthorized(player) then stopSpectating(player) end\n\tend)\n\tlocal function watch(player)\n\t\tplayer.CharacterRemoving:Connect(function() stopSpectating(player, \"Admin respawned\"); pending[player] = nil end)\n\tend\n\tPlayers.PlayerAdded:Connect(watch)\n\tfor _, player in ipairs(Players:GetPlayers()) do watch(player) end\n\tPlayers.PlayerRemoving:Connect(function(player)\n\t\tif roomPresence[player] then record(player, \"left Admin Room (disconnected)\") end\n\t\tstopSpectating(player)\n\t\tfor admin, session in pairs(spectators) do if session.Target == player then stopSpectating(admin, \"Player left the server\") end end\n\t\tpending[player], busy[player], lastAnnouncement[player], roomPresence[player], respawning[player] = nil,nil,nil,nil,nil\n\t\tforget(player)\n\tend)\n\ttask.spawn(function()\n\t\tlocal currentRoom\n\t\twhile true do\n\t\t\tlocal room = workspace:FindFirstChild(\"WeatherAdminRoom\")\n\t\t\tif room and room ~= currentRoom and room:FindFirstChild(\"BackWall\") then\n\t\t\t\tlocal panels, issue = RoomPanels.Attach(room)\n\t\t\t\tif panels then currentRoom=room else warn(\"[AdminCommand] \" .. issue); currentRoom=room end\n\t\t\tend\n\t\t\tlocal roster, plots = snapshot()\n\t\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\t\tif WeatherAdmin:IsAuthorized(player) then\n\t\t\t\t\tlocal inside = WeatherAdmin:IsInsideRoom(player)\n\t\t\t\t\tif inside ~= (roomPresence[player] == true) then\n\t\t\t\t\t\trecord(player, inside and \"entered Admin Room\" or \"left Admin Room\")\n\t\t\t\t\t\troomPresence[player] = inside\n\t\t\t\t\tend\n\t\t\t\t\tif not inside then stopSpectating(player, \"Left Admin Room\"); pending[player] = nil end\n\t\t\t\t\tsendState(player, roster, plots)\n\t\t\t\telse\n\t\t\t\t\tstopSpectating(player, \"Authorization changed\")\n\t\t\t\t\tpending[player] = nil\n\t\t\t\t\tstateRemote:FireClient(player, {Authorized=false})\n\t\t\t\tend\n\t\t\tend\n\t\t\ttask.wait(1)\n\t\tend\n\tend)\nend\n\nreturn Service\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "NumNomService"], "source": "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\nlocal Database = require(ReplicatedStorage.SharedSource.Datas.NumNomDatabase)\nlocal Guard = require(script.Parent.Parent.Utilities.GameplayGuard)\n\nlocal NumNomService = Knit.CreateService({ Name = \"NumNomService\", Client = {} })\nlocal DataService\nlocal CurrencyService\nlocal activeById = {}\nlocal random = Random.new()\nlocal biomeSpacing = 160\nlocal biomeSlots = {\n\tVector2.new(-1.5, -1.5), Vector2.new(-0.5, -1.5), Vector2.new(0.5, -1.5), Vector2.new(1.5, -1.5),\n\tVector2.new(1.5, -0.5), Vector2.new(1.5, 0.5), Vector2.new(1.5, 1.5), Vector2.new(0.5, 1.5),\n\tVector2.new(-0.5, 1.5), Vector2.new(-1.5, 1.5), Vector2.new(-1.5, 0.5), Vector2.new(-1.5, -0.5),\n}\n\nfunction NumNomService:Collect(player, instance)\n\tif not Guard.RateLimit(player, \"NumNom\", 0.75) or not Guard.IsNear(player, instance, 16) then return false end\n\tlocal id = instance:GetAttribute(\"NumNomId\")\n\tlocal definition = type(id) == \"string\" and Database[id]\n\tlocal data = DataService:Get(player)\n\tif not definition or not data or not data.UnlockedBiomes[definition.Biome] then return false end\n\tlocal index = table.clone(data.NumNomIndex)\n\tlocal firstDiscovery = not index[id]\n\tindex[id] = (index[id] or 0) + 1\n\tDataService:Set(player, \"NumNomIndex\", index)\n\tCurrencyService:Add(player, \"FriendshipTokens\", definition.FriendshipTokens)\n\tif firstDiscovery then\n\t\tlocal decorations = table.clone(data.UnlockedDecorations)\n\t\tdecorations[definition.UnlockId] = true\n\t\tDataService:Set(player, \"UnlockedDecorations\", decorations)\n\tend\n\tactiveById[instance] = nil\n\tinstance:Destroy()\n\treturn true\nend\n\nfunction NumNomService:SpawnOne()\n\tlocal totalWeight = 0\n\tfor _, candidate in pairs(Database) do totalWeight += candidate.SpawnWeight end\n\tlocal roll = random:NextInteger(1, totalWeight)\n\tlocal definition\n\tfor _, candidate in pairs(Database) do\n\t\troll -= candidate.SpawnWeight\n\t\tif roll <= 0 then definition = candidate break end\n\tend\n\tif not definition then return end\n\tlocal runtime = workspace:FindFirstChild(\"World\") and workspace.World:FindFirstChild(\"Runtime\")\n\tif not runtime then return end\n\tlocal object = Instance.new(\"Part\")\n\tobject.Name = definition.NumNomId\n\tobject.Shape = Enum.PartType.Ball\n\tobject.Size = Vector3.new(2.5, 2.5, 2.5)\n\tobject.Anchored = true\n\tlocal blockout = workspace.World:FindFirstChild(\"BiomeBlockout\")\n\tlocal biomeModel = blockout and blockout:FindFirstChild(definition.Biome)\n\tlocal platform = biomeModel and biomeModel:FindFirstChild(\"Platform\")\n\tif platform then\n\t\tobject.Position = platform.Position + Vector3.new(\n\t\t\trandom:NextNumber(-platform.Size.X * 0.4, platform.Size.X * 0.4),\n\t\t\t3,\n\t\t\trandom:NextNumber(-platform.Size.Z * 0.4, platform.Size.Z * 0.4)\n\t\t)\n\telse\n\t\tlocal biomeIndex = 1\n\t\tfor index, biome in ipairs(require(ReplicatedStorage.SharedSource.Datas.AnimalKingdomConfig).Biomes) do\n\t\t\tif biome.Id == definition.Biome then biomeIndex = index break end\n\t\tend\n\t\tlocal slot = biomeSlots[biomeIndex]\n\t\tobject.Position = Vector3.new(\n\t\t\tslot.X * biomeSpacing + random:NextNumber(-60, 60),\n\t\t\t2,\n\t\t\tslot.Y * biomeSpacing + random:NextNumber(-60, 60)\n\t\t)\n\tend\n\tobject.Color = Color3.fromRGB(255, 153, 204)\n\tobject:SetAttribute(\"NumNomId\", definition.NumNomId)\n\tobject:SetAttribute(\"BiomeId\", definition.Biome)\n\tobject.Parent = runtime\n\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\tprompt.ActionText = \"Befriend\"\n\tprompt.ObjectText = definition.Name\n\tprompt.MaxActivationDistance = 12\n\tprompt.Parent = object\n\tprompt.Triggered:Connect(function(player) self:Collect(player, object) end)\n\tactiveById[object] = true\nend\n\nfunction NumNomService:KnitStart()\n\t-- The authored map replaces the old blockout coordinates. Do not populate\n\t-- future gameplay with prototype spheres unless a developer opts in.\n\tfor _, biome in ipairs(require(ReplicatedStorage.SharedSource.Datas.AnimalKingdomConfig).Biomes) do\n\t\tlocal region = workspace:FindFirstChild(biome.Id)\n\t\tlocal floor = region and region:FindFirstChild(biome.Id .. \"Floor\")\n\t\tif floor and floor:IsA(\"BasePart\") and workspace:GetAttribute(\"AK_EnableLegacyGameplayScaffold\") ~= true then\n\t\t\tprint(\"[NumNomService] Prototype world spawns disabled for authored map\")\n\t\t\treturn\n\t\tend\n\tend\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(5)\n\t\t\tlocal count = 0\n\t\t\tfor object in pairs(activeById) do if object.Parent then count += 1 else activeById[object] = nil end end\n\t\t\tif count < math.max(12, #Players:GetPlayers() * 6) then self:SpawnOne() end\n\t\tend\n\tend)\nend\n\nfunction NumNomService:KnitInit()\n\tDataService = Knit.GetService(\"PlayerDataService\")\n\tCurrencyService = Knit.GetService(\"CurrencyService\")\nend\n\nreturn NumNomService\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "ProfileService"], "source": "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\n\nlocal Signal = require(ReplicatedStorage.Packages.Signal)\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\n\nlocal ProfileService = Knit.CreateService({\n\tName = \"ProfileService\",\n\tClient = {\n\t\tGetData = Knit.CreateSignal(),\n\n\t\t--[[\n\t\t\t@description Use this for client to reduce network receive data, this updates DataController.Data\n\t\t\n\t\t\tNote: If you use :Connect() and want to retrieve updated data, ensure to add a task.wait() \n\t\t\tat least for the DataController.Data to update.\n\t\t]]\n\t\tUpdateSpecificData = Knit.CreateSignal(),\n\t},\n\n\tUpdateSpecificData = Signal.new(),\n})\n\nlocal ActualProfileStore =\n\trequire(ServerScriptService:WaitForChild(\"ServerSource\"):WaitForChild(\"Externals\"):WaitForChild(\"ProfileStore\"))\nlocal ProfileTemplate = require(ReplicatedStorage.SharedSource.Datas.ProfileTemplate)\nlocal AnimalKingdomConfig = require(ReplicatedStorage.SharedSource.Datas.AnimalKingdomConfig)\nlocal PetDatabase = require(ReplicatedStorage.SharedSource.Datas.PetDatabase)\nlocal MutationDatabase = require(ReplicatedStorage.SharedSource.Datas.MutationDatabase)\n\nlocal PlayerProfileStore\n\nlocal Profiles = {} -- [player] = profile\nlocal Loading = {}\nlocal DataRequestPending, LastDataRequest = {}, {}\nlocal LOAD_TIMEOUT = 120\nProfileService.Profiles = Profiles\n\nlocal function nonNegativeInteger(value)\n\tif type(value) ~= \"number\" or value ~= value or math.abs(value) == math.huge then return 0 end\n\treturn math.max(0, math.floor(value))\nend\n\nlocal function NormalizeAnimalKingdomData(data)\n\tdata.ForestCoins = nonNegativeInteger(data.ForestCoins)\n\tdata.FriendshipTokens = nonNegativeInteger(data.FriendshipTokens)\n\tdata.OwnedPets = type(data.OwnedPets) == \"table\" and data.OwnedPets or {}\n\tdata.DisplayedPetIds = type(data.DisplayedPetIds) == \"table\" and data.DisplayedPetIds or {}\n\tdata.UnlockedBiomes = type(data.UnlockedBiomes) == \"table\" and data.UnlockedBiomes or { Meadow = true }\n\tdata.UnlockedBiomes.Meadow = true\n\tlocal validOwned = {}\n\tlocal ownedIds = {}\n\tfor _, owned in ipairs(data.OwnedPets) do\n\t\tif type(owned) == \"table\" and type(owned.UniquePetId) == \"string\" and not ownedIds[owned.UniquePetId]\n\t\t\tand PetDatabase[owned.PetId] and MutationDatabase[owned.Mutation] then\n\t\t\townedIds[owned.UniquePetId] = true\n\t\t\ttable.insert(validOwned, owned)\n\t\tend\n\tend\n\tdata.OwnedPets = validOwned\n\tlocal validDisplayed = {}\n\tlocal seen = {}\n\tfor _, uniqueId in ipairs(data.DisplayedPetIds) do\n\t\tif #validDisplayed >= AnimalKingdomConfig.MaxDisplayedPets then break end\n\t\tif type(uniqueId) == \"string\" and ownedIds[uniqueId] and not seen[uniqueId] then\n\t\t\tseen[uniqueId] = true\n\t\t\ttable.insert(validDisplayed, uniqueId)\n\t\tend\n\tend\n\tdata.DisplayedPetIds = validDisplayed\n\tdata.SchemaVersion = AnimalKingdomConfig.SchemaVersion\nend\n\nlocal function DataSuccessfullyLoaded(player)\n\tlocal profile = Profiles[player]\n\tif profile and profile.Data.SanctuaryIncomeUpdatedAt == 0 then\n\t\tprofile.Data.SanctuaryIncomeUpdatedAt = os.time()\n\tend\nend\n\nlocal function HandlePlayerAdded(player)\n\tif Loading[player] or Profiles[player] or not player:IsDescendantOf(Players) then return end\n\tLoading[player] = true\n\tlocal started = os.clock()\n\tlocal ok, profile = pcall(function()\n\t\treturn PlayerProfileStore:StartSessionAsync(\"Player_\" .. player.UserId, {\n\t\t\t-- Supplying Cancel replaces ProfileStore's default timeout, so retain\n\t\t\t-- a bounded load while also releasing requests for departed players.\n\t\t\tCancel = function()\n\t\t\t\treturn not player:IsDescendantOf(Players) or os.clock() - started >= LOAD_TIMEOUT\n\t\t\tend,\n\t\t})\n\tend)\n\tLoading[player] = nil\n\tif not ok then\n\t\twarn(\"[ProfileService] Load failed for \" .. player.Name .. \": \" .. tostring(profile))\n\t\tif player:IsDescendantOf(Players) then player:Kick(\"Your data could not be loaded. Please rejoin.\") end\n\t\treturn\n\tend\n\n\tif profile ~= nil then\n\t\tlocal prepared, issue = pcall(function()\n\t\t\tprofile:AddUserId(player.UserId) -- GDPR compliance\n\t\t\tprofile:Reconcile() -- Fill in missing variables from ProfileTemplate\n\t\t\tNormalizeAnimalKingdomData(profile.Data)\n\t\tend)\n\t\tif not prepared then\n\t\t\twarn(\"[ProfileService] Data preparation failed for \" .. player.Name .. \": \" .. tostring(issue))\n\t\t\tprofile:EndSession()\n\t\t\tif player:IsDescendantOf(Players) then player:Kick(\"Your data could not be prepared. Please rejoin.\") end\n\t\t\treturn\n\t\tend\n\n\t\t-- Add MetaData for backwards compatibility\n\t\tif not profile.MetaData then\n\t\t\tprofile.MetaData = {\n\t\t\t\tProfileCreateTime = profile.FirstSessionTime,\n\t\t\t\tSessionLoadCount = profile.SessionLoadCount,\n\t\t\t\tActiveSession = profile.Session,\n\t\t\t}\n\t\tend\n\n\t\tprofile.OnSessionEnd:Connect(function()\n\t\t\tif Profiles[player] ~= profile then return end\n\t\t\tProfiles[player] = nil\n\t\t\t-- The profile could've been loaded on another Roblox server\n\t\t\tif player:IsDescendantOf(Players) then player:Kick(\"Your data session ended. Please rejoin.\") end\n\t\tend)\n\n\t\tif player:IsDescendantOf(Players) then\n\t\t\tProfiles[player] = profile\n\t\t\tDataSuccessfullyLoaded(player)\n\t\telse\n\t\t\t-- Player left before the profile loaded\n\t\t\tprofile:EndSession()\n\t\tend\n\telse\n\t\t-- The profile couldn't be loaded possibly due to other\n\t\t-- Roblox servers trying to load this profile at the same time\n\t\tif player:IsDescendantOf(Players) then player:Kick(\"Your data could not be loaded. Please rejoin.\") end\n\tend\nend\n\nlocal function HandlePlayerRemoving(player)\n\tDataRequestPending[player], LastDataRequest[player] = nil, nil\n\tlocal profile = Profiles[player]\n\tif profile ~= nil then\n\t\t-- Clear ownership before EndSession fires its callback. Normal departures\n\t\t-- must not be treated as a stolen session.\n\t\tProfiles[player] = nil\n\t\tprofile:EndSession()\n\tend\nend\n\nfunction ProfileService:WaitUntilProfileLoaded(player)\n\twhile not Profiles[player] and player:IsDescendantOf(Players) do\n\t\ttask.wait(0.1)\n\tend\nend\n\nfunction ProfileService:GetProfile(player)\n\tif player == nil then\n\t\twarn(\"Player instance is nil when getting profile\")\n\t\treturn nil\n\tend\n\n\tif not Profiles[player] then\n\t\tProfileService:WaitUntilProfileLoaded(player)\n\tend\n\n\tlocal profile = Profiles[player]\n\treturn profile, profile and profile.Data\nend\n\nfunction ProfileService:ChangeData(player, redirectories, newValue)\n\tlocal profile, profileData = ProfileService:GetProfile(player)\n\n\tif not profileData then\n\t\twarn(\"Profile data not found for player: \" .. (player.Name or \"Unknown\"))\n\t\treturn\n\tend\n\n\tlocal directData = profileData\n\n\t-- Navigate through the redirectories path\n\tfor i = 1, #redirectories do\n\t\tif not directData[redirectories[i]] and i ~= #redirectories then\n\t\t\tlocal redirectoriesPath = \"profileData\"\n\t\t\tfor j = 1, i do\n\t\t\t\tredirectoriesPath = redirectoriesPath .. \".\" .. redirectories[j]\n\t\t\tend\n\t\t\terror(\n\t\t\t\t\"'\"\n\t\t\t\t\t.. redirectoriesPath\n\t\t\t\t\t.. \"' table does not exist. ALWAYS PREVENT THIS BY MAKING TABLES INSIDE PROFILETEMPLATE.\"\n\t\t\t)\n\t\t\treturn\n\t\tend\n\n\t\tif i ~= #redirectories then\n\t\t\tdirectData = directData[redirectories[i]]\n\t\tend\n\tend\n\n\t-- Set the new value\n\tdirectData[redirectories[#redirectories]] = newValue\n\n\t-- Fire update signals\n\tProfileService.Client.UpdateSpecificData:Fire(player, redirectories, newValue)\n\tProfileService.UpdateSpecificData:Fire(player, redirectories, newValue)\nend\n\nfunction ProfileService.Client:GetOtherPlayer_ProfileData(player, otherPlayer)\n\tif typeof(otherPlayer) ~= \"Instance\" or not otherPlayer:IsA(\"Player\") or not otherPlayer:IsDescendantOf(Players) then\n\t\treturn nil\n\tend\n\tlocal _, profileData = ProfileService:GetProfile(otherPlayer)\n\tif not profileData then return nil end\n\treturn {\n\t\tPetIndex = profileData.PetIndex,\n\t\tNumNomIndex = profileData.NumNomIndex,\n\t}\nend\n\nfunction ProfileService.Client:GetProfileAge(player)\n\tlocal profile = ProfileService:GetProfile(player)\n\tif not profile then\n\t\treturn 0\n\tend\n\n\tlocal profileAge = os.time() - profile.FirstSessionTime\n\treturn profileAge\nend\n\nfunction ProfileService:KnitStart()\n\t-- Subscribe before taking the snapshot; Loading also guards duplicate starts.\n\tPlayers.PlayerAdded:Connect(HandlePlayerAdded)\n\tPlayers.PlayerRemoving:Connect(HandlePlayerRemoving)\n\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\ttask.spawn(HandlePlayerAdded, player)\n\tend\n\n\t-- Handle client data requests\n\tProfileService.Client.GetData:Connect(function(player)\n\t\tlocal now = os.clock()\n\t\tif DataRequestPending[player] or (LastDataRequest[player] and now - LastDataRequest[player] < 1) then return end\n\t\tDataRequestPending[player], LastDataRequest[player] = true, now\n\t\tProfileService:WaitUntilProfileLoaded(player)\n\t\tlocal _, profileData = ProfileService:GetProfile(player)\n\t\tDataRequestPending[player] = nil\n\t\tif profileData and player:IsDescendantOf(Players) then ProfileService.Client.GetData:Fire(player, profileData) end\n\tend)\nend\n\nfunction ProfileService:KnitInit()\n\tPlayerProfileStore = ActualProfileStore.New(\"OriginalData1\", ProfileTemplate)\nend\n\nreturn ProfileService\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "WeatherAdminService"], "source": "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal GroupService = game:GetService(\"GroupService\")\nlocal TextChatService = game:GetService(\"TextChatService\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\nlocal EventDefinitions = require(ReplicatedStorage.Shared.EventDefinitions)\nlocal CameraDefinitions = require(ReplicatedStorage.Shared.AdminCameraDefinitions)\nlocal PlotLocator = require(game:GetService(\"ServerScriptService\").PlotLocator)\nlocal Teleports = require(game:GetService(\"ServerScriptService\").AdminCommandCenter.Teleports)\n\n-- Add numeric UserIds here. The experience creator is authorized automatically.\nlocal ADMIN_USER_IDS = {\n\t-- [123456789] = true,\n}\nlocal ADMIN_GROUP_ID = 0 -- Optional; 0 disables group-rank authorization.\nlocal MIN_ADMIN_GROUP_RANK = 255\nlocal ACTION_COOLDOWN = 0.35\nlocal ROOM_CENTER = Vector3.new(0, 25000, 0)\nlocal ROOM_WIDTH, ROOM_DEPTH, ROOM_HEIGHT = 170, 106, 40\n\nlocal WeatherAdminService = Knit.CreateService({ Name = \"WeatherAdminService\", Client = {} })\n-- Server-only integration: all admin tools use this service's existing policy.\nWeatherAdminService.ActionRecorded = Instance.new(\"BindableEvent\")\nlocal WeatherEventService\nlocal weatherState\nlocal room\nlocal boardState\nlocal boardFeedback\nlocal actionRemote\nlocal cameraRemote\nlocal lastAction = {}\nlocal lastCameraAction = {}\nlocal returnCFrames = {}\nlocal groupOwnerResolved = false\nlocal groupOwnerId\nlocal lastGroupOwnerCheck\nlocal eventIndicators = {}\nlocal eventActiveLabels = {}\nlocal indicatedEventId\n\nlocal normalOrder = {\n\t\"SunnySkies\", \"RainyDay\", \"Thunderstorm\", \"Snowfall\", \"Foggy\", \"Windy\",\n\t\"Heatwave\", \"Aurora\", \"BloodMoon\", \"MeteorShower\", \"SpiritNight\", \"Rainbow\",\n}\nlocal secretOrder = { \"Chaos\", \"Inverted\", \"Nightmare\", \"Void\", \"Golden\", \"AdminAbuse\" }\nlocal eventColors = {\n\tSunnySkies = Color3.fromRGB(244, 194, 76), RainyDay = Color3.fromRGB(74, 162, 220),\n\tThunderstorm = Color3.fromRGB(72, 91, 178), Snowfall = Color3.fromRGB(157, 221, 240),\n\tFoggy = Color3.fromRGB(136, 158, 173), Windy = Color3.fromRGB(117, 194, 160),\n\tHeatwave = Color3.fromRGB(247, 133, 71), Aurora = Color3.fromRGB(118, 116, 236),\n\tBloodMoon = Color3.fromRGB(203, 69, 82), MeteorShower = Color3.fromRGB(242, 144, 91),\n\tSpiritNight = Color3.fromRGB(91, 194, 198), Rainbow = Color3.fromRGB(203, 124, 232),\n\tChaos = Color3.fromRGB(245, 92, 175), Inverted = Color3.fromRGB(89, 222, 190),\n\tNightmare = Color3.fromRGB(142, 52, 99), Void = Color3.fromRGB(112, 70, 177),\n\tGolden = Color3.fromRGB(255, 201, 58), AdminAbuse = Color3.fromRGB(230, 107, 241),\n}\n\nlocal function isAuthorized(player)\n\tif not player or not player:IsA(\"Player\") or not player:IsDescendantOf(Players) then return false end\n\tlocal userId = player.UserId\n\tif ADMIN_USER_IDS[userId] then return true end\n\tif game.CreatorType == Enum.CreatorType.User and game.CreatorId == userId then return true end\n\tif game.CreatorType == Enum.CreatorType.Group then\n\t\tif not groupOwnerResolved and (not lastGroupOwnerCheck or os.clock() - lastGroupOwnerCheck >= 30) then\n\t\t\tlastGroupOwnerCheck = os.clock()\n\t\t\tlocal ok, info = pcall(GroupService.GetGroupInfoAsync, GroupService, game.CreatorId)\n\t\t\tif ok and type(info) == \"table\" then\n\t\t\t\tgroupOwnerResolved = true\n\t\t\t\tif type(info.Owner) == \"table\" then groupOwnerId = info.Owner.Id end\n\t\t\tend\n\t\tend\n\t\tif groupOwnerId == userId then return true end\n\tend\n\tif ADMIN_GROUP_ID > 0 then\n\t\tlocal ok, rank = pcall(player.GetRankInGroup, player, ADMIN_GROUP_ID)\n\t\tif ok and rank >= MIN_ADMIN_GROUP_RANK then return true end\n\tend\n\treturn false\nend\n\nlocal function makePart(name, size, cframe, tint, material)\n\tlocal part = Instance.new(\"Part\")\n\tpart.Name = name\n\tpart.Size = size\n\tpart.CFrame = cframe\n\tpart.Anchored = true\n\tpart.CanCollide = true\n\tpart.Material = material or Enum.Material.SmoothPlastic\n\tpart.Color = tint\n\tpart.TopSurface = Enum.SurfaceType.Smooth\n\tpart.BottomSurface = Enum.SurfaceType.Smooth\n\tpart.Parent = room\n\treturn part\nend\n\nlocal function makeAccent(name, size, cframe, tint)\n\tlocal part = makePart(name, size, cframe, tint, Enum.Material.Neon)\n\tpart.CanCollide = false\n\tpart.CanTouch = false\n\treturn part\nend\n\nlocal function makeText(part, name, value, tint, textSize, face)\n\t-- A pixel density preserves the physical face's aspect ratio, including\n\t-- top-facing pads (X/Z). A fixed 900x300 canvas stretched these labels.\n\tlocal surface = Instance.new(\"SurfaceGui\")\n\tsurface.Name = name .. \"Surface\"\n\tsurface.Face = face or Enum.NormalId.Front\n\tsurface.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n\tsurface.PixelsPerStud = name == \"Active\" and 24 or (name == \"Readout\" and 16 or 12)\n\tsurface.LightInfluence = 0\n\tsurface.Parent = part\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Name = name\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = 1\n\tlabel.Text = value\n\tlabel.TextColor3 = tint\n\tlabel.TextStrokeColor3 = Color3.fromRGB(8, 11, 22)\n\tlabel.TextStrokeTransparency = 1\n\tlabel.TextScaled = false\n\tlabel.TextSize = textSize or 24\n\tlabel.TextWrapped = name == \"Readout\" or name == \"KingdomMark\" or value:find(\"\\n\", 1, true) ~= nil or surface.Face == Enum.NormalId.Top\n\tlabel.Font = (name == \"Title\" or name == \"KingdomMark\") and Enum.Font.GothamBold or Enum.Font.GothamMedium\n\tlabel.TextXAlignment = name == \"Readout\" and Enum.TextXAlignment.Left or Enum.TextXAlignment.Center\n\tlabel.TextYAlignment = Enum.TextYAlignment.Center\n\tlabel.RichText = false\n\tlabel.Parent = surface\n\tlocal padding = Instance.new(\"UIPadding\")\n\tpadding.PaddingLeft = UDim.new(0, 8)\n\tpadding.PaddingRight = UDim.new(0, 8)\n\tpadding.PaddingTop = UDim.new(0, 4)\n\tpadding.PaddingBottom = UDim.new(0, 4)\n\tpadding.Parent = label\n\treturn label\nend\n\nlocal function facingCenter(position)\n\treturn CFrame.lookAt(position, Vector3.new(ROOM_CENTER.X, position.Y, ROOM_CENTER.Z))\nend\n\nlocal function feedback(message, button)\n\tif boardFeedback then boardFeedback.Text = message end\n\tif button and button.Parent then\n\t\tlocal originalColor = button.Color\n\t\tlocal originalCFrame = button.CFrame\n\t\tTweenService:Create(button, TweenInfo.new(0.12, Enum.EasingStyle.Quad), {\n\t\t\tColor = originalColor:Lerp(Color3.new(1, 1, 1), 0.55),\n\t\t\tCFrame = originalCFrame * (button:GetAttribute(\"PressDown\") and CFrame.new(0, -0.2, 0) or CFrame.new(0, 0, 0.2)),\n\t\t}):Play()\n\t\ttask.delay(0.13, function()\n\t\t\tif button.Parent then\n\t\t\t\tTweenService:Create(button, TweenInfo.new(0.17, Enum.EasingStyle.Quad), {\n\t\t\t\t\tColor = originalColor, CFrame = originalCFrame,\n\t\t\t\t}):Play()\n\t\t\tend\n\t\tend)\n\tend\nend\n\nlocal function getRoot(player)\n\tlocal character = player.Character\n\tlocal humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n\tlocal root = character and character:FindFirstChild(\"HumanoidRootPart\")\n\tif not humanoid or humanoid.Health <= 0 or not root then return nil end\n\treturn root\nend\n\nlocal function isInsideRoom(player)\n\tlocal root = getRoot(player)\n\tif not root then return false end\n\tlocal relative = root.Position - ROOM_CENTER\n\treturn math.abs(relative.X) < ROOM_WIDTH / 2 - 3\n\t\tand relative.Y > -2 and relative.Y < ROOM_HEIGHT - 2\n\t\tand math.abs(relative.Z) < ROOM_DEPTH / 2 - 3\nend\n\nlocal function normalSpawnCFrame(player)\n\tlocal plotId = player and player:GetAttribute(\"PlotId\")\n\tif plotId then\n\t\tfor _, plot in ipairs(PlotLocator.getPlots()) do\n\t\t\tif plot.Name == plotId then\n\t\t\t\tlocal marker = plot:FindFirstChild(\"PlotSpawn\", true)\n\t\t\t\tif marker and marker:IsA(\"BasePart\") then return marker.CFrame * CFrame.new(0, 3, 0) end\n\t\t\tend\n\t\tend\n\tend\n\tlocal spawn = workspace:FindFirstChild(\"MeadowSpawn\", true)\n\tif spawn and spawn:IsA(\"BasePart\") then return spawn.CFrame + Vector3.new(0, 5, 0) end\n\tlocal anySpawn = workspace:FindFirstChildWhichIsA(\"SpawnLocation\", true)\n\tif anySpawn then return anySpawn.CFrame + Vector3.new(0, 5, 0) end\n\treturn CFrame.new(0, 8, 0)\nend\n\nlocal function enterRoom(player)\n\tlocal root = getRoot(player)\n\tif not root then return false end\n\tlocal returnFrame = returnCFrames[player]\n\tif not isInsideRoom(player) then\n\t\tlocal humanoid = player.Character:FindFirstChildOfClass(\"Humanoid\")\n\t\treturnFrame = humanoid and humanoid.FloorMaterial ~= Enum.Material.Air and root.CFrame or nil\n\tend\n\tlocal moved = Teleports.Near(player, CFrame.lookAt(ROOM_CENTER + Vector3.new(0, 4.5, 36), ROOM_CENTER + Vector3.new(0, 4.5, -20)))\n\tif moved then returnCFrames[player] = returnFrame end\n\treturn moved\nend\n\nlocal function returnToGame(player)\n\tlocal root = getRoot(player)\n\tif not root then return false end\n\tlocal saved = returnCFrames[player]\n\tlocal moved = saved and Teleports.Near(player, saved) or false\n\tif not moved then moved = Teleports.ToPlot(player, player) end\n\tif not moved then moved = Teleports.Near(player, normalSpawnCFrame(player)) end\n\tif moved then\n\t\tif cameraRemote then cameraRemote:FireClient(player, \"Close\") end\n\t\treturnCFrames[player] = nil\n\tend\n\treturn moved\nend\n\nlocal function checkCooldown(player)\n\tlocal now = os.clock()\n\tlocal previous = lastAction[player]\n\tif previous and now - previous < ACTION_COOLDOWN then return false end\n\tlastAction[player] = now\n\treturn true\nend\n\nlocal function dispatch(player, action, eventId, button)\n\t-- Shared by physical prompts, chat commands, and the remote. Never trust a client payload.\n\tif not checkCooldown(player) or not isAuthorized(player) or type(action) ~= \"string\" then return end\n\tif action == \"Teleport\" then\n\t\tif enterRoom(player) then\n\t\t\tfeedback(player.DisplayName .. \" entered the weather room\", button)\n\t\t\tprint(\"[WeatherAdmin] \" .. player.Name .. \" entered admin room\")\n\t\tend\n\t\treturn\n\tend\n\tif action == \"Return\" then\n\t\tif not isInsideRoom(player) then return end\n\t\tif returnToGame(player) then\n\t\t\tfeedback(player.DisplayName .. \" returned to the kingdom\", button)\n\t\t\tprint(\"[WeatherAdmin] Returning player: \" .. player.Name)\n\t\tend\n\t\treturn\n\tend\n\tif not isInsideRoom(player) then return end\n\t-- ClickDetectors can reach every wall panel; room membership remains the boundary.\n\tif action == \"StartEvent\" then\n\t\tif type(eventId) ~= \"string\" or not EventDefinitions[eventId] then return end\n\t\tWeatherEventService:StartEvent(eventId)\n\t\tWeatherAdminService.ActionRecorded:Fire(player, \"started \" .. EventDefinitions[eventId].DisplayName)\n\t\tfeedback(\"Started \" .. EventDefinitions[eventId].DisplayName .. \" \u2022 \" .. player.DisplayName, button)\n\t\tprint(\"[WeatherAdmin] Starting event: \" .. eventId)\n\telseif action == \"RandomEvent\" then\n\t\tlocal selected = WeatherEventService:StartRandomAutomaticEvent()\n\t\tWeatherAdminService.ActionRecorded:Fire(player, \"started random event \" .. EventDefinitions[selected].DisplayName)\n\t\tfeedback(\"Random event: \" .. EventDefinitions[selected].DisplayName .. \" \u2022 \" .. player.DisplayName, button)\n\t\tprint(\"[WeatherAdmin] Random event: \" .. selected)\n\telseif action == \"EndEvent\" then\n\t\tif WeatherEventService.CurrentPhase ~= \"Event\" then return end\n\t\tWeatherEventService:EndCurrentEvent()\n\t\tWeatherAdminService.ActionRecorded:Fire(player, \"ended weather\")\n\t\tfeedback(\"Current event ended \u2022 \" .. player.DisplayName, button)\n\t\tprint(\"[WeatherAdmin] Ending current event\")\n\telseif action == \"PauseAuto\" then\n\t\tWeatherEventService:PauseAutomaticEvents()\n\t\tWeatherAdminService.ActionRecorded:Fire(player, \"paused automatic weather\")\n\t\tfeedback(\"Automatic events paused \u2022 \" .. player.DisplayName, button)\n\t\tprint(\"[WeatherAdmin] Automatic events paused\")\n\telseif action == \"ResumeAuto\" then\n\t\tWeatherEventService:ResumeAutomaticEvents()\n\t\tWeatherAdminService.ActionRecorded:Fire(player, \"resumed automatic weather\")\n\t\tfeedback(\"Automatic events resumed \u2022 \" .. player.DisplayName, button)\n\t\tprint(\"[WeatherAdmin] Automatic events resumed\")\n\tend\nend\n\nlocal function addClick(button, handler)\n\tlocal detector = Instance.new(\"ClickDetector\")\n\tdetector.MaxActivationDistance = 150\n\tdetector.Parent = button\n\tlocal baseColor = button.Color\n\tdetector.MouseHoverEnter:Connect(function(player)\n\t\tif isAuthorized(player) and isInsideRoom(player) then\n\t\t\tTweenService:Create(button, TweenInfo.new(0.12), { Color = baseColor:Lerp(Color3.new(1, 1, 1), 0.16) }):Play()\n\t\tend\n\tend)\n\tdetector.MouseHoverLeave:Connect(function()\n\t\tTweenService:Create(button, TweenInfo.new(0.12), { Color = baseColor }):Play()\n\tend)\n\tdetector.MouseClick:Connect(handler)\nend\n\nlocal function addActionClick(button, action, eventId)\n\taddClick(button, function(player)\n\t\tdispatch(player, action, eventId, button)\n\tend)\nend\n\nlocal WHITE = Color3.fromRGB(245, 248, 252)\nlocal GRAY = Color3.fromRGB(205, 218, 231)\nlocal NAVY = Color3.fromRGB(8, 24, 48)\nlocal BLUE = Color3.fromRGB(25, 125, 255)\nlocal CYAN = Color3.fromRGB(65, 210, 255)\nlocal OFF = Color3.fromRGB(49, 75, 105)\nlocal cameraAllowed = {}\nfor _, definition in ipairs(CameraDefinitions) do\n\tif type(definition.DisplayName) == \"string\" and definition.DisplayName:match(\"%S\") then\n\t\tcameraAllowed[definition.Id] = definition\n\tend\nend\nlocal refreshSpecialCamera\nlocal function selectCamera(player, id, button)\n\tif type(id) ~= \"string\" or not cameraAllowed[id] or not isAuthorized(player) or not isInsideRoom(player) then return end\n\tif refreshSpecialCamera and (id == \"PlayerPlots\" or id == \"Town\") then refreshSpecialCamera(id) end\n\tlocal folder = workspace:FindFirstChild(\"AK_AdminCameraPoints\")\n\tif not folder or not folder:FindFirstChild(id) then return end\n\tlocal now = os.clock()\n\tif lastCameraAction[player] and now - lastCameraAction[player] < 0.15 then return end\n\tlastCameraAction[player] = now\n\tcameraRemote:FireClient(player, \"Open\", id)\n\tif button then feedback(\"Viewing live camera: \" .. id, button) end\n\tprint(\"[AdminCamera] Opening camera: \" .. id)\nend\nlocal queueState\nlocal serverState\n\nlocal function roomPart(name, size, offset, color, material)\n\treturn makePart(name, size, CFrame.new(ROOM_CENTER + offset), color, material)\nend\n\nlocal function lightPart(part, brightness, range, color)\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Brightness = brightness\n\tlight.Range = range\n\tlight.Color = color\n\tlight.Parent = part\nend\n\nlocal function topLabel(part, name, value, color)\n\treturn makeText(part, name, value, color, name == \"KingdomMark\" and 34 or 20, Enum.NormalId.Top)\nend\n\nlocal function makeWallCard(name, value, position, width, accent, height)\n\theight = height or 4.9\n\tlocal direction = math.abs(position.X - ROOM_CENTER.X) > 60\n\t\tand Vector3.new(position.X < ROOM_CENTER.X and 1 or -1, 0, 0)\n\t\tor Vector3.new(0, 0, 1)\n\tlocal face = CFrame.lookAt(position, position + direction)\n\tlocal frame = makePart(name .. \"Frame\", Vector3.new(width + 1.2, height + 0.9, 0.8), face * CFrame.new(0, 0, 0.15), GRAY, Enum.Material.Metal)\n\tlocal card = makePart(name, Vector3.new(width, height, 0.5), face * CFrame.new(0, 0, -0.4), NAVY, Enum.Material.SmoothPlastic)\n\tif value then makeText(card, \"Label\", value, WHITE, 24) end\n\tlocal accentPart = makeAccent(name .. \"Accent\", Vector3.new(0.25, height - 0.3, 0.13), face * CFrame.new(-width / 2 + 0.4, 0, -0.75), accent)\n\treturn card, face, frame, accentPart\nend\n\nlocal function clearOldCameraPanels()\n\tlocal removed = 0\n\tfor _, child in ipairs(room:GetDescendants()) do\n\t\tif child.Parent and (child.Name == \"CameraWallPanels\" or (child:IsA(\"BasePart\") and child.Name:match(\"^Camera\"))) then\n\t\t\tchild:Destroy() -- Descendant UI and click detectors are destroyed with the part.\n\t\t\tremoved += 1\n\t\tend\n\tend\n\tprint(\"[WeatherAdminCamera] Old physical camera panels removed: \" .. removed)\n\treturn removed\nend\n\nlocal function createCameraPanel(definition, index, container)\n\tlocal id = definition.Id\n\tassert(type(definition.DisplayName) == \"string\" and definition.DisplayName:match(\"%S\"),\n\t\t\"Missing DisplayName for camera \" .. tostring(id))\n\tlocal col = (index - 1) % 3\n\tlocal row = math.floor((index - 1) / 3)\n\tlocal position = ROOM_CENTER + Vector3.new(-29 + col * 29, 26.2 - row * 5.5, -51.2)\n\tlocal face = CFrame.lookAt(position, position + Vector3.new(0, 0, 1))\n\tlocal frame = makePart(\"Camera\" .. id .. \"Frame\", Vector3.new(26.2, 5.2, 0.8), face * CFrame.new(0, 0, 0.15), GRAY, Enum.Material.Metal)\n\tlocal panel = makePart(\"Camera\" .. id, Vector3.new(25, 5, 0.5), face * CFrame.new(0, 0, -0.4), NAVY, Enum.Material.SmoothPlastic)\n\tlocal accent = makeAccent(\"Camera\" .. id .. \"Accent\", Vector3.new(0.25, 4.7, 0.13), face * CFrame.new(-12.1, 0, -0.75), CYAN)\n\tframe.Parent = container\n\tpanel.Parent = container\n\taccent.Parent = container\n\tpanel:SetAttribute(\"CameraId\", id)\n\tpanel:SetAttribute(\"CameraDisplayName\", definition.DisplayName)\n\taddClick(panel, function(player)\n\t\tselectCamera(player, definition.Id, panel)\n\tend)\n\tpanel:SetAttribute(\"CameraActionConnected\", true)\n\treturn panel\nend\n\nlocal CAMERA_LABELS = {\n\t\"PLAYER PLOTS\", \"TOWN\", \"MEADOW\",\n\t\"FOREST\", \"JUNGLE\", \"DESERT\",\n\t\"SNOW\", \"VOLCANO\", \"OCEAN\",\n\t\"ANCIENT RUINS\", \"MAGICAL FOREST\", \"SKY\",\n\t\"PREHISTORIC\", \"MYTHICAL\", \"HIGH OVERVIEW\",\n}\nlocal function attachCameraLabels()\n\tlocal container = room:FindFirstChild(\"CameraWallPanels\")\n\tassert(container, \"Existing camera wall panels missing\")\n\tlocal panels = {}\n\tfor _, child in ipairs(container:GetChildren()) do\n\t\tif child:IsA(\"BasePart\") and child:FindFirstChildOfClass(\"ClickDetector\") then\n\t\t\ttable.insert(panels, child)\n\t\tend\n\tend\n\tassert(#panels == 15, string.format(\"Expected 15 existing camera panels; found %d\", #panels))\n\ttable.sort(panels, function(a, b)\n\t\tif math.abs(a.Position.Y - b.Position.Y) > 1 then return a.Position.Y > b.Position.Y end\n\t\treturn a.Position.X < b.Position.X\n\tend)\n\tlocal playerPlotsSurface = panels[1]:FindFirstChildWhichIsA(\"SurfaceGui\")\n\tlocal visibleFace = playerPlotsSurface and playerPlotsSurface.Face or Enum.NormalId.Front\n\tlocal surfaceCount, labelCount = 0, 0\n\tfor index, panel in ipairs(panels) do\n\t\tfor _, child in ipairs(panel:GetChildren()) do\n\t\t\tif child:IsA(\"SurfaceGui\") or child:IsA(\"BillboardGui\") then\n\t\t\t\tchild:Destroy()\n\t\t\tend\n\t\tend\n\t\tlocal surface = Instance.new(\"SurfaceGui\")\n\t\tsurface.Name = \"CameraNameSurface_NEW\"\n\t\tsurface.Adornee = panel\n\t\tsurface.Parent = panel\n\t\tsurface.Face = visibleFace\n\t\tsurface.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n\t\tsurface.PixelsPerStud = 12\n\t\tsurface.AlwaysOnTop = true\n\t\tsurface.LightInfluence = 0\n\t\tsurface.Enabled = true\n\t\tsurfaceCount += 1\n\t\tlocal label = Instance.new(\"TextLabel\")\n\t\tlabel.Name = \"CameraName_NEW\"\n\t\tlabel.Text = CAMERA_LABELS[index]\n\t\tlabel.Size = UDim2.fromScale(1, 1)\n\t\tlabel.Position = UDim2.fromScale(0, 0)\n\t\tlabel.BackgroundTransparency = 1\n\t\tlabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n\t\tlabel.TextStrokeColor3 = Color3.fromRGB(0, 15, 50)\n\t\tlabel.TextStrokeTransparency = 1\n\t\tlabel.Font = Enum.Font.GothamBold\n\t\tlabel.TextScaled = false\n\t\tlabel.TextSize = 24\n\t\tlabel.TextWrapped = false\n\t\tlabel.TextXAlignment = Enum.TextXAlignment.Center\n\t\tlabel.TextYAlignment = Enum.TextYAlignment.Center\n\t\tlabel.Visible = true\n\t\tlabel.ZIndex = 50\n\t\tlabel.Parent = surface\n\t\tlabelCount += 1\n\t\tlocal padding = Instance.new(\"UIPadding\")\n\t\tpadding.PaddingLeft = UDim.new(0, 10)\n\t\tpadding.PaddingRight = UDim.new(0, 10)\n\t\tpadding.Parent = label\n\tend\n\tassert(surfaceCount == 15 and labelCount == 15, \"Camera label creation count mismatch\")\nend\n\nlocal function eventButton(eventId, position, width, rare)\n\tlocal definition = EventDefinitions[eventId]\n\tlocal accent = rare and eventColors[eventId]:Lerp(BLUE, 0.45) or BLUE\n\tlocal button, face = makeWallCard(eventId .. \"Button\", definition.DisplayName, position, width, accent)\n\tlocal indicator = makeAccent(eventId .. \"ActiveIndicator\", Vector3.new(0.9, 0.9, 0.18), face * CFrame.new(width / 2 - 1.2, 0, -0.78), OFF)\n\teventIndicators[eventId] = indicator\n\tlocal activeTag = makePart(eventId .. \"ActiveTag\", Vector3.new(5.5, 1.25, 0.15), face * CFrame.new(width / 2 - 3.6, -1.55, -0.79), NAVY)\n\teventActiveLabels[eventId] = makeText(activeTag, \"Active\", \"ACTIVE\", OFF, 16)\n\taddActionClick(button, \"StartEvent\", eventId)\nend\n\nlocal function biomeRegion(id)\n\t-- Match BiomeTeleport.Landing.FindFloor: live top-level regions take priority\n\t-- over the Rojo blockout when a Studio place contains both.\n\tlocal liveRegion = workspace:FindFirstChild(id)\n\tif liveRegion then return liveRegion end\n\tlocal world = workspace:FindFirstChild(\"World\")\n\tlocal regions = world and (world:FindFirstChild(\"BiomeBlockout\") or world:FindFirstChild(\"Biomes\"))\n\treturn regions and regions:FindFirstChild(id)\nend\n\nlocal function regionBounds(region)\n\tif region:IsA(\"Model\") then return region:GetBoundingBox() end\n\tlocal low, high\n\tfor _, descendant in ipairs(region:GetDescendants()) do\n\t\tif descendant:IsA(\"BasePart\") then\n\t\t\tlocal p, half = descendant.Position, descendant.Size * 0.5\n\t\t\tlocal a, b = p - half, p + half\n\t\t\tlow = low and Vector3.new(math.min(low.X, a.X), math.min(low.Y, a.Y), math.min(low.Z, a.Z)) or a\n\t\t\thigh = high and Vector3.new(math.max(high.X, b.X), math.max(high.Y, b.Y), math.max(high.Z, b.Z)) or b\n\t\tend\n\tend\n\tif low then return CFrame.new((low + high) * 0.5), high - low end\nend\n\nlocal function findAnchor(region)\n\tfor _, name in ipairs({ \"CameraAnchor\", \"CameraPoint\", \"BiomeCenter\", \"TeleportPoint\", \"TeleportSpawn\", \"SpawnPoint\", \"Entrance\", \"Center\" }) do\n\t\tlocal anchor = region:FindFirstChild(name, true)\n\t\tif anchor and anchor:IsA(\"BasePart\") then return anchor end\n\tend\nend\n\nlocal function clearView(position, target, ignored)\n\tlocal params = RaycastParams.new()\n\tparams.FilterType = Enum.RaycastFilterType.Exclude\n\tparams.FilterDescendantsInstances = ignored\n\tlocal overlap = OverlapParams.new()\n\toverlap.FilterType = Enum.RaycastFilterType.Exclude\n\toverlap.FilterDescendantsInstances = ignored\n\tfor _, part in ipairs(workspace:GetPartBoundsInBox(CFrame.new(position), Vector3.new(5, 5, 5), overlap)) do\n\t\tif part.CanCollide and part.Transparency < 0.95 then return false end\n\tend\n\tlocal direction = target - position\n\tlocal hit = workspace:Raycast(position, direction, params)\n\treturn not hit or (hit.Position - target).Magnitude < 22\nend\n\nlocal function cameraCFrame(target, size, ignored)\n\tlocal span = math.max(size.X, size.Z)\n\tlocal back = math.max(44, span * 0.48)\n\tlocal height = math.max(28, size.Y * 0.7 + span * 0.36)\n\tlocal position = target + Vector3.new(back * 0.18, height, back)\n\tfor _ = 1, 4 do\n\t\tif clearView(position, target, ignored) then break end\n\t\tposition += Vector3.new(0, math.max(14, span * 0.12), back * 0.08)\n\tend\n\treturn CFrame.lookAt(position, target)\nend\n\nlocal function setCameraPoint(folder, id, displayName, cframe, target)\n\tlocal point = folder:FindFirstChild(id)\n\tif not point then\n\t\tpoint = Instance.new(\"Part\")\n\t\tpoint.Name = id\n\t\tpoint.Parent = folder\n\tend\n\tpoint.Size = Vector3.new(1, 1, 1)\n\tpoint.CFrame = cframe\n\tpoint.Anchored = true\n\tpoint.CanCollide = false\n\tpoint.CanTouch = false\n\tpoint.CanQuery = false\n\tpoint.Transparency = 1\n\tpoint:SetAttribute(\"DisplayName\", displayName)\n\tpoint:SetAttribute(\"TargetCenter\", target)\n\tprint(\"[AdminCamera] Camera point created: \" .. id .. \" target \" .. tostring(target))\nend\n\nrefreshSpecialCamera = function(id)\n\tlocal folder = workspace:FindFirstChild(\"AK_AdminCameraPoints\")\n\tif not folder then return false end\n\tif id == \"PlayerPlots\" then\n\t\tlocal box, size = PlotLocator.getCollectionBounds()\n\t\tif not box then return false end\n\t\tlocal target = box.Position\n\t\tsetCameraPoint(folder, id, cameraAllowed[id].DisplayName, cameraCFrame(target, size * 1.45, { folder, room }), target)\n\t\treturn true\n\telseif id == \"Town\" then\n\t\tlocal town = PlotLocator.getTown()\n\t\t-- The inspected live place keeps TownPlaza beside the town Folder.\n\t\tlocal plaza = workspace:FindFirstChild(\"TownPlaza\") or (town and town:FindFirstChild(\"TownPlaza\", true))\n\t\tlocal box, size\n\t\tif plaza and plaza:IsA(\"BasePart\") then\n\t\t\tbox, size = PlotLocator.getBounds(plaza)\n\t\telseif town then\n\t\t\tbox, size = regionBounds(town)\n\t\tend\n\t\tif not box then return false end\n\t\tlocal target = box.Position\n\t\tsetCameraPoint(folder, id, cameraAllowed[id].DisplayName, cameraCFrame(target, size, { folder, room }), target)\n\t\treturn true\n\tend\n\treturn false\nend\n\nlocal function makeCameraPoints()\n\tlocal folder = workspace:FindFirstChild(\"AK_AdminCameraPoints\")\n\tif not folder then\n\t\tfolder = Instance.new(\"Folder\")\n\t\tfolder.Name = \"AK_AdminCameraPoints\"\n\t\tfolder.Parent = workspace\n\tend\n\tfor _, child in ipairs(folder:GetChildren()) do\n\t\tif not cameraAllowed[child.Name] then child:Destroy() end\n\tend\n\t-- WorldService can populate gameplay objects after this service starts.\n\ttask.spawn(function()\n\t\tlocal missing = {}\n\t\tfor _, camera in ipairs(CameraDefinitions) do\n\t\t\tif camera.Target == \"Biome\" and cameraAllowed[camera.Id] then missing[camera.Id] = camera end\n\t\tend\n\t\tlocal plotsDone, townDone, highDone = false, false, false\n\t\tfor attempt = 1, 30 do\n\t\t\tlocal overallLow, overallHigh\n\t\t\tfor _, camera in ipairs(CameraDefinitions) do\n\t\t\t\tif camera.Target ~= \"Biome\" or not cameraAllowed[camera.Id] then continue end\n\t\t\t\tlocal region = biomeRegion(camera.Id)\n\t\t\t\tif region then\n\t\t\t\t\tlocal box, size = regionBounds(region)\n\t\t\t\t\tif box and size then\n\t\t\t\t\t\tlocal center = box.Position\n\t\t\t\t\t\tlocal half = size * 0.5\n\t\t\t\t\t\tlocal a, b = center - half, center + half\n\t\t\t\t\t\toverallLow = overallLow and Vector3.new(math.min(overallLow.X, a.X), math.min(overallLow.Y, a.Y), math.min(overallLow.Z, a.Z)) or a\n\t\t\t\t\t\toverallHigh = overallHigh and Vector3.new(math.max(overallHigh.X, b.X), math.max(overallHigh.Y, b.Y), math.max(overallHigh.Z, b.Z)) or b\n\t\t\t\t\t\tif missing[camera.Id] then\n\t\t\t\t\t\t\tlocal anchor = findAnchor(region)\n\t\t\t\t\t\t\tlocal target = anchor and anchor.Position or center\n\t\t\t\t\t\t\tsetCameraPoint(folder, camera.Id, camera.DisplayName, cameraCFrame(target, size, { folder, room }), target)\n\t\t\t\t\t\t\tmissing[camera.Id] = nil\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\tif not plotsDone then\n\t\t\t\tplotsDone = refreshSpecialCamera(\"PlayerPlots\")\n\t\t\tend\n\t\t\tif not townDone then\n\t\t\t\ttownDone = refreshSpecialCamera(\"Town\")\n\t\t\tend\n\t\t\tif not highDone and overallLow and overallHigh then\n\t\t\t\tlocal center = (overallLow + overallHigh) * 0.5\n\t\t\t\tlocal size = overallHigh - overallLow\n\t\t\t\tsetCameraPoint(folder, \"HighOverview\", cameraAllowed.HighOverview.DisplayName, cameraCFrame(center, size, { folder, room }), center)\n\t\t\t\thighDone = true\n\t\t\tend\n\t\t\tif plotsDone and townDone and highDone and next(missing) == nil then break end\n\t\t\ttask.wait(2)\n\t\tend\n\t\tfor id in pairs(missing) do warn(\"[AdminCamera] Missing biome region for camera: \" .. id) end\n\t\tif not plotsDone then warn(\"[AdminCamera] Existing player plots not found; PlayerPlots camera unavailable\") end\n\t\tif not townDone then warn(\"[AdminCamera] AnimalKingdomTown not found; Town camera unavailable\") end\n\tend)\nend\n\nlocal function buildRoom()\n\tlocal existing = workspace:FindFirstChild(\"WeatherAdminRoom\")\n\tassert(not existing, \"WeatherAdminRoom already exists; refusing to overwrite an existing room\")\n\troom = Instance.new(\"Model\")\n\troom.Name = \"WeatherAdminRoom\"\n\troom.Parent = workspace\n\troomPart(\"Floor\", Vector3.new(ROOM_WIDTH, 2, ROOM_DEPTH), Vector3.new(0, -1, 0), WHITE, Enum.Material.Marble)\n\troomPart(\"Ceiling\", Vector3.new(ROOM_WIDTH, 2, ROOM_DEPTH), Vector3.new(0, ROOM_HEIGHT + 1, 0), WHITE, Enum.Material.SmoothPlastic)\n\tfor _, side in ipairs({ -1, 1 }) do\n\t\troomPart(side < 0 and \"LeftWall\" or \"RightWall\", Vector3.new(2, ROOM_HEIGHT, ROOM_DEPTH), Vector3.new(side * 85, 20, 0), WHITE, Enum.Material.SmoothPlastic)\n\t\troomPart(\"WallLowerPanel\", Vector3.new(1, 4, 102), Vector3.new(side * 83.7, 2, 0), GRAY, Enum.Material.Metal)\n\t\tmakeAccent(\"WallRecessLine\", Vector3.new(0.18, 0.25, 96), CFrame.new(ROOM_CENTER + Vector3.new(side * 83.1, 35.5, 0)), BLUE)\n\t\tmakeAccent(\"FloorEdge\", Vector3.new(0.25, 0.13, 95), CFrame.new(ROOM_CENTER + Vector3.new(side * 77, 0.1, 0)), CYAN)\n\t\tfor _, z in ipairs({ -48, 0, 48 }) do\n\t\t\troomPart(\"ArchitecturalColumn\", Vector3.new(3, 35, 3), Vector3.new(side * 81, 18, z), WHITE, Enum.Material.Marble)\n\t\t\tmakeAccent(\"ColumnInset\", Vector3.new(0.18, 27, 0.25), CFrame.new(ROOM_CENTER + Vector3.new(side * 79.3, 18, z)), BLUE)\n\t\tend\n\tend\n\troomPart(\"FrontWall\", Vector3.new(ROOM_WIDTH, ROOM_HEIGHT, 2), Vector3.new(0, 20, -53), WHITE, Enum.Material.SmoothPlastic)\n\troomPart(\"BackWall\", Vector3.new(ROOM_WIDTH, ROOM_HEIGHT, 2), Vector3.new(0, 20, 53), WHITE, Enum.Material.SmoothPlastic)\n\tfor _, x in ipairs({ -65, -33, 0, 33, 65 }) do\n\t\troomPart(\"CeilingBay\", Vector3.new(21, 0.5, 76), Vector3.new(x, 39.65, 0), GRAY, Enum.Material.Metal)\n\t\tmakeAccent(\"BlueCeilingStrip\", Vector3.new(0.22, 0.1, 76), CFrame.new(ROOM_CENTER + Vector3.new(x + 11, 39.35, 0)), BLUE)\n\t\tfor _, z in ipairs({ -29, 0, 29 }) do\n\t\t\tlocal fixture = roomPart(\"CircularCeilingLight\", Vector3.new(7, 0.25, 7), Vector3.new(x, 39.2, z), WHITE, Enum.Material.SmoothPlastic)\n\t\t\tfixture.Shape = Enum.PartType.Cylinder\n\t\t\tlocal glow = makeAccent(\"CircularLightInset\", Vector3.new(5.6, 0.12, 5.6), CFrame.new(ROOM_CENTER + Vector3.new(x, 39.02, z)), WHITE)\n\t\t\tglow.Shape = Enum.PartType.Cylinder\n\t\t\tlightPart(glow, 0.75, 32, WHITE)\n\t\tend\n\tend\n\tfor _, z in ipairs({ -46, 46 }) do\n\t\tmakeAccent(\"FloorCrossStrip\", Vector3.new(148, 0.08, 0.25), CFrame.new(ROOM_CENTER + Vector3.new(0, 0.04, z)), BLUE)\n\tend\n\tlocal floorCircle = roomPart(\"AnimalKingdomFloorMedallion\", Vector3.new(38, 0.12, 38), Vector3.new(0, 0.08, 36), WHITE, Enum.Material.Marble)\n\tfloorCircle.Shape = Enum.PartType.Cylinder\n\tlocal ring = roomPart(\"MedallionBlueRing\", Vector3.new(34, 0.13, 34), Vector3.new(0, 0.16, 36), BLUE, Enum.Material.Metal)\n\tring.Shape = Enum.PartType.Cylinder\n\tlocal middle = roomPart(\"MedallionCenter\", Vector3.new(31, 0.14, 31), Vector3.new(0, 0.23, 36), WHITE, Enum.Material.Marble)\n\tmiddle.Shape = Enum.PartType.Cylinder\n\ttopLabel(middle, \"KingdomMark\", \"ANIMAL KINGDOM\", NAVY)\n\n\t-- Event consoles sit inside framed navy wall recesses. Clicks use the existing dispatcher.\n\tfor _, side in ipairs({ -1, 1 }) do\n\t\tlocal frame = makePart(\"EventConsoleFrame\", Vector3.new(94, 34, 1.1), facingCenter(ROOM_CENTER + Vector3.new(side * 82.9, 20, 0)), GRAY, Enum.Material.Metal)\n\t\tframe.CanCollide = false\n\t\tlocal display = makePart(\"EventConsoleDisplay\", Vector3.new(91, 31.5, 0.5), frame.CFrame * CFrame.new(0, 0, -0.8), NAVY, Enum.Material.SmoothPlastic)\n\t\tdisplay.CanCollide = false\n\t\tmakeAccent(\"EventConsoleHeaderRule\", Vector3.new(86, 0.16, 0.12), display.CFrame * CFrame.new(0, 12.1, -0.34), side < 0 and BLUE or Color3.fromRGB(153, 113, 239))\n\tend\n\tlocal normalHeader = makePart(\"NormalHeader\", Vector3.new(45, 3, 0.3), facingCenter(ROOM_CENTER + Vector3.new(-81.8, 34, 0)), NAVY)\n\tmakeText(normalHeader, \"Title\", \"NORMAL EVENTS\", WHITE, 28)\n\tfor index, id in ipairs(normalOrder) do\n\t\tlocal column = (index - 1) % 3\n\t\tlocal row = math.floor((index - 1) / 3)\n\t\teventButton(id, ROOM_CENTER + Vector3.new(-81.1, 27 - row * 7.2, -30 + column * 30), 26, false)\n\tend\n\tlocal rareHeader = makePart(\"RareHeader\", Vector3.new(45, 3, 0.3), facingCenter(ROOM_CENTER + Vector3.new(81.8, 34, 0)), NAVY)\n\tmakeText(rareHeader, \"Title\", \"RARE EVENTS\", WHITE, 28)\n\tfor index, id in ipairs(secretOrder) do\n\t\tlocal column = (index - 1) % 2\n\t\tlocal row = math.floor((index - 1) / 2)\n\t\teventButton(id, ROOM_CENTER + Vector3.new(81.1, 25 - row * 9, -22 + column * 44), 37, true)\n\tend\n\n\tlocal brand = makePart(\"KingdomBrand\", Vector3.new(92, 7, 0.5), facingCenter(ROOM_CENTER + Vector3.new(0, 36, -51.5)), WHITE, Enum.Material.Marble)\n\tmakeText(brand, \"Title\", \"ANIMAL KINGDOM\\nWEATHER CONTROL CENTER\", NAVY, 34)\n\tmakeAccent(\"BrandUnderline\", Vector3.new(90, 0.2, 0.2), brand.CFrame * CFrame.new(0, -3.8, -0.35), BLUE)\n\tlocal cameraHeader = makePart(\"LiveCameraHeader\", Vector3.new(65, 3, 0.5), facingCenter(ROOM_CENTER + Vector3.new(0, 30.5, -51.6)), NAVY)\n\tmakeText(cameraHeader, \"Title\", \"LIVE MAP CAMERAS\", WHITE, 28)\n\tclearOldCameraPanels()\n\tlocal cameraContainer = Instance.new(\"Model\")\n\tcameraContainer.Name = \"CameraWallPanels\"\n\tcameraContainer.Parent = room\n\tlocal cameraPanels = {}\n\tassert(#CameraDefinitions == 15, \"Weather camera wall requires exactly 15 camera definitions\")\n\tfor index, definition in ipairs(CameraDefinitions) do\n\t\tlocal panel = createCameraPanel(definition, index, cameraContainer)\n\t\ttable.insert(cameraPanels, { Part = panel, Id = definition.Id, DisplayName = definition.DisplayName })\n\tend\n\tassert(#cameraPanels == 15, \"Weather camera wall did not create exactly 15 camera panels\")\n\n\t-- Raised station, recessed screens, and a deep angled control deck.\n\troomPart(\"CommandPlatform\", Vector3.new(82, 1, 33), Vector3.new(0, 0.5, 2), GRAY, Enum.Material.Marble)\n\troomPart(\"CommandStep\", Vector3.new(82, 0.5, 5), Vector3.new(0, 0.25, 21), WHITE, Enum.Material.Marble)\n\tmakeAccent(\"PlatformFrontLight\", Vector3.new(81, 0.18, 0.22), CFrame.new(ROOM_CENTER + Vector3.new(0, 1.05, -14.5)), BLUE)\n\troomPart(\"ConsolePedestal\", Vector3.new(76, 4.5, 17), Vector3.new(0, 3.3, 1), WHITE, Enum.Material.SmoothPlastic)\n\troomPart(\"ConsoleTop\", Vector3.new(78, 0.8, 20), Vector3.new(0, 5.9, 1), WHITE, Enum.Material.Metal)\n\tfor _, x in ipairs({ -31, 31 }) do\n\t\tlocal wedge = Instance.new(\"WedgePart\")\n\t\twedge.Name = \"AngledConsoleWing\"\n\t\twedge.Size = Vector3.new(14, 5, 18)\n\t\twedge.CFrame = CFrame.new(ROOM_CENTER + Vector3.new(x, 3.9, 1)) * CFrame.Angles(0, x < 0 and math.rad(-12) or math.rad(12), 0)\n\t\twedge.Color = WHITE\n\t\twedge.Material = Enum.Material.Metal\n\t\twedge.Anchored = true\n\t\twedge.Parent = room\n\tend\n\tmakeAccent(\"ConsoleBlueLip\", Vector3.new(78, 0.18, 0.25), CFrame.new(ROOM_CENTER + Vector3.new(0, 6.4, 11)), CYAN)\n\tmakeAccent(\"UnderConsoleLight\", Vector3.new(69, 0.2, 0.3), CFrame.new(ROOM_CENTER + Vector3.new(0, 1.1, 9.6)), BLUE)\n\tfor index, spec in ipairs({\n\t\t{ \"CurrentEventBoard\", \"CURRENT EVENT\\nLoading...\" },\n\t\t{ \"EventQueueBoard\", \"NEXT EVENT / EVENT QUEUE\\nAUTOMATIC / RANDOM\" },\n\t\t{ \"ServerStatusBoard\", \"SERVER STATUS\\nLoading...\" },\n\t}) do\n\t\tlocal x = -25 + (index - 1) * 25\n\t\troomPart(spec[1] .. \"Housing\", Vector3.new(23.5, 0.4, 8.5), Vector3.new(x, 6.45, -3.7), GRAY, Enum.Material.Metal)\n\t\tlocal screen = roomPart(spec[1], Vector3.new(22.5, 0.3, 7.5), Vector3.new(x, 6.76, -3.7), NAVY, Enum.Material.SmoothPlastic)\n\t\tlocal label = topLabel(screen, \"Readout\", spec[2], WHITE)\n\t\tif index == 1 then boardState = label elseif index == 2 then queueState = label else serverState = label end\n\t\tmakeAccent(spec[1] .. \"Indicator\", Vector3.new(20, 0.08, 0.13), CFrame.new(ROOM_CENTER + Vector3.new(x, 6.95, 0.1)), BLUE)\n\tend\n\tlocal controls = {\n\t\t{ \"RandomEvent\", \"RANDOM EVENT\", BLUE, -27 },\n\t\t{ \"EndEvent\", \"END EVENT\", Color3.fromRGB(203, 92, 99), -13.5 },\n\t\t{ \"PauseAuto\", \"PAUSE AUTO\", BLUE, 0 },\n\t\t{ \"ResumeAuto\", \"RESUME AUTO\", BLUE, 13.5 },\n\t\t{ \"Return\", \"RETURN TO GAME\", CYAN, 27 },\n\t}\n\tfor _, entry in ipairs(controls) do\n\t\tlocal x = entry[4]\n\t\troomPart(entry[1] .. \"Socket\", Vector3.new(12.4, 0.35, 5.4), Vector3.new(x, 6.5, 6), GRAY, Enum.Material.Metal)\n\t\tlocal button = roomPart(entry[1] .. \"Button\", Vector3.new(11.4, 0.55, 4.5), Vector3.new(x, 6.94, 6), entry[3], Enum.Material.SmoothPlastic)\n\t\tbutton:SetAttribute(\"PressDown\", true)\n\t\ttopLabel(button, \"Label\", entry[2], WHITE)\n\t\taddActionClick(button, entry[1])\n\tend\n\tlocal feedbackPanel = makePart(\"StatusPanel\", Vector3.new(58, 3.1, 0.5), facingCenter(ROOM_CENTER + Vector3.new(0, 10.5, 50.8)), NAVY)\n\tboardFeedback = makeText(feedbackPanel, \"Status\", \"Weather controls ready\", WHITE, 22)\n\troomPart(\"ArrivalPad\", Vector3.new(23, 0.25, 13), Vector3.new(0, 0.13, 37), GRAY, Enum.Material.Metal)\n\tmakeAccent(\"ArrivalGuide\", Vector3.new(18, 0.1, 0.25), CFrame.new(ROOM_CENTER + Vector3.new(0, 0.31, 43)), CYAN)\n\tmakeCameraPoints()\n\tprint(\"[WeatherAdmin] White and blue control center created\")\nend\n\nlocal function updateBoard()\n\tlocal phase = weatherState:GetAttribute(\"Phase\") or \"Break\"\n\tlocal eventId = phase == \"Event\" and weatherState:GetAttribute(\"EventId\") or nil\n\tif eventId ~= indicatedEventId then\n\t\tindicatedEventId = eventId\n\t\tfor id, indicator in pairs(eventIndicators) do\n\t\t\tindicator.Color = id == eventId and Color3.fromRGB(113, 255, 165)\n\t\t\t\tor eventColors[id]:Lerp(Color3.fromRGB(12, 17, 28), 0.7)\n\t\t\teventActiveLabels[id].TextColor3 = id == eventId and Color3.fromRGB(113, 255, 165) or OFF\n\t\tend\n\tend\n\tlocal eventName = weatherState:GetAttribute(\"EventName\") or \"\"\n\tlocal deadline = phase == \"Event\" and weatherState:GetAttribute(\"EndsAt\") or weatherState:GetAttribute(\"BreakEndsAt\")\n\tlocal seconds = type(deadline) == \"number\" and math.max(0, math.ceil(deadline - workspace:GetServerTimeNow())) or 0\n\tlocal timeText = string.format(\"%d:%02d\", math.floor(seconds / 60), seconds % 60)\n\tlocal automatic = weatherState:GetAttribute(\"AutomaticPaused\") and \"PAUSED\" or \"ON\"\n\tboardState.Text = string.format(\"CURRENT EVENT\\n%s\\nPhase: %s  \u2022  %s: %s\\nAutomatic Events: %s\", eventName ~= \"\" and eventName or \"None\", phase, phase == \"Event\" and \"Time Left\" or \"Break Time\", timeText, automatic)\n\tlocal queuedId = weatherState:GetAttribute(\"QueuedEventId\")\n\tlocal queued = queuedId and EventDefinitions[queuedId]\n\tqueueState.Text = \"NEXT EVENT / EVENT QUEUE\\n\" .. (queued and queued.DisplayName or \"AUTOMATIC / RANDOM\") .. \"\\nAuto events: \" .. automatic\n\tserverState.Text = string.format(\"SERVER STATUS\\nPlayers: %d\\nAuto: %s  |  Phase: %s\", #Players:GetPlayers(), automatic, phase)\nend\n\nlocal function addCommand(name, primary, secondary, action)\n\tlocal command = TextChatService:FindFirstChild(name)\n\tif not command then\n\t\tcommand = Instance.new(\"TextChatCommand\")\n\t\tcommand.Name = name\n\t\tcommand.PrimaryAlias = primary\n\t\tcommand.SecondaryAlias = secondary\n\t\tcommand.AutocompleteVisible = false\n\t\tcommand.Parent = TextChatService\n\tend\n\tassert(command:IsA(\"TextChatCommand\"), name .. \" must be a TextChatCommand\")\n\tcommand.Triggered:Connect(function(textSource)\n\t\tlocal player = Players:GetPlayerByUserId(textSource.UserId)\n\t\tif player then dispatch(player, action) end\n\tend)\nend\n\nfunction WeatherAdminService:IsAuthorized(player)\n\treturn isAuthorized(player)\nend\n\nfunction WeatherAdminService:IsInsideRoom(player)\n\treturn isInsideRoom(player)\nend\n\nfunction WeatherAdminService:EnterAdminRoom(player)\n\tif not isAuthorized(player) then return false end\n\treturn enterRoom(player)\nend\n\nfunction WeatherAdminService:KnitInit()\n\tWeatherEventService = Knit.GetService(\"WeatherEventService\")\nend\n\nfunction WeatherAdminService:KnitStart()\n\tbuildRoom()\n\tattachCameraLabels()\n\tweatherState = ReplicatedStorage:WaitForChild(\"WeatherState\")\n\tlocal remotes = ReplicatedStorage:FindFirstChild(\"AnimalKingdomRemotes\")\n\tif not remotes then\n\t\tremotes = Instance.new(\"Folder\")\n\t\tremotes.Name = \"AnimalKingdomRemotes\"\n\t\tremotes.Parent = ReplicatedStorage\n\tend\n\tassert(remotes:IsA(\"Folder\"), \"AnimalKingdomRemotes must be a Folder\")\n\tactionRemote = remotes:FindFirstChild(\"WeatherAdminAction\")\n\tif not actionRemote then\n\t\tactionRemote = Instance.new(\"RemoteEvent\")\n\t\tactionRemote.Name = \"WeatherAdminAction\"\n\t\tactionRemote.Parent = remotes\n\tend\n\tassert(actionRemote:IsA(\"RemoteEvent\"), \"WeatherAdminAction must be a RemoteEvent\")\n\tcameraRemote = remotes:FindFirstChild(\"AdminCameraControl\")\n\tif not cameraRemote then\n\t\tcameraRemote = Instance.new(\"RemoteEvent\")\n\t\tcameraRemote.Name = \"AdminCameraControl\"\n\t\tcameraRemote.Parent = remotes\n\tend\n\tassert(cameraRemote:IsA(\"RemoteEvent\"), \"AdminCameraControl must be a RemoteEvent\")\n\tcameraRemote.OnServerEvent:Connect(function(player, command, cameraId)\n\t\tif not isAuthorized(player) or not isInsideRoom(player) then return end\n\t\tif command == \"Select\" then\n\t\t\tselectCamera(player, cameraId)\n\t\telseif command == \"Exit\" then\n\t\t\tcameraRemote:FireClient(player, \"Close\")\n\t\tend\n\tend)\n\tactionRemote.OnServerEvent:Connect(function(player, payload)\n\t\tif type(payload) ~= \"table\" then return end\n\t\tdispatch(player, payload.Action, payload.EventId)\n\tend)\n\taddCommand(\"WeatherRoomCommand\", \"/weatherroom\", \"/weatheradmin\", \"Teleport\")\n\taddCommand(\"WeatherReturnCommand\", \"/return\", \"/weatherreturn\", \"Return\")\n\tPlayers.PlayerRemoving:Connect(function(player)\n\t\tlastAction[player] = nil\n\t\tlastCameraAction[player] = nil\n\t\treturnCFrames[player] = nil\n\tend)\n\tlocal function watchPlayer(player)\n\t\tplayer.CharacterAdded:Connect(function()\n\t\t\t-- Respawns use the normal game spawn; no admin-room SpawnLocation is created.\n\t\t\treturnCFrames[player] = nil\n\t\t\tcameraRemote:FireClient(player, \"Close\")\n\t\tend)\n\tend\n\tPlayers.PlayerAdded:Connect(watchPlayer)\n\tfor _, player in ipairs(Players:GetPlayers()) do watchPlayer(player) end\n\ttask.spawn(function()\n\t\twhile room.Parent do\n\t\t\tupdateBoard()\n\t\t\ttask.wait(0.5)\n\t\tend\n\tend)\nend\n\nreturn WeatherAdminService\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "WeatherEventService"], "source": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\nlocal EventDefinitions = require(ReplicatedStorage.Shared.EventDefinitions)\n\n-- Production timings apply to automatic AND administrator-started events.\n-- Fast cycles belong in the test scheduler, never in the shipped service.\nlocal TEST_MODE = false\nlocal BREAK_DURATION = 5 * 60\nlocal EVENT_DURATION = 7 * 60\n\nlocal WeatherEventService = Knit.CreateService({ Name = \"WeatherEventService\", Client = {} })\nlocal random = Random.new()\nlocal timerVersion = 0\nlocal started = false\nlocal stateFolder\n\nWeatherEventService.CurrentPhase = \"Break\"\nWeatherEventService.CurrentEventId = \"\"\nWeatherEventService.CurrentEventStartTime = 0\nWeatherEventService.CurrentEventEndTime = 0\nWeatherEventService.BreakEndTime = 0\nWeatherEventService.PreviousAutomaticEventId = nil\nWeatherEventService.AutomaticEventsPaused = false\nWeatherEventService.QueuedEventId = \"\"\nWeatherEventService.QueueRevision = 0\n\nlocal function durationFor(definition)\n\treturn definition.Duration or EVENT_DURATION\nend\n\nlocal function publishState(self)\n\t-- The folder is created before the first transition; its attributes are the join snapshot.\n\tstateFolder:SetAttribute(\"Phase\", self.CurrentPhase)\n\tstateFolder:SetAttribute(\"EventId\", self.CurrentEventId)\n\tstateFolder:SetAttribute(\"EventName\", self.CurrentEventId ~= \"\" and EventDefinitions[self.CurrentEventId].DisplayName or \"\")\n\tstateFolder:SetAttribute(\"StartedAt\", self.CurrentEventStartTime)\n\tstateFolder:SetAttribute(\"EndsAt\", self.CurrentEventEndTime)\n\tstateFolder:SetAttribute(\"BreakEndsAt\", self.BreakEndTime)\n\tstateFolder:SetAttribute(\"AutomaticPaused\", self.AutomaticEventsPaused)\n\tstateFolder:SetAttribute(\"QueuedEventId\", self.QueuedEventId)\n\tstateFolder:SetAttribute(\"QueueRevision\", self.QueueRevision)\n\tstateFolder:SetAttribute(\"TestMode\", TEST_MODE)\n\tstateFolder:SetAttribute(\"BreakDuration\", BREAK_DURATION)\n\tstateFolder:SetAttribute(\"EventDuration\", EVENT_DURATION)\nend\n\nlocal function invalidateTimer()\n\ttimerVersion += 1\n\treturn timerVersion\nend\n\nfunction WeatherEventService:OnEventStarted(_definition)\n\t-- Future server-side effects attach here.\nend\n\nfunction WeatherEventService:OnEventEnded(_definition)\n\t-- Future server-side cleanup attaches here.\nend\n\nfunction WeatherEventService:GetCurrentState()\n\treturn {\n\t\tPhase = self.CurrentPhase,\n\t\tEventId = self.CurrentEventId,\n\t\tEventName = self.CurrentEventId ~= \"\" and EventDefinitions[self.CurrentEventId].DisplayName or \"\",\n\t\tStartedAt = self.CurrentEventStartTime,\n\t\tEndsAt = self.CurrentEventEndTime,\n\t\tBreakEndsAt = self.BreakEndTime,\n\t\tAutomaticPaused = self.AutomaticEventsPaused,\n\t\tQueuedEventId = self.QueuedEventId,\n\t\tQueueRevision = self.QueueRevision,\n\t}\nend\n\nfunction WeatherEventService:SelectRandomAutomaticEvent()\n\tlocal totalWeight = 0\n\tfor id, definition in pairs(EventDefinitions) do\n\t\tif definition.IsAutomatic and id ~= self.PreviousAutomaticEventId and definition.Weight > 0 then\n\t\t\ttotalWeight += definition.Weight\n\t\tend\n\tend\n\tassert(totalWeight > 0, \"No eligible automatic weather events\")\n\tlocal roll = random:NextInteger(1, totalWeight)\n\tfor id, definition in pairs(EventDefinitions) do\n\t\tif definition.IsAutomatic and id ~= self.PreviousAutomaticEventId and definition.Weight > 0 then\n\t\t\troll -= definition.Weight\n\t\t\tif roll <= 0 then\n\t\t\t\treturn id\n\t\t\tend\n\t\tend\n\tend\n\terror(\"Automatic weather event selection failed\")\nend\n\nfunction WeatherEventService:StartBreak()\n\tassert(started, \"WeatherEventService has not started\")\n\tlocal version = invalidateTimer()\n\tself.CurrentPhase = \"Break\"\n\tself.CurrentEventId = \"\"\n\tself.CurrentEventStartTime = 0\n\tself.CurrentEventEndTime = 0\n\tself.BreakEndTime = workspace:GetServerTimeNow() + BREAK_DURATION\n\tpublishState(self)\n\tprint(\"[WeatherEventService] Break started - \" .. BREAK_DURATION .. \" seconds\")\n\ttask.delay(BREAK_DURATION, function()\n\t\tif version ~= timerVersion or self.CurrentPhase ~= \"Break\" then return end\n\t\tself.BreakEndTime = 0\n\t\tpublishState(self)\n\t\tif not self.AutomaticEventsPaused then\n\t\t\tself:_StartAutomaticEvent()\n\t\tend\n\tend)\nend\n\nfunction WeatherEventService:StartEvent(eventId, isAutomatic)\n\tassert(started, \"WeatherEventService has not started\")\n\tlocal definition = EventDefinitions[eventId]\n\tassert(definition, \"Unknown weather event: \" .. tostring(eventId))\n\tif isAutomatic then\n\t\tassert(definition.IsAutomatic, \"Secret events cannot start automatically\")\n\tend\n\tlocal version = invalidateTimer()\n\tif self.CurrentPhase == \"Event\" then\n\t\tlocal oldDefinition = EventDefinitions[self.CurrentEventId]\n\t\tprint(\"[WeatherEventService] Ending event: \" .. oldDefinition.DisplayName)\n\t\tself:OnEventEnded(oldDefinition)\n\tend\n\tlocal now = workspace:GetServerTimeNow()\n\tlocal duration = durationFor(definition)\n\tself.CurrentPhase = \"Event\"\n\tself.CurrentEventId = eventId\n\tself.CurrentEventStartTime = now\n\tself.CurrentEventEndTime = now + duration\n\tself.BreakEndTime = 0\n\tif isAutomatic then\n\t\tself.PreviousAutomaticEventId = eventId\n\tend\n\tpublishState(self)\n\tprint(\"[WeatherEventService] Starting event: \" .. definition.DisplayName .. \" - \" .. duration .. \" seconds\")\n\tself:OnEventStarted(definition)\n\ttask.delay(duration, function()\n\t\tif version ~= timerVersion or self.CurrentPhase ~= \"Event\" then return end\n\t\tself:EndCurrentEvent()\n\tend)\nend\n\nfunction WeatherEventService:_StartAutomaticEvent()\n\tif self.AutomaticEventsPaused or self.CurrentPhase ~= \"Break\" then return end\n\tif self:_StartQueuedEvent() then return end\n\tself:StartRandomAutomaticEvent()\nend\n\nfunction WeatherEventService:QueueEvent(eventId)\n\tif type(eventId) ~= \"string\" or not EventDefinitions[eventId] then return false end\n\tself.QueuedEventId = eventId\n\tself.QueueRevision += 1\n\tpublishState(self)\n\treturn true\nend\n\nfunction WeatherEventService:ClearQueue()\n\tself.QueuedEventId = \"\"\n\tself.QueueRevision += 1\n\tpublishState(self)\nend\n\nfunction WeatherEventService:_StartQueuedEvent()\n\tlocal eventId = self.QueuedEventId\n\tif eventId == \"\" then return false end\n\t-- Consume before starting so callbacks cannot replay the queued event.\n\tself.QueuedEventId = \"\"\n\tself.QueueRevision += 1\n\tself:StartEvent(eventId)\n\treturn true\nend\n\nfunction WeatherEventService:StartRandomAutomaticEvent()\n\tlocal eventId = self:SelectRandomAutomaticEvent()\n\tself:StartEvent(eventId, true)\n\treturn eventId\nend\n\nfunction WeatherEventService:EndCurrentEvent()\n\tif not started or self.CurrentPhase ~= \"Event\" then return end\n\tinvalidateTimer()\n\tlocal definition = EventDefinitions[self.CurrentEventId]\n\tprint(\"[WeatherEventService] Ending event: \" .. definition.DisplayName)\n\tself:OnEventEnded(definition)\n\t-- Explicitly queued events follow the current event immediately. An automatic\n\t-- pause holds the queue until automatic weather is resumed.\n\tself.CurrentPhase = \"Break\"\n\tif not self.AutomaticEventsPaused and self:_StartQueuedEvent() then return end\n\tself:StartBreak()\nend\n\nfunction WeatherEventService:EmergencyReset()\n\tinvalidateTimer()\n\tif self.CurrentPhase == \"Event\" then\n\t\tself:OnEventEnded(EventDefinitions[self.CurrentEventId])\n\tend\n\tself.QueuedEventId = \"\"\n\tself.QueueRevision += 1\n\tself.AutomaticEventsPaused = false\n\t-- Publishing Break invokes the existing client visual cleanup; its normal\n\t-- timer restarts the cycle. No Lighting objects are touched here.\n\tself:StartBreak()\nend\n\nfunction WeatherEventService:PauseAutomaticEvents()\n\tif self.AutomaticEventsPaused then return end\n\tself.AutomaticEventsPaused = true\n\tpublishState(self)\n\tprint(\"[WeatherEventService] Automatic events paused\")\nend\n\nfunction WeatherEventService:ResumeAutomaticEvents()\n\tif not self.AutomaticEventsPaused then return end\n\tself.AutomaticEventsPaused = false\n\tpublishState(self)\n\tprint(\"[WeatherEventService] Automatic events resumed\")\n\tif self.CurrentPhase == \"Break\" and self.BreakEndTime == 0 then\n\t\tself:_StartAutomaticEvent()\n\tend\nend\n\nfunction WeatherEventService:Start()\n\tif started then return end\n\tstarted = true\n\tstateFolder = ReplicatedStorage:FindFirstChild(\"WeatherState\")\n\tif not stateFolder then\n\t\tstateFolder = Instance.new(\"Folder\")\n\t\tstateFolder.Name = \"WeatherState\"\n\tend\n\tassert(stateFolder:IsA(\"Folder\"), \"WeatherState must be a Folder\")\n\tself:StartBreak()\n\tstateFolder.Parent = ReplicatedStorage\nend\n\nfunction WeatherEventService:KnitStart()\n\tself:Start()\nend\n\nreturn WeatherEventService\n"}, {"path": ["ServerScriptService", "ServerSource", "Server", "WorldService"], "source": "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\nlocal Config = require(ReplicatedStorage.SharedSource.Datas.AnimalKingdomConfig)\nlocal Shakeables = require(ReplicatedStorage.SharedSource.Datas.ShakeableDatabase)\nlocal Pets = require(ReplicatedStorage.SharedSource.Datas.PetDatabase)\nlocal Mutations = require(ReplicatedStorage.SharedSource.Datas.MutationDatabase)\n\nlocal WorldService = Knit.CreateService({ Name = \"WorldService\", Client = {} })\nlocal SanctuaryService\nlocal HarvestService\nlocal DataService\nlocal ProfileService\nlocal ProgressionService\nlocal nextSanctuarySlot = 0\nlocal biomeSpacing = 160\nlocal biomeSlots = {\n\tVector2.new(-1.5, -1.5), Vector2.new(-0.5, -1.5), Vector2.new(0.5, -1.5), Vector2.new(1.5, -1.5),\n\tVector2.new(1.5, -0.5), Vector2.new(1.5, 0.5), Vector2.new(1.5, 1.5), Vector2.new(0.5, 1.5),\n\tVector2.new(-0.5, 1.5), Vector2.new(-1.5, 1.5), Vector2.new(-1.5, 0.5), Vector2.new(-1.5, -0.5),\n}\n\nlocal biomeStyles = {\n\tMeadow = { Ground = Color3.fromRGB(111, 191, 82), Accent = Color3.fromRGB(244, 220, 92), Material = Enum.Material.Grass },\n\tForest = { Ground = Color3.fromRGB(40, 105, 55), Accent = Color3.fromRGB(100, 67, 42), Material = Enum.Material.Grass },\n\tJungle = { Ground = Color3.fromRGB(25, 137, 74), Accent = Color3.fromRGB(68, 209, 112), Material = Enum.Material.LeafyGrass },\n\tDesert = { Ground = Color3.fromRGB(227, 184, 100), Accent = Color3.fromRGB(199, 105, 53), Material = Enum.Material.Sand },\n\tSnow = { Ground = Color3.fromRGB(226, 241, 247), Accent = Color3.fromRGB(113, 190, 224), Material = Enum.Material.Snow },\n\tVolcano = { Ground = Color3.fromRGB(61, 53, 52), Accent = Color3.fromRGB(255, 76, 24), Material = Enum.Material.Slate },\n\tOcean = { Ground = Color3.fromRGB(40, 143, 202), Accent = Color3.fromRGB(76, 225, 220), Material = Enum.Material.Sand },\n\tAncientRuins = { Ground = Color3.fromRGB(122, 120, 103), Accent = Color3.fromRGB(222, 196, 121), Material = Enum.Material.Cobblestone },\n\tMagicalForest = { Ground = Color3.fromRGB(91, 55, 128), Accent = Color3.fromRGB(225, 107, 255), Material = Enum.Material.Grass },\n\tSky = { Ground = Color3.fromRGB(179, 224, 244), Accent = Color3.fromRGB(255, 255, 255), Material = Enum.Material.SmoothPlastic },\n\tPrehistoric = { Ground = Color3.fromRGB(104, 126, 62), Accent = Color3.fromRGB(184, 111, 55), Material = Enum.Material.Ground },\n\tMythical = { Ground = Color3.fromRGB(69, 44, 111), Accent = Color3.fromRGB(255, 107, 207), Material = Enum.Material.Slate },\n}\n\nlocal function folder(parent, name)\n\tlocal value = parent:FindFirstChild(name) or Instance.new(\"Folder\")\n\tvalue.Name = name\n\tvalue.Parent = parent\n\treturn value\nend\n\nlocal function part(parent, name, size, position, color)\n\tlocal value = Instance.new(\"Part\")\n\tvalue.Name = name\n\tvalue.Anchored = true\n\tvalue.Size = size\n\tvalue.Position = position\n\tvalue.Color = color\n\tvalue.Material = Enum.Material.SmoothPlastic\n\tvalue.TopSurface = Enum.SurfaceType.Smooth\n\tvalue.BottomSurface = Enum.SurfaceType.Smooth\n\tvalue.Parent = parent\n\treturn value\nend\n\nlocal function billboard(parent, text, offset, color)\n\tlocal gui = Instance.new(\"BillboardGui\")\n\tgui.Name = \"WorldLabel\"\n\tgui.Size = UDim2.fromOffset(280, 72)\n\tgui.StudsOffset = offset\n\tgui.AlwaysOnTop = true\n\tgui.MaxDistance = 150\n\tgui.Parent = parent\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = 1\n\tlabel.Text = text\n\tlabel.TextColor3 = color or Color3.new(1, 1, 1)\n\tlabel.TextStrokeColor3 = Color3.fromRGB(28, 36, 30)\n\tlabel.TextStrokeTransparency = 0.15\n\tlabel.TextScaled = true\n\tlabel.Font = Enum.Font.GothamBlack\n\tlabel.Parent = gui\n\treturn gui\nend\n\nlocal function propPart(parent, name, size, cframe, color, material, shape)\n\tlocal value = Instance.new(\"Part\")\n\tvalue.Name = name\n\tvalue.Anchored = true\n\tvalue.CanCollide = true\n\tvalue.Size = size\n\tvalue.CFrame = cframe\n\tvalue.Color = color\n\tvalue.Material = material or Enum.Material.SmoothPlastic\n\tvalue.TopSurface = Enum.SurfaceType.Smooth\n\tvalue.BottomSurface = Enum.SurfaceType.Smooth\n\tif shape then value.Shape = shape end\n\tvalue.Parent = parent\n\treturn value\nend\n\nlocal function buildTree(parent, position, style, scale, variant)\n\tlocal trunk = propPart(parent, \"Trunk\", Vector3.new(2.2, 8, 2.2) * scale, CFrame.new(position + Vector3.new(0, 4 * scale, 0)), style.Accent, Enum.Material.Wood, Enum.PartType.Cylinder)\n\ttrunk.CFrame *= CFrame.Angles(0, 0, math.rad(90))\n\tlocal crownColor = style.Ground:Lerp(Color3.new(1, 1, 1), variant * 0.035)\n\tpropPart(parent, \"Crown\", Vector3.new(7, 7, 7) * scale, CFrame.new(position + Vector3.new(0, 9 * scale, 0)), crownColor, Enum.Material.Grass, Enum.PartType.Ball)\n\tpropPart(parent, \"Crown\", Vector3.new(5, 5, 5) * scale, CFrame.new(position + Vector3.new(2.8, 10 * scale, 0)), crownColor, Enum.Material.Grass, Enum.PartType.Ball)\nend\n\nlocal function buildBiomeProp(parent, biomeId, position, style, scale, variant)\n\tif biomeId == \"Meadow\" or biomeId == \"Forest\" or biomeId == \"Jungle\" or biomeId == \"Prehistoric\" then\n\t\tbuildTree(parent, position, style, scale, variant)\n\telseif biomeId == \"Desert\" then\n\t\tlocal cactus = propPart(parent, \"Cactus\", Vector3.new(2.4, 9, 2.4) * scale, CFrame.new(position + Vector3.new(0, 4.5 * scale, 0)), Color3.fromRGB(62, 145, 72), Enum.Material.SmoothPlastic)\n\t\tpropPart(parent, \"CactusArm\", Vector3.new(5, 1.7, 1.7) * scale, cactus.CFrame * CFrame.new(1.7 * scale, 0.5 * scale, 0), cactus.Color, cactus.Material)\n\telseif biomeId == \"Snow\" then\n\t\tpropPart(parent, \"IceSpire\", Vector3.new(4, 11, 4) * scale, CFrame.new(position + Vector3.new(0, 5.5 * scale, 0)) * CFrame.Angles(0, math.rad(45), math.rad(8)), style.Accent, Enum.Material.Glass)\n\telseif biomeId == \"Volcano\" then\n\t\tpropPart(parent, \"LavaRock\", Vector3.new(7, 5, 7) * scale, CFrame.new(position + Vector3.new(0, 2.5 * scale, 0)) * CFrame.Angles(0, variant, 0), style.Ground, Enum.Material.Slate, Enum.PartType.Ball)\n\t\tlocal glow = propPart(parent, \"LavaCrack\", Vector3.new(4, 0.35, 1) * scale, CFrame.new(position + Vector3.new(0, 5 * scale, 0)), style.Accent, Enum.Material.Neon)\n\t\tglow.CanCollide = false\n\telseif biomeId == \"Ocean\" then\n\t\tpropPart(parent, \"Coral\", Vector3.new(2, 8, 2) * scale, CFrame.new(position + Vector3.new(0, 4 * scale, 0)) * CFrame.Angles(0, 0, math.rad(variant % 2 == 0 and 12 or -12)), style.Accent, Enum.Material.SmoothPlastic)\n\t\tpropPart(parent, \"CoralBranch\", Vector3.new(5, 1.5, 1.5) * scale, CFrame.new(position + Vector3.new(0, 5 * scale, 0)), Color3.fromRGB(255, 126, 151), Enum.Material.SmoothPlastic)\n\telseif biomeId == \"AncientRuins\" then\n\t\tpropPart(parent, \"Pillar\", Vector3.new(4, 10, 4) * scale, CFrame.new(position + Vector3.new(0, 5 * scale, 0)) * CFrame.Angles(math.rad(variant % 3 * 3), 0, math.rad(variant % 2 * 5)), style.Accent, Enum.Material.Cobblestone)\n\t\tpropPart(parent, \"Capital\", Vector3.new(6, 1.2, 6) * scale, CFrame.new(position + Vector3.new(0, 10 * scale, 0)), style.Accent, Enum.Material.Cobblestone)\n\telseif biomeId == \"MagicalForest\" then\n\t\tlocal stem = propPart(parent, \"MushroomStem\", Vector3.new(2.5, 6, 2.5) * scale, CFrame.new(position + Vector3.new(0, 3 * scale, 0)), Color3.fromRGB(236, 220, 203), Enum.Material.SmoothPlastic)\n\t\tpropPart(parent, \"MushroomCap\", Vector3.new(8, 3, 8) * scale, stem.CFrame * CFrame.new(0, 4 * scale, 0), style.Accent, Enum.Material.Neon, Enum.PartType.Ball)\n\telseif biomeId == \"Sky\" then\n\t\tlocal cloud = propPart(parent, \"Cloud\", Vector3.new(9, 4, 6) * scale, CFrame.new(position + Vector3.new(0, 6 * scale, 0)), Color3.new(1, 1, 1), Enum.Material.SmoothPlastic, Enum.PartType.Ball)\n\t\tcloud.CanCollide = false\n\t\tpropPart(parent, \"Cloud\", Vector3.new(6, 5, 6) * scale, cloud.CFrame * CFrame.new(3 * scale, 1, 0), cloud.Color, cloud.Material, Enum.PartType.Ball).CanCollide = false\n\telse\n\t\tlocal crystal = propPart(parent, \"Crystal\", Vector3.new(3.5, 10, 3.5) * scale, CFrame.new(position + Vector3.new(0, 5 * scale, 0)) * CFrame.Angles(0, math.rad(45), math.rad(variant % 2 == 0 and 8 or -8)), style.Accent, Enum.Material.Neon)\n\t\tcrystal.CanCollide = false\n\tend\nend\n\nfunction WorldService:BuildStaticBiomes(world)\n\tlocal blockout = world:FindFirstChild(\"BiomeBlockout\")\n\tif not blockout then return end\n\tfor biomeIndex, biome in ipairs(Config.Biomes) do\n\t\tlocal biomeModel = blockout:FindFirstChild(biome.Id)\n\t\tlocal platform = biomeModel and biomeModel:FindFirstChild(\"Platform\")\n\t\tif platform then\n\t\t\tlocal style = biomeStyles[biome.Id]\n\t\t\tplatform.Color = style.Ground\n\t\t\tplatform.Material = style.Material\n\t\t\tbiomeModel:SetAttribute(\"BiomeId\", biome.Id)\n\t\t\tlocal gameplay = folder(biomeModel, \"Gameplay\")\n\t\t\tgameplay:ClearAllChildren()\n\t\t\tlocal center = platform.Position + Vector3.new(0, platform.Size.Y / 2, 0)\n\t\t\tlocal sign = propPart(gameplay, \"BiomeSign\", Vector3.new(20, 10, 2), CFrame.new(center + Vector3.new(0, 5, -platform.Size.Z / 2 + 10)), style.Accent, Enum.Material.Wood)\n\t\t\tbillboard(sign, string.upper(biome.DisplayName), Vector3.new(0, 7, 0), style.Accent)\n\t\t\tlocal randomizer = Random.new(4700 + biomeIndex)\n\t\t\tfor propIndex = 1, 14 do\n\t\t\t\tlocal x = randomizer:NextNumber(-platform.Size.X * 0.42, platform.Size.X * 0.42)\n\t\t\t\tlocal z = randomizer:NextNumber(-platform.Size.Z * 0.38, platform.Size.Z * 0.38)\n\t\t\t\tif math.abs(x) > 22 or math.abs(z) > 25 then\n\t\t\t\t\tbuildBiomeProp(gameplay, biome.Id, center + Vector3.new(x, 0, z), style, randomizer:NextNumber(0.75, 1.35), propIndex)\n\t\t\t\tend\n\t\t\tend\n\t\t\tfor objectIndex = 1, Config.ShakeablesPerBiome do\n\t\t\t\tlocal shakeableId = string.format(\"%s_Shakeable_%02d\", biome.Id, objectIndex)\n\t\t\t\tlocal definition = Shakeables[shakeableId]\n\t\t\t\tlocal angle = (objectIndex - 1) / Config.ShakeablesPerBiome * math.pi * 2\n\t\t\t\tlocal glowing = biome.Id == \"Volcano\" or biome.Id == \"MagicalForest\" or biome.Id == \"Mythical\"\n\t\t\t\tlocal object = propPart(gameplay, shakeableId, Vector3.new(8, 10, 8), CFrame.new(center + Vector3.new(math.cos(angle) * 42, 5, math.sin(angle) * 36)), style.Accent, glowing and Enum.Material.Neon or Enum.Material.SmoothPlastic, Enum.PartType.Ball)\n\t\t\t\tobject:SetAttribute(\"ShakeableId\", shakeableId)\n\t\t\t\tobject:SetAttribute(\"Cost\", definition.Cost)\n\t\t\t\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\t\t\t\tprompt.ActionText = \"Pay & Shake\"\n\t\t\t\tprompt.ObjectText = string.format(\"%d Forest Coins\", definition.Cost)\n\t\t\t\tprompt.MaxActivationDistance = 12\n\t\t\t\tprompt.Parent = object\n\t\t\t\tprompt.Triggered:Connect(function(player)\n\t\t\t\t\tHarvestService.Client.Shake(HarvestService.Client, player, shakeableId)\n\t\t\t\tend)\n\t\t\tend\n\t\t\tif biomeIndex == 1 then\n\t\t\t\tlocal spawn = Instance.new(\"SpawnLocation\")\n\t\t\t\tspawn.Name = \"MeadowSpawn\"\n\t\t\t\tspawn.Anchored = true\n\t\t\t\tspawn.Neutral = true\n\t\t\t\tspawn.Size = Vector3.new(12, 1, 12)\n\t\t\t\tspawn.Position = center + Vector3.new(0, 1, 18)\n\t\t\t\tspawn.Color = style.Accent\n\t\t\t\tspawn.Material = Enum.Material.Neon\n\t\t\t\tspawn.Parent = gameplay\n\t\t\telse\n\t\t\t\tlocal inward = Vector3.new(-center.X, 0, -center.Z).Unit\n\t\t\t\tlocal gate = propPart(gameplay, \"UnlockGate\", Vector3.new(18, 14, 3), CFrame.new(center + inward * math.min(platform.Size.X, platform.Size.Z) * 0.39 + Vector3.new(0, 7, 0), center + inward * 10 + Vector3.new(0, 7, 0)), style.Accent, Enum.Material.Neon)\n\t\t\t\tgate.CanCollide = false\n\t\t\t\tgate:SetAttribute(\"BiomeId\", biome.Id)\n\t\t\t\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\t\t\t\tprompt.ActionText = \"Unlock \" .. biome.DisplayName\n\t\t\t\tprompt.ObjectText = tostring(biome.UnlockCost) .. \" Forest Coins\"\n\t\t\t\tprompt.HoldDuration = 0.5\n\t\t\t\tprompt.MaxActivationDistance = 14\n\t\t\t\tprompt.Parent = gate\n\t\t\t\tprompt.Triggered:Connect(function(player)\n\t\t\t\t\tProgressionService.Client.UnlockBiome(ProgressionService.Client, player, biome.Id)\n\t\t\t\tend)\n\t\t\tend\n\t\tend\n\tend\nend\n\nfunction WorldService:EnsurePerimeterBoundary()\n\tlocal ground = workspace:FindFirstChild(\"AnimalKingdomConcreteGround\")\n\tif not ground or not ground:IsA(\"BasePart\") then return end\n\tlocal height, thickness = 6, 3\n\tif ground.Size.X <= thickness * 2 or ground.Size.Z <= thickness * 2 then return end\n\tlocal boundary = workspace:FindFirstChild(\"AK_AuditPerimeter\")\n\tif boundary and (not boundary:IsA(\"Folder\") or boundary:GetAttribute(\"ManagedBy\") ~= \"WorldService\") then\n\t\twarn(\"[WorldService] Existing unmanaged AK_AuditPerimeter preserved\")\n\t\treturn\n\tend\n\tif not boundary then\n\t\tboundary = Instance.new(\"Folder\")\n\t\tboundary.Name = \"AK_AuditPerimeter\"\n\t\tboundary:SetAttribute(\"ManagedBy\", \"WorldService\")\n\t\tboundary.Parent = workspace\n\tend\n\t-- Four visible walls occupy the outermost three studs of the support slab.\n\t-- They are outside the authored biomes/routes; corners meet without gaps.\n\tlocal y = ground.Size.Y / 2 + height / 2\n\tlocal x, z = (ground.Size.X - thickness) / 2, (ground.Size.Z - thickness) / 2\n\tlocal sides = {\n\t\t{\"North\", Vector3.new(ground.Size.X, height, thickness), CFrame.new(0, y, -z)},\n\t\t{\"South\", Vector3.new(ground.Size.X, height, thickness), CFrame.new(0, y, z)},\n\t\t{\"West\", Vector3.new(thickness, height, ground.Size.Z - thickness * 2), CFrame.new(-x, y, 0)},\n\t\t{\"East\", Vector3.new(thickness, height, ground.Size.Z - thickness * 2), CFrame.new(x, y, 0)},\n\t}\n\tfor _, spec in ipairs(sides) do\n\t\tlocal wall = boundary:FindFirstChild(spec[1])\n\t\tif wall and (not wall:IsA(\"Part\") or wall:GetAttribute(\"AKBoundaryWall\") ~= true) then\n\t\t\twarn(\"[WorldService] Existing unmanaged perimeter object preserved: \" .. spec[1])\n\t\t\tcontinue\n\t\tend\n\t\tif not wall then wall = Instance.new(\"Part\"); wall.Name = spec[1] end\n\t\twall.Size = spec[2]\n\t\twall.CFrame = ground.CFrame * spec[3]\n\t\twall.Anchored = true\n\t\twall.CanCollide = true\n\t\twall.CanTouch = false\n\t\twall.CanQuery = true\n\t\twall.Transparency = 0\n\t\twall.Material = Enum.Material.Slate\n\t\twall.Color = Color3.fromRGB(143, 148, 150)\n\t\twall.TopSurface = Enum.SurfaceType.Smooth\n\t\twall.BottomSurface = Enum.SurfaceType.Smooth\n\t\twall:SetAttribute(\"AKBoundaryWall\", true)\n\t\twall.Parent = boundary\n\tend\nend\n\nfunction WorldService:BuildWorld()\n\t-- The authored place has separate named floors and detailed environment models.\n\t-- A live-only cleanup script removes BiomeBlockout, so its presence is not a\n\t-- reliable signal to generate an entire replacement world at startup.\n\tfor _, biome in ipairs(Config.Biomes) do\n\t\tlocal authored = workspace:FindFirstChild(biome.Id)\n\t\tlocal floor = authored and authored:FindFirstChild(biome.Id .. \"Floor\")\n\t\tif floor and floor:IsA(\"BasePart\") then\n\t\t\tself.AuthoredMap = true\n\t\t\tlocal world = folder(workspace, \"World\")\n\t\t\tfolder(world, \"Runtime\")\n\t\t\tself:EnsurePerimeterBoundary()\n\t\t\t-- Keep Rojo's portable fallback available in edit data, but prevent\n\t\t\t-- its old footprint from appearing or blocking the authored map.\n\t\t\tlocal blockout = world:FindFirstChild(\"BiomeBlockout\")\n\t\t\tif blockout then\n\t\t\t\tblockout:SetAttribute(\"EditorReferenceOnly\", true)\n\t\t\t\tfor _, object in ipairs(blockout:GetDescendants()) do\n\t\t\t\t\tif object:IsA(\"BasePart\") then\n\t\t\t\t\t\tobject.Transparency = 1\n\t\t\t\t\t\tobject.CanCollide = false\n\t\t\t\t\t\tobject.CanTouch = false\n\t\t\t\t\t\tobject.CanQuery = false\n\t\t\t\t\t\tif object:IsA(\"SpawnLocation\") then object.Enabled = false end\n\t\t\t\t\telseif object:IsA(\"BillboardGui\") or object:IsA(\"SurfaceGui\") or object:IsA(\"ProximityPrompt\") then\n\t\t\t\t\t\tobject.Enabled = false\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\tprint(\"[WorldService] Preserving authored biome map; legacy world generation skipped\")\n\t\t\treturn\n\t\tend\n\tend\n\t-- The biome blockout is mapped by Rojo. Runtime objects still need a stable\n\t-- parent so systems such as NumNomService can add temporary world content.\n\tlocal existingWorld = workspace:FindFirstChild(\"World\")\n\tif existingWorld and existingWorld:FindFirstChild(\"BiomeBlockout\") then\n\t\tfolder(existingWorld, \"Runtime\")\n\t\tfolder(workspace, \"Sanctuaries\")\n\t\tself:BuildStaticBiomes(existingWorld)\n\t\treturn\n\tend\n\n\t-- Fall back to a generated world when the static blockout is not present.\n\tlocal world = folder(workspace, \"World\")\n\tlocal biomesFolder = folder(world, \"Biomes\")\n\tfolder(world, \"Runtime\")\n\tfolder(workspace, \"Sanctuaries\")\n\tlocal plaza = part(world, \"CentralPlaza\", Vector3.new(300, 0.1, 300), Vector3.new(0, 0.05, 0), Color3.fromRGB(213, 198, 153))\n\tplaza.Material = Enum.Material.Cobblestone\n\tlocal welcome = part(world, \"WelcomeSign\", Vector3.new(24, 12, 2), Vector3.new(0, 7, -135), Color3.fromRGB(65, 99, 72))\n\tbillboard(welcome, \"ANIMAL KINGDOM\", Vector3.new(0, 8, 0), Color3.fromRGB(255, 239, 154))\n\tfor biomeIndex, biome in ipairs(Config.Biomes) do\n\t\tlocal biomeFolder = folder(biomesFolder, biome.Id)\n\t\tbiomeFolder:SetAttribute(\"BiomeId\", biome.Id)\n\t\tlocal slot = biomeSlots[biomeIndex]\n\t\tlocal center = Vector3.new(slot.X * biomeSpacing, 0.05, slot.Y * biomeSpacing)\n\t\tlocal style = biomeStyles[biome.Id]\n\t\tlocal biomeColor = style.Ground\n\t\tlocal ground = part(biomeFolder, \"Ground\", Vector3.new(150, 0.1, 150), center, biomeColor)\n\t\tground.Material = style.Material\n\t\tlocal borderY = center.Y + 0.45\n\t\tlocal north = part(biomeFolder, \"NorthBorder\", Vector3.new(150, 0.8, 1.5), Vector3.new(center.X, borderY, center.Z - 74.25), style.Accent)\n\t\tlocal south = part(biomeFolder, \"SouthBorder\", Vector3.new(150, 0.8, 1.5), Vector3.new(center.X, borderY, center.Z + 74.25), style.Accent)\n\t\tlocal west = part(biomeFolder, \"WestBorder\", Vector3.new(1.5, 0.8, 147), Vector3.new(center.X - 74.25, borderY, center.Z), style.Accent)\n\t\tlocal east = part(biomeFolder, \"EastBorder\", Vector3.new(1.5, 0.8, 147), Vector3.new(center.X + 74.25, borderY, center.Z), style.Accent)\n\t\tfor _, border in ipairs({ north, south, west, east }) do\n\t\t\tborder.Material = (biome.Id == \"Volcano\" or biome.Id == \"MagicalForest\" or biome.Id == \"Mythical\") and Enum.Material.Neon or style.Material\n\t\t\tborder.CanCollide = false\n\t\tend\n\t\tlocal sign = part(biomeFolder, \"BiomeSign\", Vector3.new(16, 9, 1), center + Vector3.new(-61, 5.5, -61), style.Accent)\n\t\tbillboard(sign, string.upper(biome.DisplayName), Vector3.new(0, 6, 0), style.Accent)\n\t\tif biomeIndex == 1 then\n\t\t\tlocal spawn = Instance.new(\"SpawnLocation\")\n\t\t\tspawn.Name = \"MeadowSpawn\"\n\t\t\tspawn.Anchored = true\n\t\t\tspawn.Neutral = true\n\t\t\tspawn.Size = Vector3.new(10, 1, 10)\n\t\t\tspawn.Position = center + Vector3.new(-45, 2, -20)\n\t\t\tspawn.Color = Color3.fromRGB(244, 235, 133)\n\t\t\tspawn.Material = Enum.Material.Neon\n\t\t\tspawn.Parent = biomeFolder\n\t\telseif biome.UnlockCost > 0 then\n\t\t\tlocal inward = Vector3.new(-center.X, 0, -center.Z).Unit\n\t\t\tlocal gate = part(biomeFolder, \"UnlockGate\", Vector3.new(12, 12, 3), center + inward * 62 + Vector3.new(0, 6, 0), biomeColor:Lerp(Color3.new(0, 0, 0), 0.35))\n\t\t\tgate.CanCollide = false\n\t\t\tgate:SetAttribute(\"BiomeId\", biome.Id)\n\t\t\tlocal unlockPrompt = Instance.new(\"ProximityPrompt\")\n\t\t\tunlockPrompt.ActionText = \"Unlock \" .. biome.DisplayName\n\t\t\tunlockPrompt.ObjectText = tostring(biome.UnlockCost) .. \" Forest Coins\"\n\t\t\tunlockPrompt.HoldDuration = 0.5\n\t\t\tunlockPrompt.MaxActivationDistance = 14\n\t\t\tunlockPrompt.Parent = gate\n\t\t\tunlockPrompt.Triggered:Connect(function(player)\n\t\t\t\tProgressionService.Client.UnlockBiome(ProgressionService.Client, player, biome.Id)\n\t\t\tend)\n\t\tend\n\t\tfor shakeableId, definition in pairs(Shakeables) do\n\t\t\tif definition.Biome == biome.Id and not biomeFolder:FindFirstChild(shakeableId) then\n\t\t\t\tlocal objectIndex = tonumber(shakeableId:match(\"(%d+)$\")) or 1\n\t\t\t\tlocal object = part(biomeFolder, shakeableId, Vector3.new(8, 11, 8), center + Vector3.new(-50 + objectIndex * 20, 6.5, 32), style.Accent)\n\t\t\t\tobject.Material = (biome.Id == \"Volcano\" or biome.Id == \"MagicalForest\" or biome.Id == \"Mythical\") and Enum.Material.Neon or style.Material\n\t\t\t\tobject:SetAttribute(\"ShakeableId\", shakeableId)\n\t\t\t\tobject:SetAttribute(\"Cost\", definition.Cost)\n\t\t\t\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\t\t\t\tprompt.ActionText = \"Pay & Shake\"\n\t\t\t\tprompt.ObjectText = string.format(\"%s Forest Coins\", definition.Cost)\n\t\t\t\tprompt.MaxActivationDistance = 12\n\t\t\t\tprompt.Parent = object\n\t\t\t\tprompt.Triggered:Connect(function(player)\n\t\t\t\t\tHarvestService.Client.Shake(HarvestService.Client, player, shakeableId)\n\t\t\t\tend)\n\t\t\tend\n\t\tend\n\tend\nend\n\nfunction WorldService:CreateSanctuary(player)\n\tlocal sanctuaries = folder(workspace, \"Sanctuaries\")\n\tlocal existing = sanctuaries:FindFirstChild(tostring(player.UserId))\n\tif existing then existing:Destroy() end\n\tlocal model = Instance.new(\"Model\")\n\tmodel.Name = tostring(player.UserId)\n\tmodel:SetAttribute(\"OwnerUserId\", player.UserId)\n\tmodel.Parent = sanctuaries\n\tlocal slot = nextSanctuarySlot\n\tnextSanctuarySlot += 1\n\tlocal origin = Vector3.new((slot % 2) * 78 - 39, 0.15, math.floor(slot / 2) * 68 - 34)\n\tlocal base = part(model, \"SanctuaryFloor\", Vector3.new(72, 0.1, 60), origin, Color3.fromRGB(104, 180, 82))\n\tbase.Material = Enum.Material.Grass\n\tfor index = 1, Config.MaxDisplayedPets do\n\t\tlocal row = math.floor((index - 1) / 10)\n\t\tlocal column = (index - 1) % 10\n\t\tlocal spot = part(model, string.format(\"DisplaySpot%02d\", index), Vector3.new(5, 0.4, 5), origin + Vector3.new(-31.5 + column * 7, 0.7, -22 + row * 7), Color3.fromRGB(196, 231, 170))\n\t\tspot:SetAttribute(\"DisplayIndex\", index)\n\tend\n\tlocal pad = part(model, \"CollectionPad\", Vector3.new(12, 1, 8), origin + Vector3.new(0, 1, 25), Color3.fromRGB(255, 211, 75))\n\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\tprompt.ActionText = \"Collect Forest Coins\"\n\tprompt.ObjectText = \"Shared Sanctuary Income\"\n\tprompt.MaxActivationDistance = 12\n\tprompt.Parent = pad\n\tprompt.Triggered:Connect(function(triggeringPlayer)\n\t\tif triggeringPlayer == player then SanctuaryService.Client.Collect(SanctuaryService.Client, player) end\n\tend)\n\ttask.defer(function()\n\t\tProfileService:WaitUntilProfileLoaded(player)\n\t\tif player:IsDescendantOf(Players) then\n\t\t\tself:RefreshDisplays(player)\n\t\tend\n\tend)\nend\n\nfunction WorldService:RefreshDisplays(player)\n\tlocal sanctuaries = workspace:FindFirstChild(\"Sanctuaries\")\n\tlocal sanctuary = sanctuaries and sanctuaries:FindFirstChild(tostring(player.UserId))\n\tlocal data = DataService:Get(player)\n\tif not sanctuary or not data then return end\n\tlocal visuals = sanctuary:FindFirstChild(\"DisplayedPets\") or Instance.new(\"Folder\")\n\tvisuals.Name = \"DisplayedPets\"\n\tvisuals.Parent = sanctuary\n\tvisuals:ClearAllChildren()\n\tlocal ownedById = {}\n\tfor _, owned in ipairs(data.OwnedPets) do ownedById[owned.UniquePetId] = owned end\n\tfor index, uniqueId in ipairs(data.DisplayedPetIds) do\n\t\tif index > Config.MaxDisplayedPets then break end\n\t\tlocal owned = ownedById[uniqueId]\n\t\tlocal definition = owned and Pets[owned.PetId]\n\t\tlocal mutation = owned and Mutations[owned.Mutation]\n\t\tlocal spot = sanctuary:FindFirstChild(string.format(\"DisplaySpot%02d\", index))\n\t\tif definition and mutation and spot then\n\t\t\tlocal visual = part(visuals, uniqueId, Vector3.new(3.2, 3.2, 3.2), spot.Position + Vector3.new(0, 2), mutation.Color)\n\t\t\tvisual.Shape = Enum.PartType.Ball\n\t\t\tvisual.CanCollide = false\n\t\t\tvisual:SetAttribute(\"PetId\", owned.PetId)\n\t\t\tvisual:SetAttribute(\"Mutation\", owned.Mutation)\n\t\t\tlocal label = Instance.new(\"BillboardGui\")\n\t\t\tlabel.Size = UDim2.fromOffset(150, 40)\n\t\t\tlabel.StudsOffset = Vector3.new(0, 2.5, 0)\n\t\t\tlabel.AlwaysOnTop = true\n\t\t\tlabel.Parent = visual\n\t\t\tlocal textLabel = Instance.new(\"TextLabel\")\n\t\t\ttextLabel.Size = UDim2.fromScale(1, 1)\n\t\t\ttextLabel.BackgroundTransparency = 1\n\t\t\ttextLabel.TextColor3 = Color3.new(1, 1, 1)\n\t\t\ttextLabel.TextStrokeTransparency = 0.4\n\t\t\ttextLabel.TextScaled = true\n\t\t\ttextLabel.Text = definition.Name\n\t\t\ttextLabel.Parent = label\n\t\tend\n\tend\nend\n\nfunction WorldService:KnitStart()\n\tself:BuildWorld()\n\t-- Legacy display pads are prototype pet content, not the authored player plots.\n\t-- Keep them available only through an explicit development opt-in.\n\tif self.AuthoredMap and workspace:GetAttribute(\"AK_EnableLegacyGameplayScaffold\") ~= true then\n\t\treturn\n\tend\n\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\ttask.spawn(function() self:CreateSanctuary(player) end)\n\tend\n\tPlayers.PlayerAdded:Connect(function(player)\n\t\tself:CreateSanctuary(player)\n\tend)\n\tPlayers.PlayerRemoving:Connect(function(player)\n\t\tlocal sanctuaries = workspace:FindFirstChild(\"Sanctuaries\")\n\t\tlocal sanctuary = sanctuaries and sanctuaries:FindFirstChild(tostring(player.UserId))\n\t\tif sanctuary then sanctuary:Destroy() end\n\tend)\n\tProfileService.UpdateSpecificData:Connect(function(player, redirectories)\n\t\tif redirectories[1] == \"DisplayedPetIds\" then\n\t\t\tself:RefreshDisplays(player)\n\t\tend\n\tend)\nend\n\nfunction WorldService:KnitInit()\n\tSanctuaryService = Knit.GetService(\"SanctuaryService\")\n\tHarvestService = Knit.GetService(\"HarvestService\")\n\tDataService = Knit.GetService(\"PlayerDataService\")\n\tProfileService = Knit.GetService(\"ProfileService\")\n\tProgressionService = Knit.GetService(\"ProgressionService\")\nend\n\nreturn WorldService\n"}, {"path": ["StarterGui", "AnimalKingdomUI", "Components"], "source": "local TweenService = game:GetService(\"TweenService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal Theme = require(script.Parent.Theme)\n\nlocal C = {}\n\nlocal function new(className, props, parent)\n\tlocal object = Instance.new(className)\n\tfor key, value in pairs(props or {}) do object[key] = value end\n\tobject.Parent = parent\n\treturn object\nend\nC.new = new\n\nfunction C.corner(parent, radius)\n\treturn new(\"UICorner\", { CornerRadius = UDim.new(0, radius or 14) }, parent)\nend\n\nfunction C.stroke(parent, thickness, color)\n\treturn new(\"UIStroke\", { Thickness = thickness or 3, Color = color or Theme.Ink, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, parent)\nend\n\nfunction C.padding(parent, left, right, top, bottom)\n\treturn new(\"UIPadding\", {\n\t\tPaddingLeft = UDim.new(0, left), PaddingRight = UDim.new(0, right or left),\n\t\tPaddingTop = UDim.new(0, top or left), PaddingBottom = UDim.new(0, bottom or top or left),\n\t}, parent)\nend\n\nfunction C.text(parent, props)\n\tprops = props or {}\n\tprops.BackgroundTransparency = props.BackgroundTransparency == nil and 1 or props.BackgroundTransparency\n\tprops.Font = props.Font or Enum.Font.GothamBold\n\tprops.TextColor3 = props.TextColor3 or Theme.Ink\n\tprops.TextSize = props.TextSize or 18\n\tprops.TextWrapped = props.TextWrapped == nil and true or props.TextWrapped\n\tlocal label = new(\"TextLabel\", props, parent)\n\tnew(\"UITextSizeConstraint\", { MinTextSize = math.min(10, props.TextSize), MaxTextSize = props.TextSize }, label)\n\treturn label\nend\n\nfunction C.shadow(parent, offset)\n\tlocal shadow = new(\"Frame\", {\n\t\tName = \"Shadow\", AnchorPoint = parent.AnchorPoint, Position = parent.Position + UDim2.fromOffset(0, offset or 7),\n\t\tSize = parent.Size, BackgroundColor3 = Theme.Shadow, BackgroundTransparency = 0.58,\n\t\tBorderSizePixel = 0, ZIndex = math.max(0, parent.ZIndex - 1), Visible = parent.Visible,\n\t}, parent.Parent)\n\tC.corner(shadow, 16)\n\tparent:GetPropertyChangedSignal(\"Position\"):Connect(function() shadow.Position = parent.Position + UDim2.fromOffset(0, offset or 7) end)\n\tparent:GetPropertyChangedSignal(\"Size\"):Connect(function() shadow.Size = parent.Size end)\n\tparent:GetPropertyChangedSignal(\"Visible\"):Connect(function() shadow.Visible = parent.Visible end)\n\treturn shadow\nend\n\nfunction C.button(parent, name, text, color, size)\n\tlocal button = new(\"TextButton\", {\n\t\tName = name, Size = size or UDim2.fromOffset(150, 48), BackgroundColor3 = color or Theme.Green,\n\t\tBorderSizePixel = 0, AutoButtonColor = false, Text = text, TextColor3 = Theme.White,\n\t\tTextStrokeColor3 = Theme.Ink, TextStrokeTransparency = 0.55, TextSize = 18,\n\t\tFont = Enum.Font.GothamBlack, ZIndex = 5,\n\t}, parent)\n\tC.corner(button, 12); C.stroke(button, 3)\n\tlocal scale = new(\"UIScale\", { Scale = 1 }, button)\n\tlocal function tween(value, duration) TweenService:Create(scale, TweenInfo.new(duration or .1, Enum.EasingStyle.Quad), { Scale = value }):Play() end\n\tif not UserInputService.TouchEnabled or UserInputService.MouseEnabled then\n\t\tbutton.MouseEnter:Connect(function() tween(1.05, .12) end)\n\t\tbutton.MouseLeave:Connect(function() tween(1, .12) end)\n\tend\n\tbutton.MouseButton1Down:Connect(function() tween(.94, .06) end)\n\tbutton.MouseButton1Up:Connect(function() tween(UserInputService.MouseEnabled and 1.05 or 1, .09) end)\n\treturn button\nend\n\nfunction C.pill(parent, text, color)\n\tlocal label = C.text(parent, { Size = UDim2.fromOffset(100, 28), BackgroundTransparency = 0, BackgroundColor3 = color, Text = text, TextColor3 = Theme.White, TextSize = 13 })\n\tC.corner(label, 10); C.stroke(label, 2)\n\treturn label\nend\n\nfunction C.card(parent, name, size, color)\n\tlocal frame = new(\"Frame\", { Name = name, Size = size, BackgroundColor3 = color or Theme.White, BorderSizePixel = 0 }, parent)\n\tC.corner(frame, 14); C.stroke(frame, 3)\n\treturn frame\nend\n\nfunction C.scroller(parent, name, pos, size)\n\tlocal scroll = new(\"ScrollingFrame\", {\n\t\tName = name, Position = pos, Size = size, BackgroundTransparency = 1, BorderSizePixel = 0,\n\t\tScrollBarThickness = 6, ScrollBarImageColor3 = Theme.Ink, AutomaticCanvasSize = Enum.AutomaticSize.Y,\n\t\tCanvasSize = UDim2.new(), ScrollingDirection = Enum.ScrollingDirection.Y,\n\t}, parent)\n\treturn scroll\nend\n\nfunction C.window(parent, name, title, accent)\n\tlocal root = new(\"Frame\", {\n\t\tName = name, AnchorPoint = Vector2.new(.5, .5), Position = UDim2.fromScale(.5, .53),\n\t\tSize = UDim2.fromScale(.6, .74), BackgroundColor3 = Theme.Panel, BorderSizePixel = 0,\n\t\tVisible = false, ClipsDescendants = false, ZIndex = 20,\n\t}, parent)\n\tC.corner(root, 18); C.stroke(root, 4); C.shadow(root, 9)\n\tnew(\"UISizeConstraint\", { MinSize = Vector2.new(300, 360), MaxSize = Vector2.new(1050, 760) }, root)\n\tlocal scale = new(\"UIScale\", { Name = \"OpenScale\", Scale = .92 }, root)\n\tlocal header = new(\"Frame\", { Name = \"Header\", Size = UDim2.new(1, 0, 0, 66), BackgroundColor3 = accent, BorderSizePixel = 0, ZIndex = 21 }, root)\n\tC.corner(header, 16)\n\tnew(\"Frame\", { Name = \"SquareBottom\", Position = UDim2.new(0, 0, 1, -18), Size = UDim2.new(1, 0, 0, 18), BackgroundColor3 = accent, BorderSizePixel = 0, ZIndex = 21 }, header)\n\tC.text(header, { Name = \"Title\", Position = UDim2.fromOffset(22, 7), Size = UDim2.new(1, -92, 1, -14), Text = title, TextColor3 = Theme.White, TextStrokeColor3 = Theme.Ink, TextStrokeTransparency = .35, TextXAlignment = Enum.TextXAlignment.Left, TextSize = 28, ZIndex = 22 })\n\tlocal close = C.button(header, \"Close\", \"X\", Theme.Red, UDim2.fromOffset(48, 48))\n\tclose.AnchorPoint = Vector2.new(1, .5); close.Position = UDim2.new(1, -10, .5, 0); close.ZIndex = 23\n\treturn root, close, scale\nend\n\nreturn C\n"}, {"path": ["StarterGui", "AnimalKingdomUI", "ExampleData"], "source": "local biomes = { \"Meadow\", \"Forest\", \"Jungle\", \"Desert\", \"Snow\", \"Volcano\", \"Ocean\", \"Ancient Ruins\", \"Magical Forest\", \"Sky\", \"Prehistoric\", \"Mythical\" }\nlocal colors = {\n\tColor3.fromRGB(104,207,104), Color3.fromRGB(47,147,84), Color3.fromRGB(39,184,117), Color3.fromRGB(242,188,85),\n\tColor3.fromRGB(140,217,242), Color3.fromRGB(230,83,54), Color3.fromRGB(71,170,232), Color3.fromRGB(156,135,101),\n\tColor3.fromRGB(174,100,221), Color3.fromRGB(111,190,246), Color3.fromRGB(124,135,65), Color3.fromRGB(121,72,185),\n}\nlocal biomeData = {}\nlocal biomeConfig = require(game:GetService(\"ReplicatedStorage\").SharedSource.Datas.AnimalKingdomConfig)\nlocal biomePrices = {}\nfor _, biome in ipairs(biomeConfig.Biomes) do biomePrices[biome.Id] = biome.UnlockCost end\nfor i, name in ipairs(biomes) do\n\tlocal id = name:gsub(\" \", \"\")\n\ttable.insert(biomeData, { Id = id, Name = name, Color = colors[i], Unlocked = i == 1, Price = biomePrices[id] })\nend\nlocal pets = {\n\t{ Id=\"meadow_bunny\", Name=\"Daisy Bunny\", Biome=\"Meadow\", Rarity=\"Common\", Income=12, Discovered=true, Mutations={\"Normal\",\"Golden\"}, Owned=3 },\n\t{ Id=\"forest_fox\", Name=\"Mossy Fox\", Biome=\"Forest\", Rarity=\"Rare\", Income=125, Discovered=true, Mutations={\"Normal\"}, Owned=1 },\n\t{ Id=\"jungle_parrot\", Name=\"Sunset Parrot\", Biome=\"Jungle\", Rarity=\"Epic\", Income=680, Discovered=true, Mutations={\"Normal\",\"Shiny\"}, Owned=2 },\n\t{ Id=\"desert_fennec\", Name=\"Dune Fennec\", Biome=\"Desert\", Rarity=\"Legendary\", Income=2400, Discovered=false, Mutations={}, Owned=0 },\n\t{ Id=\"snow_owl\", Name=\"Frost Owl\", Biome=\"Snow\", Rarity=\"Mystic\", Income=9600, Discovered=false, Mutations={}, Owned=0 },\n}\nlocal decor = {\n\t{Id=\"fern\",Name=\"Sunny Fern\",Category=\"Plants\",Price=350,Owned=true,Color=Color3.fromRGB(88,190,94)},\n\t{Id=\"bench\",Name=\"Acorn Bench\",Category=\"Furniture\",Price=800,Owned=false,Color=Color3.fromRGB(190,125,67)},\n\t{Id=\"path\",Name=\"Pebble Path\",Category=\"Paths\",Price=500,Owned=true,Color=Color3.fromRGB(158,151,135)},\n\t{Id=\"lamp\",Name=\"Firefly Lamp\",Category=\"Lighting\",Price=1200,Owned=false,Color=Color3.fromRGB(255,194,54)},\n\t{Id=\"arch\",Name=\"Forest Arch\",Category=\"Structures\",Price=2600,Owned=false,Color=Color3.fromRGB(69,155,82)},\n\t{Id=\"fountain\",Name=\"Moon Fountain\",Category=\"Special\",Price=7500,Owned=false,Color=Color3.fromRGB(126,112,230)},\n}\nreturn table.freeze({ Biomes=biomeData, Pets=pets, Decor=decor })\n"}, {"path": ["StarterGui", "AnimalKingdomUI", "Main"], "source": "local Players = game:GetService(\"Players\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\n\nlocal screen = script.Parent\nlocal C = require(screen.Components)\nlocal T = require(screen.Theme)\nlocal Data = require(screen.ExampleData)\nlocal Bridge = require(screen.RemoteBridge)\n\n-- Biome preview images: edit the uploaded Roblox image asset IDs here.\n-- Canonical thumbnail source: Real_Animal_K (live Rojo mapping verified).\n-- Keys match ExampleData.Biomes.Name, including spaces (never the card position).\n-- Sky and Prehistoric are existing cards and remain in the menu.\nlocal BIOME_IMAGES = {\n\tMeadow = \"rbxassetid://79736014037603\",\n\tForest = \"rbxassetid://97040662664031\",\n\tJungle = \"rbxassetid://77499149230943\",\n\tDesert = \"rbxassetid://113662927298251\",\n\tSnow = \"rbxassetid://101360540215056\",\n\tVolcano = \"rbxassetid://75357230072758\",\n\tOcean = \"rbxassetid://136415351318087\",\n\tMythical = \"rbxassetid://140106974475381\",\n\t[\"Magical Forest\"] = \"rbxassetid://88779723399477\",\n\t[\"Ancient Ruins\"] = \"rbxassetid://111386954175720\",\n\tSky = \"rbxassetid://99203717760122\",\n\tPrehistoric = \"rbxassetid://136069416863754\",\n}\n\nscreen:SetAttribute(\"ProductionUI\", true)\nscreen:SetAttribute(\"Version\", \"1.0.0\")\n\nlocal n = C.new\nlocal windows, activeWindow, connections = {}, nil, {}\nlocal contentByWindow = {}\n\nlocal function connect(signal, callback)\n\tlocal connection = signal:Connect(callback)\n\ttable.insert(connections, connection)\n\treturn connection\nend\n\nlocal function formatNumber(value)\n\tfor _, unit in ipairs({{1e12,\"T\"},{1e9,\"B\"},{1e6,\"M\"},{1e3,\"K\"}}) do\n\t\tif value >= unit[1] then\n\t\t\tlocal digits = value / unit[1]\n\t\t\treturn (digits >= 100 and \"%.0f%s\" or digits >= 10 and \"%.1f%s\" or \"%.2f%s\"):format(digits, unit[2])\n\t\tend\n\tend\n\treturn tostring(math.floor(value))\nend\n\nlocal hud = n(\"Frame\", { Name=\"HUD\", Size=UDim2.fromScale(1,1), BackgroundTransparency=1 }, screen)\nlocal showUI = C.button(screen,\"ShowUI\",\"SHOW UI\",T.Teal,UDim2.fromOffset(104,42));showUI.AnchorPoint=Vector2.new(1,1);showUI.Position=UDim2.new(1,-18,1,-18);showUI.Visible=false;showUI.ZIndex=90\nconnect(showUI.Activated,function() hud.Visible=true;showUI.Visible=false end)\nlocal windowsFolder = n(\"Folder\", { Name=\"Windows\" }, screen)\nlocal popups = n(\"Folder\", { Name=\"Popups\" }, screen)\nlocal templates = n(\"Folder\", { Name=\"Templates\" }, screen)\n\nlocal function makeTemplate(name, size)\n\tlocal card = C.card(templates, name, size, T.White); card.Visible = false\n\tcard:SetAttribute(\"Template\", true)\n\treturn card\nend\nmakeTemplate(\"PetCard\", UDim2.fromOffset(170,210)); makeTemplate(\"BiomeCard\", UDim2.fromOffset(230,260))\nmakeTemplate(\"PlayerCard\", UDim2.new(1,-8,0,80)); makeTemplate(\"DecorCard\", UDim2.fromOffset(170,190))\n\nlocal function showWindow(name)\n\tlocal target = windows[name]\n\tif activeWindow == target then\n\t\ttarget.Close()\n\t\treturn\n\tend\n\tif activeWindow then activeWindow.Close(true) end\n\tactiveWindow = target\n\ttarget.CloseVersion += 1\n\tif target.ScaleTween then target.ScaleTween:Cancel() end\n\tif target.FadeTween then target.FadeTween:Cancel() end\n\ttarget.Root.Visible = true\n\ttarget.Root.BackgroundTransparency = 1\n\ttarget.Scale.Scale = .92\n\ttarget.ScaleTween = TweenService:Create(target.Scale, TweenInfo.new(.19, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1})\n\ttarget.FadeTween = TweenService:Create(target.Root, TweenInfo.new(.16), {BackgroundTransparency=0})\n\ttarget.ScaleTween:Play(); target.FadeTween:Play()\nend\n\nlocal function registerWindow(name, title, color)\n\tlocal root, closeButton, scale = C.window(windowsFolder, name .. \"Window\", title, color)\n\tlocal record = { Root=root, Scale=scale, CloseVersion=0 }\n\tfunction record.Close(immediate)\n\t\tif not root.Visible then return end\n\t\trecord.CloseVersion += 1\n\t\tlocal closeVersion = record.CloseVersion\n\t\tif record.ScaleTween then record.ScaleTween:Cancel() end\n\t\tif record.FadeTween then record.FadeTween:Cancel() end\n\t\tif immediate then root.Visible=false else\n\t\t\trecord.ScaleTween = TweenService:Create(scale, TweenInfo.new(.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale=.92})\n\t\t\trecord.FadeTween = TweenService:Create(root, TweenInfo.new(.14), {BackgroundTransparency=1})\n\t\t\trecord.ScaleTween:Play(); record.FadeTween:Play()\n\t\t\ttask.delay(.14, function()\n\t\t\t\tif record.CloseVersion == closeVersion then root.Visible=false; root.BackgroundTransparency=0 end\n\t\t\tend)\n\t\tend\n\t\tif activeWindow == record then\n\t\t\tactiveWindow=nil\n\t\tend\n\tend\n\tconnect(closeButton.Activated, function() record.Close() end)\n\twindows[name]=record\n\tcontentByWindow[name]=n(\"Frame\", {Name=\"Content\", Position=UDim2.fromOffset(16,78), Size=UDim2.new(1,-32,1,-94), BackgroundTransparency=1, ZIndex=21}, root)\n\treturn contentByWindow[name], record\nend\n\n-- Currency HUD\nlocal currencyBar = n(\"Frame\", {Name=\"CurrencyBar\", AnchorPoint=Vector2.new(.5,0), Position=UDim2.new(.5,0,0,6), Size=UDim2.new(.42,0,0,52), BackgroundTransparency=1}, hud)\nn(\"UISizeConstraint\", {MinSize=Vector2.new(300,48),MaxSize=Vector2.new(560,56)}, currencyBar)\nlocal currencyLayout=n(\"UIListLayout\",{FillDirection=Enum.FillDirection.Horizontal,HorizontalAlignment=Enum.HorizontalAlignment.Center,Padding=UDim.new(0,14)},currencyBar)\nlocal currencyLabels={}\nlocal function currency(name, icon, color, value)\n\tlocal capsule=C.card(currencyBar,name,UDim2.new(.5,-7,1,0),T.White)\n\tlocal iconContainer=n(\"Frame\",{Name=\"Icon\",AnchorPoint=Vector2.new(0,.5),Position=UDim2.fromOffset(9,26),Size=UDim2.fromOffset(42,42),BackgroundTransparency=1,BorderSizePixel=0},capsule)\n\tn(\"ImageLabel\",{Name=\"Image\",Size=UDim2.fromScale(1,1),BackgroundTransparency=1,Image=icon,ScaleType=Enum.ScaleType.Fit},iconContainer)\n\tC.text(capsule,{Position=UDim2.fromOffset(61,4),Size=UDim2.new(1,-69,.4,0),Text=name,TextColor3=T.Muted,TextSize=12,TextScaled=true,TextXAlignment=Enum.TextXAlignment.Left})\n\tlocal amount=C.text(capsule,{Position=UDim2.fromOffset(61,21),Size=UDim2.new(1,-69,.58,-3),Text=value and formatNumber(value) or \"\u2014\",TextSize=22,TextScaled=true,TextXAlignment=Enum.TextXAlignment.Left})\n\tcurrencyLabels[name]=amount\nend\ncurrency(\"Coins\",\"rbxassetid://73159313753278\",T.Yellow); currency(\"Friendship Tokens\",\"rbxassetid://86634408252247\",T.Pink)\nlocal currencyKeys = { ForestCoins=\"Coins\", FriendshipTokens=\"Friendship Tokens\" }\nlocal function applyCurrency(key, value)\n\tlocal label = currencyLabels[currencyKeys[key]]\n\tif label and type(value) == \"number\" and value == value then label.Text = formatNumber(value) end\nend\n\n-- Compact 2-column x 3-row navigation. Vertical fill preserves the requested\n-- Pet/Biomes/Trade left column and Merge/Decor/Settings right column.\nlocal nav=n(\"Frame\",{Name=\"Navigation\",AnchorPoint=Vector2.new(0,.5),Position=UDim2.new(0,16,.57,0),Size=UDim2.fromOffset(158,226),BackgroundTransparency=1},hud)\nn(\"UISizeConstraint\",{MinSize=Vector2.new(140,202),MaxSize=Vector2.new(170,238)},nav)\nlocal navLayout=n(\"UIGridLayout\",{CellSize=UDim2.fromOffset(72,68),CellPadding=UDim2.fromOffset(12,11),FillDirection=Enum.FillDirection.Vertical,FillDirectionMaxCells=3,HorizontalAlignment=Enum.HorizontalAlignment.Left,VerticalAlignment=Enum.VerticalAlignment.Center,SortOrder=Enum.SortOrder.LayoutOrder},nav)\nlocal navInfo={\n\t{\"PetIndex\",\"PET INDEX\",\"rbxassetid://130704366997114\",T.Green},\n\t{\"Biomes\",\"BIOMES\",\"rbxassetid://82358034979098\",T.Blue},\n\t{\"Trade\",\"TRADE\",\"rbxassetid://130691073120682\",T.Pink},\n\t{\"Merge\",\"MERGE\",\"rbxassetid://115724448794607\",T.Purple},\n\t{\"Decor\",\"DECOR\",\"rbxassetid://122606832571984\",T.Orange},\n\t{\"Settings\",\"SETTINGS\",\"rbxassetid://139359346454484\",T.Teal},\n}\nfor index, info in ipairs(navInfo) do\n\tlocal holder=n(\"Frame\",{Name=info[1],Size=UDim2.fromOffset(72,68),BackgroundTransparency=1,LayoutOrder=index},nav)\n\tlocal button=C.button(holder,\"Button\",\"\",info[4],UDim2.fromOffset(50,44)); button.AnchorPoint=Vector2.new(.5,0);button.Position=UDim2.new(.5,0,0,0)\n\tn(\"ImageLabel\",{\n\t\tName=\"Icon\", AnchorPoint=Vector2.new(.5,.5), Position=UDim2.fromScale(.5,.5),\n\t\tSize=UDim2.new(1,-6,1,-4), BackgroundTransparency=1, Image=info[3],\n\t\tScaleType=Enum.ScaleType.Fit, ZIndex=button.ZIndex+1,\n\t},button)\n\tlocal label=C.text(holder,{Position=UDim2.new(0,0,1,-19),Size=UDim2.new(1,0,0,18),Text=info[2],TextSize=9})\n\tlocal badge=C.pill(holder,\"!\",T.Red);badge.Name=\"NotificationBadge\";badge.Size=UDim2.fromOffset(21,21);badge.Position=UDim2.new(1,-19,0,-5);badge.Visible=false;badge.ZIndex=9\n\tlocal tooltip=C.pill(holder,info[2],T.Ink);tooltip.Name=\"Tooltip\";tooltip.AnchorPoint=Vector2.new(0,.5);tooltip.Position=UDim2.new(1,8,.35,0);tooltip.Size=UDim2.fromOffset(105,30);tooltip.Visible=false;tooltip.ZIndex=10\n\tconnect(button.MouseEnter,function() if UserInputService.MouseEnabled then tooltip.Visible=true end end)\n\tconnect(button.MouseLeave,function() tooltip.Visible=false end)\n\tconnect(button.Activated,function() showWindow(info[1]) end)\nend\n\nlocal function grid(parent, cell, padding)\n\treturn n(\"UIGridLayout\",{CellSize=cell,CellPadding=padding or UDim2.fromOffset(12,12),SortOrder=Enum.SortOrder.LayoutOrder},parent)\nend\nlocal function sectionTitle(parent,text,pos,size)\n\treturn C.text(parent,{Position=pos,Size=size,Text=text,TextSize=17,TextXAlignment=Enum.TextXAlignment.Left})\nend\nlocal function emptyChildren(parent, class)\n\tfor _, child in ipairs(parent:GetChildren()) do if child:IsA(class or \"GuiObject\") then child:Destroy() end end\nend\n\n-- PET INDEX\ndo\n\tlocal content=registerWindow(\"PetIndex\",\"PET INDEX\",T.Green)\n\tlocal search=n(\"TextBox\",{Name=\"Search\",Position=UDim2.fromOffset(0,0),Size=UDim2.new(.43,-6,0,44),BackgroundColor3=T.White,PlaceholderText=\"Search discovered pets...\",Text=\"\",TextColor3=T.Ink,PlaceholderColor3=T.Muted,TextSize=15,Font=Enum.Font.GothamMedium,ClearTextOnFocus=false},content);C.corner(search,12);C.stroke(search,3);C.padding(search,14,14,0,0)\n\tlocal count=C.pill(content,\"3 / 300 DISCOVERED\",T.Green);count.Name=\"DiscoveredCount\";count.Position=UDim2.new(.43,5,0,7);count.Size=UDim2.new(.27,-5,0,31)\n\tlocal filter=C.button(content,\"Filters\",\"FILTERS\",T.Blue,UDim2.new(.3,-5,0,40));filter.Position=UDim2.new(.7,5,0,2)\n\tlocal filterRow=n(\"ScrollingFrame\",{Name=\"FilterRow\",Position=UDim2.fromOffset(0,51),Size=UDim2.new(1,0,0,42),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=0,ScrollingDirection=Enum.ScrollingDirection.X,AutomaticCanvasSize=Enum.AutomaticSize.X,CanvasSize=UDim2.new()},content)\n\tlocal fl=n(\"UIListLayout\",{FillDirection=Enum.FillDirection.Horizontal,Padding=UDim.new(0,7)},filterRow)\n\tfor _,label in ipairs({\"All\",\"Meadow\",\"Forest\",\"Jungle\",\"Desert\",\"Snow\",\"Volcano\",\"Ocean\",\"Ancient Ruins\",\"Magical Forest\",\"Sky\",\"Prehistoric\",\"Mythical\",\"Rarity: All\",\"Common\",\"Rare\",\"Epic\",\"Legendary\",\"Mystic\",\"Mutation: All\",\"Normal\",\"Golden\",\"Shiny\"}) do local b=C.button(filterRow,label,label,label==\"All\" and T.Green or (label:find(\":\") and T.Purple or T.Blue),UDim2.fromOffset(math.max(66,#label*8+24),34));b.TextSize=12 end\n\tlocal cards=C.scroller(content,\"PetGrid\",UDim2.fromOffset(0,100),UDim2.new(.68,-7,1,-100)); grid(cards,UDim2.new(.5,-7,0,190))\n\tlocal details=C.card(content,\"PetDetail\",UDim2.new(.32,-7,1,-100),T.Sky);details.Position=UDim2.new(.68,7,0,100);C.padding(details,12)\n\tlocal detailText=C.text(details,{Name=\"Details\",Size=UDim2.fromScale(1,1),Text=\"Select a discovered pet\\nto view its kingdom record.\",TextSize=16,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top})\n\tlocal function render()\n\t\temptyChildren(cards,\"GuiButton\")\n\t\tlocal query=string.lower(search.Text)\n\t\tfor i,pet in ipairs(Data.Pets) do\n\t\t\tif query==\"\" or (pet.Discovered and string.find(string.lower(pet.Name),query,1,true)) then\n\t\t\t\tlocal card=C.button(cards,pet.Id,\"\",pet.Discovered and (T.Rarity[pet.Rarity] or T.Green) or Color3.fromRGB(73,77,91),UDim2.new(.5,-7,0,190));card.LayoutOrder=i\n\t\t\t\tlocal icon=C.card(card,\"PetIcon\",UDim2.new(1,-18,0,92),pet.Discovered and Color3.fromRGB(235,249,229) or Color3.fromRGB(42,44,54));icon.Position=UDim2.fromOffset(9,9)\n\t\t\t\tC.text(icon,{Size=UDim2.fromScale(1,1),Text=pet.Discovered and pet.Name:sub(1,1) or \"? ? ?\",TextSize=34,TextColor3=pet.Discovered and T.Ink or Color3.fromRGB(18,19,24)})\n\t\t\t\tC.text(card,{Position=UDim2.fromOffset(8,106),Size=UDim2.new(1,-16,0,36),Text=pet.Discovered and pet.Name or \"UNDISCOVERED\",TextSize=14,ZIndex=7})\n\t\t\t\tC.text(card,{Position=UDim2.fromOffset(8,143),Size=UDim2.new(1,-16,0,38),Text=pet.Discovered and (pet.Rarity..\" \u2022 \"..pet.Biome..\"\\n\"..formatNumber(pet.Income)..\" / sec\") or \"Find this animal to reveal it\",TextSize=11,ZIndex=7})\n\t\t\t\tconnect(card.Activated,function() if pet.Discovered then detailText.Text=string.format(\"%s\\n\\nRarity  %s\\nBiome  %s\\nIncome  %s / sec\\n\\nMutations discovered\\n%s\\n\\nAmount owned  %d\",pet.Name,pet.Rarity,pet.Biome,formatNumber(pet.Income),table.concat(pet.Mutations,\", \"),pet.Owned) end end)\n\t\t\tend\n\t\tend\n\tend\n\tconnect(search:GetPro