ild(\"UIRequest\")\n\t\treturn endpoint~=nil and endpoint:IsA(\"RemoteEvent\")\n\tend\n\tlocal pending=C.text(scroll,{Name=\"ComingSoon\",Size=UDim2.new(1,-8,0,34),Text=\"Settings and codes \u2014 coming soon\",TextColor3=T.Muted,TextSize=14,LayoutOrder=-1})\n\tlocal pendingControls={}\n\tlocal function registerPending(button,refresh)\n\t\ttable.insert(pendingControls,function(available)\n\t\t\tbutton.Interactable=available;button.Active=available;button.Selectable=available\n\t\t\trefresh(available)\n\t\tend)\n\tend\n\tlocal states={Music=true,[\"Sound Effects\"]=true,[\"Pet Effects\"]=true,[\"Other Players' Pets\"]=true,[\"Screen Shake\"]=true,Notifications=true}\n\tfor label,value in pairs(states) do\n\t\tlocal row=C.card(scroll,label,UDim2.new(1,-8,0,58),T.White);C.text(row,{Position=UDim2.fromOffset(16,0),Size=UDim2.new(1,-130,1,0),Text=label,TextXAlignment=Enum.TextXAlignment.Left,TextSize=16})\n\t\tlocal toggle=C.button(row,\"Toggle\",value and \"ON\" or \"OFF\",value and T.Green or T.Red,UDim2.fromOffset(86,38));toggle.AnchorPoint=Vector2.new(1,.5);toggle.Position=UDim2.new(1,-10,.5,0)\n\t\tregisterPending(toggle,function(available)\n\t\t\ttoggle.Text=available and (states[label] and \"ON\" or \"OFF\") or \"SOON\"\n\t\t\ttoggle.BackgroundColor3=available and (states[label] and T.Green or T.Red) or T.Muted\n\t\tend)\n\t\tconnect(toggle.Activated,function()\n\t\t\tif not endpointAvailable() then return end\n\t\t\tstates[label]=not states[label];toggle.Text=states[label] and \"ON\" or \"OFF\";toggle.BackgroundColor3=states[label] and T.Green or T.Red\n\t\t\tBridge.Request(\"UpdateSetting\",{Setting=label,Value=states[label]})\n\t\tend)\n\tend\n\tlocal graphics=C.card(scroll,\"Graphics\",UDim2.new(1,-8,0,74),Color3.fromRGB(230,249,247));C.text(graphics,{Position=UDim2.fromOffset(16,0),Size=UDim2.new(.35,0,1,0),Text=\"GRAPHICS\",TextXAlignment=Enum.TextXAlignment.Left,TextSize=16})\n\tlocal levels=n(\"Frame\",{Position=UDim2.new(.35,0,0,0),Size=UDim2.new(.65,-12,1,0),BackgroundTransparency=1},graphics);n(\"UIListLayout\",{FillDirection=Enum.FillDirection.Horizontal,VerticalAlignment=Enum.VerticalAlignment.Center,Padding=UDim.new(0,8)},levels)\n\tfor _,level in ipairs({\"LOW\",\"MEDIUM\",\"HIGH\"}) do\n\t\tlocal b=C.button(levels,level,level,level==\"MEDIUM\" and T.Teal or T.Blue,UDim2.new(.31,0,0,38));b.TextSize=12\n\t\tregisterPending(b,function(available) b.BackgroundColor3=available and (level==\"MEDIUM\" and T.Teal or T.Blue) or T.Muted end)\n\t\tconnect(b.Activated,function() if endpointAvailable() then Bridge.Request(\"UpdateSetting\",{Setting=\"Graphics\",Value=level}) end end)\n\tend\n\tlocal hide=C.button(scroll,\"HideUI\",\"HIDE UI\",T.Muted,UDim2.new(1,-8,0,48));connect(hide.Activated,function() hud.Visible=false;showUI.Visible=true;if activeWindow then activeWindow.Close(true) end end)\n\tlocal redeem=C.card(scroll,\"RedeemCode\",UDim2.new(1,-8,0,88),Color3.fromRGB(255,246,220));C.padding(redeem,10)\n\tlocal code=n(\"TextBox\",{Name=\"Code\",Size=UDim2.new(.68,-6,0,50),BackgroundColor3=T.White,PlaceholderText=\"Enter redeem code\",Text=\"\",TextColor3=T.Ink,TextSize=16,Font=Enum.Font.GothamBold,ClearTextOnFocus=false},redeem);C.corner(code,12);C.stroke(code,3);C.padding(code,12)\n\tlocal redeemButton=C.button(redeem,\"Redeem\",\"REDEEM\",T.Yellow,UDim2.new(.32,-6,0,50));redeemButton.Position=UDim2.new(.68,6,0,0)\n\tregisterPending(redeemButton,function(available)\n\t\tredeemButton.Text=available and \"REDEEM\" or \"SOON\";redeemButton.BackgroundColor3=available and T.Yellow or T.Muted\n\t\tcode.TextEditable=available;code.PlaceholderText=available and \"Enter redeem code\" or \"Codes coming soon\"\n\tend)\n\tconnect(redeemButton.Activated,function()\n\t\tif not endpointAvailable() then return end\n\t\tBridge.Request(\"RedeemCode\",{Code=code.Text});code.Text=\"\"\n\tend)\n\tlocal function refreshAvailability()\n\t\tif not screen.Parent then return end\n\t\tlocal available=endpointAvailable();pending.Visible=not available\n\t\tfor _,refresh in ipairs(pendingControls) do refresh(available) end\n\tend\n\tlocal function endpointChanged(object)\n\t\tif object.Name==\"UIRequest\" or object.Name==\"AnimalKingdomRemotes\" then task.defer(refreshAvailability) end\n\tend\n\tconnect(storage.DescendantAdded,endpointChanged);connect(storage.DescendantRemoving,endpointChanged)\n\trefreshAvailability()\nend\n\n-- Popups prepared for server-driven presentation.\nlocal tradeRequest=C.card(popups,\"TradeRequest\",UDim2.fromOffset(390,180),T.White);tradeRequest.AnchorPoint=Vector2.new(.5,.5);tradeRequest.Position=UDim2.fromScale(.5,.5);tradeRequest.Visible=false;tradeRequest.ZIndex=70\nC.text(tradeRequest,{Position=UDim2.fromOffset(20,18),Size=UDim2.new(1,-40,0,62),Text=\"PLAYER wants to trade!\",TextSize=22,ZIndex=71})\nlocal accept=C.button(tradeRequest,\"Accept\",\"ACCEPT\",T.Green,UDim2.new(.43,0,0,48));accept.Position=UDim2.new(.05,0,1,-64);accept.ZIndex=72\nlocal decline=C.button(tradeRequest,\"Decline\",\"DECLINE\",T.Red,UDim2.new(.43,0,0,48));decline.Position=UDim2.new(.52,0,1,-64);decline.ZIndex=72\nconnect(accept.Activated,function() Bridge.Request(\"RespondTradeRequest\",{Accepted=true});tradeRequest.Visible=false end)\nconnect(decline.Activated,function() Bridge.Request(\"RespondTradeRequest\",{Accepted=false});tradeRequest.Visible=false end)\nlocal confirmation=C.card(popups,\"Confirmation\",UDim2.fromOffset(400,210),T.White);confirmation.AnchorPoint=Vector2.new(.5,.5);confirmation.Position=UDim2.fromScale(.5,.5);confirmation.Visible=false;confirmation.ZIndex=70\nlocal notification=C.card(popups,\"Notification\",UDim2.fromOffset(380,76),T.White);notification.AnchorPoint=Vector2.new(.5,0);notification.Position=UDim2.fromScale(.5,.1);notification.Visible=false;notification.ZIndex=80\n\n-- Responsive scaling and layout changes. No RenderStepped loop.\nlocal camera=workspace.CurrentCamera\nlocal function resize()\n\tlocal viewport=camera and camera.ViewportSize or Vector2.new(1366,768)\n\tlocal mobile=viewport.X < 700\n\tfor _,window in pairs(windows) do\n\t\twindow.Root.Size=mobile and UDim2.fromScale(.93,.82) or UDim2.fromScale(.52,.64)\n\t\twindow.Root.Position=mobile and UDim2.fromScale(.52,.53) or UDim2.fromScale(.5,.53)\n\t\tlocal constraint = window.Root:FindFirstChildOfClass(\"UISizeConstraint\")\n\t\tif constraint then\n\t\t\tconstraint.MinSize = Vector2.new(math.min(300, math.max(1, viewport.X - 24)), math.min(360, math.max(1, viewport.Y - 40)))\n\t\tend\n\tend\n\tcurrencyBar.Size=mobile and UDim2.new(.82,0,0,48) or UDim2.new(.42,0,0,52)\n\tnav.Size=mobile and UDim2.fromOffset(142,204) or UDim2.fromOffset(158,226)\n\tnav.Position=mobile and UDim2.new(0,8,.58,0) or UDim2.new(0,16,.57,0)\nend\nlocal viewportConnection\nlocal function bindCamera()\n\tif viewportConnection then viewportConnection:Disconnect() end\n\tcamera = workspace.CurrentCamera\n\tif camera then viewportConnection = camera:GetPropertyChangedSignal(\"ViewportSize\"):Connect(resize) end\n\tresize()\nend\nconnect(workspace:GetPropertyChangedSignal(\"CurrentCamera\"), bindCamera)\nbindCamera()\n\nscreen.Destroying:Connect(function()\n\tif viewportConnection then viewportConnection:Disconnect() end\n\tfor _,connection in ipairs(connections) do connection:Disconnect() end\nend)\n"}, {"path": ["StarterGui", "AnimalKingdomUI", "RemoteBridge"], "source": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Knit = require(ReplicatedStorage.Packages.Knit)\n\nlocal Bridge = {}\nlocal localSignal = Instance.new(\"BindableEvent\")\nBridge.Requested = localSignal.Event -- Integration/test seam; never grants rewards locally.\n\nfunction Bridge.Request(action, payload)\n\tlocalSignal:Fire(action, payload)\n\tif action == \"UnlockBiome\" then\n\t\treturn Knit.OnStart():andThen(function()\n\t\t\treturn Knit.GetService(\"ProgressionService\"):UnlockBiome(payload.BiomeId)\n\t\tend):catch(function(err)\n\t\t\twarn(\"[AnimalKingdomUI] Biome unlock request failed: \" .. tostring(err))\n\t\tend)\n\tend\n\tlocal remotes = ReplicatedStorage:FindFirstChild(\"AnimalKingdomRemotes\")\n\tlocal remote = remotes and remotes:FindFirstChild(\"UIRequest\")\n\tif remote and remote:IsA(\"RemoteEvent\") then\n\t\tremote:FireServer(action, payload)\n\telse\n\t\twarn(string.format(\"[AnimalKingdomUI] Server integration pending for %s\", action))\n\tend\nend\n\nreturn Bridge\n"}, {"path": ["StarterGui", "WeatherEventUI", "WeatherEventController"], "source": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ContentProvider = game:GetService(\"ContentProvider\")\nlocal RunService = game:GetService(\"RunService\")\nlocal TweenService = game:GetService(\"TweenService\")\n\nlocal screen = script.Parent\nlocal definitions = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"EventDefinitions\"))\nlocal weatherState = ReplicatedStorage:WaitForChild(\"WeatherState\")\n\nlocal generation = 0\nlocal activeKey\nlocal activeCard\nlocal countdownLabel\nlocal endsAt = 0\nlocal hasInitialSnapshot = false\nlocal refreshQueued = false\nlocal runningTweens = {}\nlocal DEBUG_UI = RunService:IsStudio()\n\n-- Artwork is UI-only. EventDefinitions remains the source for all event text.\nlocal EVENT_CARD_IMAGES = {\n\tSunnySkies = \"rbxassetid://88425768751804\",\n\tRainyDay = \"rbxassetid://114674921602382\",\n\tThunderstorm = \"rbxassetid://92403835613689\",\n\tSnowfall = \"rbxassetid://76661117656518\",\n\tFoggy = \"rbxassetid://99104255943045\",\n\tWindy = \"rbxassetid://112381280370991\",\n\tHeatwave = \"rbxassetid://76106281136407\",\n\tAurora = \"rbxassetid://80700863827597\",\n\tBloodMoon = \"rbxassetid://74180652862291\",\n\tMeteorShower = \"rbxassetid://124363674183252\",\n\tSpiritNight = \"rbxassetid://76438929387740\",\n\tRainbow = \"rbxassetid://107219758422340\",\n\tChaos = \"rbxassetid://131557230584021\",\n\tInverted = \"rbxassetid://92045192481117\",\n\tNightmare = \"rbxassetid://105268491188486\",\n\tVoid = \"rbxassetid://79390179989574\",\n\tGolden = \"rbxassetid://140425806946255\",\n\tAdminAbuse = \"rbxassetid://138046290685051\",\n}\nlocal IMAGE_TO_EVENT = {}\nfor eventId, imageId in pairs(EVENT_CARD_IMAGES) do IMAGE_TO_EVENT[imageId] = eventId end\n\ntask.spawn(function()\n\tlocal images = {}\n\t-- Pass typed image instances: raw content strings use the generic loader,\n\t-- which can report Failure for otherwise valid image/decal artwork.\n\tfor eventId, imageId in pairs(EVENT_CARD_IMAGES) do\n\t\tlocal image = Instance.new(\"ImageLabel\")\n\t\timage.Name = eventId .. \"Preload\"\n\t\timage.Image = imageId\n\t\ttable.insert(images, image)\n\tend\n\tlocal ok, err = pcall(function()\n\t\tContentProvider:PreloadAsync(images, function(imageId, status)\n\t\t\tif DEBUG_UI and status ~= Enum.AssetFetchStatus.Success then\n\t\t\t\twarn(\"[WeatherEventUI] Image preload failed: \" .. tostring(IMAGE_TO_EVENT[imageId]) .. \" \" .. imageId .. \" (\" .. status.Name .. \")\")\n\t\t\tend\n\t\tend)\n\tend)\n\tfor _, image in ipairs(images) do image:Destroy() end\n\tif not ok then warn(\"[WeatherEventUI] Image preload error: \" .. tostring(err)) end\nend)\n\nlocal function make(className, properties, parent)\n\tlocal instance = Instance.new(className)\n\tfor property, value in pairs(properties) do\n\t\tinstance[property] = value\n\tend\n\tinstance.Parent = parent\n\treturn instance\nend\n\nlocal function tween(instance, seconds, properties, style, direction)\n\tlocal animation = TweenService:Create(instance, TweenInfo.new(seconds, style or Enum.EasingStyle.Quad, direction or Enum.EasingDirection.Out), properties)\n\ttable.insert(runningTweens, animation)\n\tanimation.Completed:Connect(function()\n\t\tlocal index = table.find(runningTweens, animation)\n\t\tif index then table.remove(runningTweens, index) end\n\tend)\n\tanimation:Play()\n\treturn animation\nend\n\nlocal function cancelTweens()\n\tlocal oldTweens = runningTweens\n\trunningTweens = {}\n\tfor _, animation in ipairs(oldTweens) do animation:Cancel() end\nend\n\nlocal function formatTime(deadline)\n\tlocal seconds = math.max(0, math.ceil(deadline - workspace:GetServerTimeNow()))\n\treturn string.format(\"%d:%02d\", math.floor(seconds / 60), seconds % 60)\nend\n\nlocal function currentScale()\n\tlocal size = screen.AbsoluteSize\n\treturn math.clamp(math.min(size.X / 500, size.Y / 330), 0.72, 1)\nend\n\nlocal function cardWidth(compact)\n\tlocal width = math.max(320, screen.AbsoluteSize.X)\n\tif compact then return math.floor(math.min(width - 24, 320, math.max(220, width * (width < 700 and 0.63 or 0.3)))) end\n\treturn math.floor(math.min(600, math.max(260, width * (width < 700 and 0.88 or 0.52)), width - 24))\nend\n\nlocal ARTWORK_ASPECT_RATIO = 1.6\nlocal function imageSize(compact)\n\tlocal width = cardWidth(compact)\n\treturn UDim2.fromOffset(width, math.floor(width / ARTWORK_ASPECT_RATIO))\nend\n\nlocal function removeCard(smooth)\n\tgeneration += 1\n\tcancelTweens()\n\tlocal card = activeCard\n\tactiveCard = nil\n\tcountdownLabel = nil\n\tactiveKey = nil\n\tendsAt = 0\n\tif not smooth then\n\t\t-- A Break fade can still be finishing when an admin starts another event.\n\t\tfor _, child in ipairs(screen:GetChildren()) do\n\t\t\tif child.Name == \"ActiveEventCard\" or child.Name == \"CustomEventImage\" then child:Destroy() end\n\t\tend\n\t\treturn\n\tend\n\tif not card then return end\n\tif DEBUG_UI then print(\"[WeatherEventUI] Hiding card for Break\") end\n\tlocal scale = card:FindFirstChildOfClass(\"UIScale\")\n\tif card:IsA(\"ImageLabel\") then\n\t\ttween(card, 0.22, { ImageTransparency = 1 })\n\telse\n\t\ttween(card, 0.22, { BackgroundTransparency = 1 })\n\tend\n\tif scale then tween(scale, 0.22, { Scale = scale.Scale * 0.85 }) end\n\tfor _, descendant in ipairs(card:GetDescendants()) do\n\t\tif descendant:IsA(\"ImageLabel\") then\n\t\t\ttween(descendant, 0.22, { ImageTransparency = 1 })\n\t\telseif descendant:IsA(\"TextLabel\") then\n\t\t\ttween(descendant, 0.22, { TextTransparency = 1, BackgroundTransparency = 1 })\n\t\telseif descendant:IsA(\"Frame\") then\n\t\t\ttween(descendant, 0.22, { BackgroundTransparency = 1 })\n\t\tend\n\tend\n\ttask.delay(0.24, function() card:Destroy() end)\nend\n\nlocal function createCard(definition, deadline)\n\tlocal secret = definition.IsSecret or definition.Category == \"Secret\"\n\tlocal accent = secret and Color3.fromRGB(246, 170, 255) or Color3.fromRGB(129, 241, 215)\n\tlocal dark = secret and Color3.fromRGB(51, 30, 75) or Color3.fromRGB(27, 61, 82)\n\tlocal card = make(\"Frame\", {\n\t\tName = \"ActiveEventCard\", AnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5, 0.45), Size = UDim2.fromOffset(420, 254),\n\t\tBackgroundColor3 = dark, BackgroundTransparency = 0.06, BorderSizePixel = 0,\n\t\tClipsDescendants = true, ZIndex = 1,\n\t}, screen)\n\tmake(\"UICorner\", { CornerRadius = UDim.new(0, 22) }, card)\n\tlocal stroke = make(\"UIStroke\", { Color = accent, Thickness = secret and 3 or 2, Transparency = 0.12 }, card)\n\tmake(\"UIGradient\", { Color = ColorSequence.new(dark, secret and Color3.fromRGB(104, 45, 116) or Color3.fromRGB(37, 117, 137)), Rotation = 25 }, card)\n\tlocal scale = make(\"UIScale\", { Scale = currentScale() }, card)\n\tmake(\"UIPadding\", { PaddingLeft = UDim.new(0, 16), PaddingRight = UDim.new(0, 16), PaddingTop = UDim.new(0, 14), PaddingBottom = UDim.new(0, 14) }, card)\n\n\tlocal imageArea = make(\"Frame\", {\n\t\tName = \"EventImageArea\", Position = UDim2.fromOffset(0, 22), Size = UDim2.fromOffset(94, 94),\n\t\tBackgroundColor3 = accent, BackgroundTransparency = 0.65, BorderSizePixel = 0,\n\t}, card)\n\tmake(\"UICorner\", { CornerRadius = UDim.new(0, 17) }, imageArea)\n\tmake(\"UIGradient\", { Color = ColorSequence.new(accent, dark), Rotation = 60 }, imageArea)\n\tlocal imageId = definition.ImageId\n\tif type(imageId) == \"string\" and imageId ~= \"\" then\n\t\tmake(\"ImageLabel\", { Name = \"EventImage\", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Image = imageId, ScaleType = Enum.ScaleType.Fit }, imageArea)\n\telse\n\t\tmake(\"TextLabel\", { Name = \"FallbackIcon\", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = secret and \"\u2726\" or \"\u2727\", TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 58, Font = Enum.Font.GothamBold }, imageArea)\n\tend\n\n\tlocal function label(name, value, position, size, textSize, bold, color)\n\t\tlocal item = make(\"TextLabel\", {\n\t\t\tName = name, BackgroundTransparency = 1, Position = position, Size = size,\n\t\t\tText = value, TextColor3 = color or Color3.fromRGB(255, 255, 255),\n\t\t\tTextSize = textSize, TextScaled = false, TextWrapped = true,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,\n\t\t\tFont = bold and Enum.Font.GothamBold or Enum.Font.GothamMedium,\n\t\t}, card)\n\t\tmake(\"UITextSizeConstraint\", { MinTextSize = 10, MaxTextSize = textSize }, item)\n\t\treturn item\n\tend\n\tlocal badge = label(\"Badge\", secret and \"SECRET EVENT\" or \"KINGDOM EVENT\", UDim2.fromOffset(108, 0), UDim2.new(1, -108, 0, 21), 12, true, accent)\n\tlocal title = label(\"Title\", definition.DisplayName, UDim2.fromOffset(108, 24), UDim2.new(1, -108, 0, 37), 25, true)\n\tlocal description = label(\"Description\", definition.Description, UDim2.fromOffset(108, 63), UDim2.new(1, -108, 0, 54), 14, false, Color3.fromRGB(235, 241, 251))\n\tlocal effects = definition.DisplayEffects or {}\n\tlocal effectsText = #effects > 0 and table.concat(effects, \"  \u2022  \") or \"Event details coming soon\"\n\tlocal effectsLabel = label(\"DisplayEffects\", effectsText, UDim2.fromOffset(0, 132), UDim2.new(1, 0, 0, 55), 15, true, accent)\n\tlocal timer = label(\"Countdown\", \"Time Left: \" .. formatTime(deadline), UDim2.fromOffset(0, 197), UDim2.new(1, 0, 0, 32), 18, true)\n\treturn card, scale, stroke, imageArea, badge, title, description, effectsLabel, timer\nend\n\nlocal function createCustomCard(imageId, deadline)\n\tlocal card = make(\"ImageLabel\", {\n\t\tName = \"CustomEventImage\", AnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5, 0.46), Size = imageSize(false),\n\t\tImage = imageId, ImageTransparency = 0, ImageColor3 = Color3.new(1, 1, 1),\n\t\tBackgroundTransparency = 1, BorderSizePixel = 0,\n\t\tScaleType = Enum.ScaleType.Fit, ClipsDescendants = true, Visible = true, ZIndex = 10,\n\t}, screen)\n\tmake(\"UICorner\", { CornerRadius = UDim.new(0, 18) }, card)\n\tlocal scale = make(\"UIScale\", { Scale = 1 }, card)\n\t-- The artwork contains no live time value. Keep a legible footer bound to\n\t-- the same server EndsAt snapshot used by the admin room and fallback card.\n\tlocal timer = make(\"TextLabel\", {\n\t\tName = \"Countdown\", AnchorPoint = Vector2.new(0.5, 1),\n\t\tPosition = UDim2.new(0.5, 0, 1, -5), Size = UDim2.new(1, -14, 0, 26),\n\t\tBackgroundColor3 = Color3.fromRGB(17, 28, 42), BackgroundTransparency = 0.1,\n\t\tBorderSizePixel = 0, Text = \"Time Left: \" .. formatTime(deadline),\n\t\tTextColor3 = Color3.new(1, 1, 1), TextSize = 15, Font = Enum.Font.GothamBold,\n\t\tTextScaled = false, ZIndex = 11,\n\t}, card)\n\tmake(\"UICorner\", { CornerRadius = UDim.new(0, 8) }, timer)\n\treturn card, scale, timer\nend\n\nlocal function showEvent(definition, eventId, key, deadline, newEvent)\n\tremoveCard(false)\n\tactiveKey = key\n\tendsAt = deadline\n\tlocal token = generation\n\tlocal imageId = EVENT_CARD_IMAGES[eventId]\n\tif not imageId and DEBUG_UI then warn(\"[WeatherEventUI] Missing card image for: \" .. tostring(eventId)) end\n\tlocal custom = imageId ~= nil\n\tlocal card, scale, stroke, imageArea, badge, title, description, effectsLabel, timer\n\tif custom then\n\t\tcard, scale, timer = createCustomCard(imageId, deadline)\n\t\tif DEBUG_UI then\n\t\t\tprint(\"[WeatherEventUI] Showing custom card:\", eventId, imageId)\n\t\tend\n\telse\n\t\tcard, scale, stroke, imageArea, badge, title, description, effectsLabel, timer = createCard(definition, deadline)\n\tend\n\tactiveCard = card\n\tcountdownLabel = timer\n\tlocal baseScale = custom and 1 or currentScale()\n\tif custom and not newEvent then\n\t\tcard.AnchorPoint = Vector2.new(1, 0)\n\t\tcard.Position = UDim2.new(1, -15, 0, 15)\n\t\tcard.Size = imageSize(true)\n\t\tcard:SetAttribute(\"Docked\", true)\n\t\tif DEBUG_UI then print(\"[WeatherEventUI] Docking custom card (joined mid-event)\") end\n\t\treturn\n\tend\n\n\tlocal function dock()\n\t\tif token ~= generation then return end\n\t\tif custom then\n\t\t\tcard:SetAttribute(\"Docked\", true)\n\t\t\tif DEBUG_UI then print(\"[WeatherEventUI] Docking custom card\") end\n\t\t\ttween(card, 0.48, {\n\t\t\t\tAnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -15, 0, 15),\n\t\t\t\tSize = imageSize(true),\n\t\t\t}, Enum.EasingStyle.Quart)\n\t\t\treturn\n\t\tend\n\t\ttween(card, 0.42, {\n\t\t\tAnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -14, 0, 14),\n\t\t\tSize = UDim2.fromOffset(300, 122),\n\t\t}, Enum.EasingStyle.Quart)\n\t\ttween(imageArea, 0.42, { Position = UDim2.fromOffset(0, 25), Size = UDim2.fromOffset(65, 65) })\n\t\tbadge.Position = UDim2.fromOffset(76, 0)\n\t\tbadge.Size = UDim2.new(1, -76, 0, 16)\n\t\tbadge.TextSize = 10\n\t\ttitle.Position = UDim2.fromOffset(76, 17)\n\t\ttitle.Size = UDim2.new(1, -76, 0, 27)\n\t\ttitle.TextSize = 18\n\t\tdescription.Visible = false\n\t\teffectsLabel.Position = UDim2.fromOffset(76, 46)\n\t\teffectsLabel.Size = UDim2.new(1, -76, 0, 35)\n\t\teffectsLabel.TextSize = 11\n\t\ttimer.Position = UDim2.fromOffset(76, 81)\n\t\ttimer.Size = UDim2.new(1, -76, 0, 20)\n\t\ttimer.TextSize = 13\n\tend\n\n\ttask.spawn(function()\n\t\tif custom then\n\t\t\tscale.Scale = 0.9\n\t\t\ttween(scale, 0.28, { Scale = baseScale }, Enum.EasingStyle.Back).Completed:Wait()\n\t\t\tif token ~= generation then return end\n\t\tend\n\t\tif newEvent then\n\t\t\t-- Exactly three visible pulses for players present when this event started.\n\t\t\tfor _ = 1, 3 do\n\t\t\t\tif token ~= generation then return end\n\t\t\t\ttween(scale, 0.28, { Scale = baseScale * 1.055 }, Enum.EasingStyle.Sine).Completed:Wait()\n\t\t\t\tif token ~= generation then return end\n\t\t\t\tif not custom then\n\t\t\t\t\ttween(stroke, 0.20, { Transparency = 0.55 }, Enum.EasingStyle.Sine).Completed:Wait()\n\t\t\t\t\tif token ~= generation then return end\n\t\t\t\tend\n\t\t\t\ttween(scale, 0.28, { Scale = baseScale }, Enum.EasingStyle.Sine).Completed:Wait()\n\t\t\t\tif token ~= generation then return end\n\t\t\t\tif not custom then\n\t\t\t\t\ttween(stroke, 0.20, { Transparency = 0.12 }, Enum.EasingStyle.Sine).Completed:Wait()\n\t\t\t\tend\n\t\t\tend\n\t\telse\n\t\t\tif not custom then\n\t\t\t\tscale.Scale = baseScale * 0.92\n\t\t\t\ttween(scale, 0.26, { Scale = baseScale }, Enum.EasingStyle.Back).Completed:Wait()\n\t\t\tend\n\t\tend\n\t\tdock()\n\tend)\nend\n\nlocal function refreshFromState()\n\tlocal phase = weatherState:GetAttribute(\"Phase\")\n\tlocal eventId = weatherState:GetAttribute(\"EventId\")\n\tlocal startedAt = weatherState:GetAttribute(\"StartedAt\")\n\tlocal deadline = weatherState:GetAttribute(\"EndsAt\")\n\tlocal definition = type(eventId) == \"string\" and definitions[eventId]\n\tlocal valid = phase == \"Event\" and type(eventId) == \"string\" and eventId ~= \"\" and type(startedAt) == \"number\"\n\t\tand type(deadline) == \"number\" and startedAt > 0 and deadline > startedAt\n\tif not valid then\n\t\tif activeCard then removeCard(phase == \"Break\") end\n\t\thasInitialSnapshot = true\n\t\treturn\n\tend\n\tlocal key = eventId .. \":\" .. tostring(startedAt)\n\tif key == activeKey then\n\t\tendsAt = deadline\n\t\thasInitialSnapshot = true\n\t\treturn\n\tend\n\tlocal newEvent = hasInitialSnapshot\n\thasInitialSnapshot = true\n\tif deadline <= workspace:GetServerTimeNow() then return end\n\tif not definition then\n\t\tlocal eventName = weatherState:GetAttribute(\"EventName\")\n\t\tif type(eventName) ~= \"string\" or eventName == \"\" then eventName = eventId end\n\t\tdefinition = {\n\t\t\tDisplayName = eventName,\n\t\t\tDescription = \"An event is active in the kingdom.\",\n\t\t\tDisplayEffects = {}, IsSecret = false,\n\t\t}\n\tend\n\tshowEvent(definition, eventId, key, deadline, newEvent)\nend\n\nweatherState.AttributeChanged:Connect(function(attribute)\n\tif attribute ~= \"Phase\" and attribute ~= \"EventId\" and attribute ~= \"StartedAt\" and attribute ~= \"EndsAt\" then return end\n\tif refreshQueued then return end\n\trefreshQueued = true\n\ttask.defer(function()\n\t\trefreshQueued = false\n\t\trefreshFromState()\n\tend)\nend)\nrefreshFromState()\n\nscreen:GetPropertyChangedSignal(\"AbsoluteSize\"):Connect(function()\n\tif activeCard then\n\t\tif activeCard:IsA(\"ImageLabel\") then\n\t\t\tactiveCard.Size = imageSize(activeCard:GetAttribute(\"Docked\") == true)\n\t\telse\n\t\t\tlocal scale = activeCard:FindFirstChildOfClass(\"UIScale\")\n\t\t\tif scale then scale.Scale = currentScale() end\n\t\tend\n\tend\nend)\n\ntask.spawn(function()\n\twhile screen.Parent do\n\t\tif countdownLabel then\n\t\t\tcountdownLabel.Text = \"Time Left: \" .. formatTime(endsAt)\n\t\tend\n\t\ttask.wait(0.25)\n\tend\nend)\n"}, {"path": ["StarterPlayer", "StarterPlayerScripts", "WeatherVisualController"], "source": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal RunService = game:GetService(\"RunService\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal TweenService = game:GetService(\"TweenService\")\n\nlocal DEBUG_VISUALS = RunService:IsStudio()\nlocal TRANSITION = 2\nif DEBUG_VISUALS then print(\"[WeatherVisuals] Script starting\") end\nlocal state = ReplicatedStorage:WaitForChild(\"WeatherState\")\nlocal definitions = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"EventDefinitions\"))\nlocal rng = Random.new()\n\nlocal function color(r, g, b)\n\treturn Color3.fromRGB(r, g, b)\nend\n\n-- Every event has its own lighting recipe. Particle and sky details are added below.\nlocal presets = {\n\tSunnySkies = { clock = 13, brightness = 3.2, exposure = 0.16, fog = 100000, atmosphere = 0.1, tint = color(255, 244, 215), saturation = 0.16, bloom = 0.22, rays = 0.11, clouds = 0.06 },\n\tRainyDay = { clock = 15, brightness = 1.35, exposure = -0.18, fog = 530, atmosphere = 0.47, tint = color(173, 198, 225), saturation = -0.18, bloom = 0.08, rays = 0, clouds = 0.92, particles = \"Rain\" },\n\tThunderstorm = { clock = 18, brightness = 0.75, exposure = -0.38, fog = 280, fogStart = 0, atmosphere = 0.63, tint = color(118, 145, 183), saturation = -0.32, bloom = 0.15, rays = 0, clouds = 1, particles = \"HeavyRain\", extraParticles = \"WindStreaks\", loop = \"Lightning\" },\n\tSnowfall = { clock = 11, brightness = 2.1, exposure = 0.02, fog = 440, fogStart = 0, atmosphere = 0.47, tint = color(188, 223, 255), saturation = -0.34, bloom = 0.26, rays = 0.02, clouds = 0.75, particles = \"Snow\" },\n\tFoggy = { clock = 10, brightness = 1.25, exposure = -0.15, fog = 105, fogStart = 0, atmosphere = 0.74, tint = color(167, 187, 203), saturation = -0.48, bloom = 0.03, blur = 2, rays = 0, clouds = 0.76 },\n\tWindy = { clock = 14, brightness = 2, exposure = -0.02, fog = 850, atmosphere = 0.32, tint = color(207, 226, 217), saturation = 0.02, bloom = 0.08, rays = 0.02, clouds = 0.8, particles = \"Leaves\", extraParticles = \"WindStreaks\", loop = \"Wind\" },\n\tHeatwave = { clock = 14, brightness = 3.35, exposure = 0.28, fog = 480, atmosphere = 0.4, tint = color(255, 206, 145), saturation = 0.19, bloom = 0.38, blur = 0.7, rays = 0.14, clouds = 0.04, particles = \"Haze\" },\n\tAurora = { clock = 0, brightness = 1.1, exposure = -0.12, fog = 100000, atmosphere = 0.15, tint = color(164, 196, 244), saturation = 0.32, bloom = 0.5, rays = 0, clouds = 0.08, particles = \"Stars\", sky = \"Aurora\" },\n\tBloodMoon = { clock = 0, brightness = 0.7, exposure = -0.3, fog = 100000, fogStart = 0, atmosphere = 0.2, tint = color(211, 89, 103), saturation = 0.05, bloom = 0.3, rays = 0, clouds = 0.52, particles = \"Ash\", sky = \"BloodMoon\" },\n\tMeteorShower = { clock = 0, brightness = 0.95, exposure = -0.2, fog = 950, atmosphere = 0.28, tint = color(159, 180, 237), saturation = 0.2, bloom = 0.45, rays = 0, clouds = 0.03, particles = \"Stars\", loop = \"Meteors\" },\n\tSpiritNight = { clock = 1, brightness = 1, exposure = -0.18, fog = 390, atmosphere = 0.48, tint = color(134, 219, 235), saturation = 0.24, bloom = 0.44, rays = 0, clouds = 0.25, particles = \"SpiritMist\", loop = \"Spirits\" },\n\tRainbow = { clock = 14, brightness = 3.15, exposure = 0.16, fog = 100000, atmosphere = 0.06, tint = color(255, 240, 254), saturation = 0.4, bloom = 0.34, rays = 0.09, clouds = 0.12, particles = \"Sparkles\", sky = \"Rainbow\" },\n\tChaos = { clock = 19, brightness = 2, exposure = 0.04, fog = 410, atmosphere = 0.52, tint = color(255, 143, 209), saturation = 0.4, bloom = 0.5, rays = 0, clouds = 0.72, particles = \"Chaos\", loop = \"Chaos\" },\n\tInverted = { clock = 22, brightness = 1.55, exposure = 0.2, fog = 420, atmosphere = 0.55, tint = color(117, 250, 203), saturation = -0.38, bloom = 0.4, rays = 0, clouds = 0.6, particles = \"Inverted\" },\n\tNightmare = { clock = 0, brightness = 0.65, exposure = -0.39, fog = 240, atmosphere = 0.66, tint = color(166, 77, 127), saturation = -0.36, bloom = 0.25, rays = 0, clouds = 0.84, particles = \"Ash\", loop = \"Nightmare\" },\n\tVoid = { clock = 0, brightness = 0.65, exposure = -0.37, fog = 180, atmosphere = 0.69, tint = color(129, 85, 204), saturation = -0.18, bloom = 0.59, blur = 1.5, rays = 0, clouds = 0.86, particles = \"Void\", sky = \"Void\" },\n\tGolden = { clock = 16, brightness = 3.5, exposure = 0.3, fog = 1400, atmosphere = 0.22, tint = color(255, 204, 92), saturation = 0.31, bloom = 0.52, rays = 0.16, clouds = 0.1, particles = \"Gold\" },\n\tAdminAbuse = { clock = 17, brightness = 2.5, exposure = 0.09, fog = 520, atmosphere = 0.38, tint = color(255, 198, 247), saturation = 0.38, bloom = 0.52, rays = 0.06, clouds = 0.58, particles = \"Admin\", loop = \"Admin\" },\n}\n\n-- WeatherState uses the canonical IDs in EventDefinitions. Accept the older\n-- underscored spellings as input without changing the server's event contract.\nlocal aliases = {\n\tSunny_Skies = \"SunnySkies\", Rainy_Day = \"RainyDay\", Blood_Moon = \"BloodMoon\",\n\tMeteor_Shower = \"MeteorShower\", Spirit_Night = \"SpiritNight\", Admin_Abuse = \"AdminAbuse\",\n}\n\nlocal lightingProperties = { \"Brightness\", \"ClockTime\", \"ExposureCompensation\", \"FogStart\", \"FogEnd\", \"FogColor\", \"Ambient\", \"OutdoorAmbient\", \"ColorShift_Top\", \"ColorShift_Bottom\" }\nlocal effectProperties = {\n\tAtmosphere = { \"Density\", \"Color\", \"Decay\", \"Haze\", \"Glare\", \"Offset\" },\n\tClouds = { \"Cover\", \"Density\", \"Color\", \"Enabled\" },\n\tColorCorrectionEffect = { \"Brightness\", \"Contrast\", \"Saturation\", \"TintColor\", \"Enabled\" },\n\tBloomEffect = { \"Intensity\", \"Size\", \"Threshold\", \"Enabled\" },\n\tSunRaysEffect = { \"Intensity\", \"Spread\", \"Enabled\" },\n\tDepthOfFieldEffect = { \"FarIntensity\", \"FocusDistance\", \"InFocusRadius\", \"NearIntensity\", \"Enabled\" },\n\tBlurEffect = { \"Size\", \"Enabled\" },\n}\nlocal original = {}\nfor _, property in ipairs(lightingProperties) do original[property] = Lighting[property] end\n-- The folder is a client-local index of managed effects. Roblox renders\n-- Atmosphere/post effects under Lighting and Clouds under Terrain, so the live\n-- instances cannot be placed inside this folder without disabling them.\nlocal visualFolder = Lighting:FindFirstChild(\"AK_WeatherVisuals\")\nif not visualFolder then\n\tvisualFolder = Instance.new(\"Folder\")\n\tvisualFolder.Name = \"AK_WeatherVisuals\"\n\tvisualFolder.Parent = Lighting\nend\nlocal function indexEffect(className, effect)\n\tlocal reference = visualFolder:FindFirstChild(className)\n\tif not reference or not reference:IsA(\"ObjectValue\") then\n\t\treference = Instance.new(\"ObjectValue\")\n\t\treference.Name = className\n\t\treference.Parent = visualFolder\n\tend\n\treference.Value = effect\nend\nlocal effects = {}\nlocal initialEffects = {}\nlocal createdEffects = {}\nlocal terrain = workspace.Terrain\nlocal requiredEffects = { \"Atmosphere\", \"ColorCorrectionEffect\", \"BloomEffect\", \"BlurEffect\", \"SunRaysEffect\", \"Clouds\" }\nlocal effectLabels = {\n\tColorCorrectionEffect = \"ColorCorrection\", BloomEffect = \"Bloom\",\n\tBlurEffect = \"Blur\", SunRaysEffect = \"SunRays\",\n}\n\nlocal function ensureEffect(className, parent)\n\tlocal effect = effects[className]\n\tif effect and effect.Parent == parent then\n\t\tif DEBUG_VISUALS then print(\"[WeatherVisuals] \" .. (effectLabels[className] or className) .. \" ready\") end\n\t\treturn effect\n\tend\n\teffect = parent:FindFirstChildOfClass(className)\n\tif effect and not initialEffects[className] then\n\t\tlocal snapshot = {}\n\t\tfor _, property in ipairs(effectProperties[className]) do snapshot[property] = effect[property] end\n\t\tinitialEffects[className] = snapshot\n\t\tcreatedEffects[className] = nil\n\tend\n\tif not effect then\n\t\tlocal ok, result = pcall(Instance.new, className)\n\t\tif not ok then\n\t\t\twarn(\"[WeatherVisuals] Cannot create \" .. className .. \": \" .. tostring(result))\n\t\t\treturn nil\n\t\tend\n\t\teffect = result\n\t\teffect.Name = \"AK_Weather\" .. className\n\t\tif effect:IsA(\"PostEffect\") then effect.Enabled = false end\n\t\tif className == \"Atmosphere\" then\n\t\t\teffect.Density = 0\n\t\t\teffect.Haze = 0\n\t\t\teffect.Glare = 0\n\t\telseif className == \"Clouds\" then\n\t\t\teffect.Cover = 0\n\t\t\teffect.Enabled = false\n\t\tend\n\t\teffect.Parent = parent\n\t\tcreatedEffects[className] = true\n\tend\n\teffects[className] = effect\n\tindexEffect(className, effect)\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] \" .. (effectLabels[className] or className) .. \" ready\") end\n\treturn effect\nend\n\n-- Capture the real map appearance before any weather instance is created.\nfor className, properties in pairs(effectProperties) do\n\tlocal parent = className == \"Clouds\" and terrain or Lighting\n\tlocal effect = parent:FindFirstChildOfClass(className)\n\tif effect then\n\t\tlocal snapshot = {}\n\t\tfor _, property in ipairs(properties) do snapshot[property] = effect[property] end\n\t\tinitialEffects[className] = snapshot\n\t\teffects[className] = effect\n\t\tindexEffect(className, effect)\n\tend\nend\n\nlocal generation = 0\nlocal activeKey\nlocal activeEventId\nlocal runtime\nlocal followConnection\nlocal runningTweens = {}\nlocal refreshQueued = false\nlocal activeSounds = {}\nlocal skyMoonSnapshots = {}\n\n-- World coordinates shared by every client. Only the nearby precipitation\n-- volume follows camera POSITION; environmental sky objects never follow it.\nlocal WORLD_SKY = {\n\tBloodMoon = Vector3.new(-6338, 8008, -23752),\n\tRainbow = Vector3.new(-500, 60, -2200),\n\tAurora = Vector3.new(-500, 850, -1700),\n\tMeteors = Vector3.new(-338, 1508, -1952),\n\tLightning = Vector3.new(-338, 658, -852),\n\tVoid = Vector3.new(-338, 108, 18),\n}\n\n-- Creator Store audio. Only the rain and thunder tracks are Roblox-owned;\n-- the wind/meteor clips are free Creator Store sound effects.\nlocal soundAssets = {\n\tRain = \"rbxassetid://1516791621\",\n\tThunder = \"rbxassetid://12222030\",\n\tWind = \"rbxassetid://8202539690\",\n\tEerieWind = \"rbxassetid://9114228918\",\n\tMeteor = \"rbxassetid://9120705982\",\n}\nlocal ambientSounds = {\n\tRainyDay = { \"Rain\", 0.42 }, Thunderstorm = { \"Rain\", 0.62 },\n\tSnowfall = { \"Wind\", 0.2 }, Foggy = { \"EerieWind\", 0.16 },\n\tWindy = { \"Wind\", 0.5 }, BloodMoon = { \"EerieWind\", 0.25 },\n\tSpiritNight = { \"EerieWind\", 0.19 }, Nightmare = { \"EerieWind\", 0.3 },\n\tVoid = { \"EerieWind\", 0.3 }, Chaos = { \"EerieWind\", 0.22 },\n\tAdminAbuse = { \"Rain\", 0.24 },\n}\n\nlocal function trackTween(instance, properties, seconds)\n\tif not instance then\n\t\twarn(\"[WeatherVisuals] Cannot tween a missing visual instance\")\n\t\treturn nil\n\tend\n\tlocal ok, animation = pcall(TweenService.Create, TweenService, instance, TweenInfo.new(seconds or TRANSITION, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), properties)\n\tif not ok then\n\t\twarn(\"[WeatherVisuals] Tween failed for \" .. instance.Name .. \": \" .. tostring(animation))\n\t\t-- Keep the preset visible even if a property cannot be tweened in Studio.\n\t\tfor property, value in pairs(properties) do\n\t\t\tlocal setOk, setError = pcall(function() instance[property] = value end)\n\t\t\tif not setOk then warn(\"[WeatherVisuals] Cannot set \" .. instance.Name .. \".\" .. property .. \": \" .. tostring(setError)) end\n\t\tend\n\t\treturn nil\n\tend\n\ttable.insert(runningTweens, animation)\n\tanimation.Completed:Connect(function()\n\t\tlocal index = table.find(runningTweens, animation)\n\t\tif index then table.remove(runningTweens, index) end\n\tend)\n\tanimation:Play()\n\treturn animation\nend\n\nlocal function cancelTweens()\n\t-- Cancel may fire Completed synchronously; swap the list first so its\n\t-- removal callback cannot skip every other active tween.\n\tlocal oldTweens = runningTweens\n\trunningTweens = {}\n\tfor _, animation in ipairs(oldTweens) do animation:Cancel() end\nend\n\nlocal function playWeatherSound(kind, volume, looped)\n\tlocal sound = Instance.new(\"Sound\")\n\tsound.Name = \"AK_Weather\" .. kind\n\tsound.SoundId = soundAssets[kind]\n\tsound.Looped = looped\n\tsound.Volume = 0\n\tsound.Parent = SoundService\n\ttable.insert(activeSounds, sound)\n\tsound.Ended:Connect(function()\n\t\tlocal index = table.find(activeSounds, sound)\n\t\tif index then table.remove(activeSounds, index) end\n\t\tsound:Destroy()\n\tend)\n\tsound:Play()\n\ttrackTween(sound, { Volume = volume }, looped and 1.4 or 0.12)\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Audio: \" .. kind) end\n\ttask.delay(5, function()\n\t\tif DEBUG_VISUALS and sound.Parent and not sound.IsLoaded then\n\t\t\twarn(\"[WeatherVisuals] Audio not loaded: \" .. kind .. \" (check Creator Store access)\")\n\t\tend\n\tend)\n\tif not looped then\n\t\ttask.delay(6, function()\n\t\t\tlocal index = table.find(activeSounds, sound)\n\t\t\tif index then table.remove(activeSounds, index) end\n\t\t\tif sound.Parent then sound:Destroy() end\n\t\tend)\n\tend\n\treturn sound\nend\n\nlocal function fadeWeatherSounds()\n\tlocal oldSounds = activeSounds\n\tactiveSounds = {}\n\tfor _, sound in ipairs(oldSounds) do\n\t\tif sound.Parent then\n\t\t\ttrackTween(sound, { Volume = 0 }, 0.35)\n\t\ttask.delay(0.4, function() sound:Destroy() end)\n\t\tend\n\tend\nend\n\nlocal function restoreOriginal(token)\n\ttrackTween(Lighting, original)\n\tfor className, effect in pairs(effects) do\n\t\tlocal snapshot = initialEffects[className]\n\t\tif snapshot then\n\t\t\tlocal numericAndColor = {}\n\t\t\tfor property, value in pairs(snapshot) do\n\t\t\t\tif property ~= \"Enabled\" then numericAndColor[property] = value end\n\t\t\tend\n\t\t\ttrackTween(effect, numericAndColor)\n\t\t\tif snapshot.Enabled ~= nil then\n\t\t\t\ttask.delay(TRANSITION, function()\n\t\t\t\t\tif token == generation then effect.Enabled = snapshot.Enabled end\n\t\t\t\tend)\n\t\t\tend\n\t\telse\n\t\t\t-- Newly created effects fade to neutral, then leave Lighting entirely.\n\t\t\tif className == \"Atmosphere\" then trackTween(effect, { Density = 0, Haze = 0, Glare = 0 }) end\n\t\t\tif className == \"Clouds\" then trackTween(effect, { Cover = 0 }) end\n\t\t\tif className == \"ColorCorrectionEffect\" then trackTween(effect, { Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1) }) end\n\t\t\tif className == \"BloomEffect\" then trackTween(effect, { Intensity = 0 }) end\n\t\t\tif className == \"SunRaysEffect\" then trackTween(effect, { Intensity = 0 }) end\n\t\t\tif className == \"BlurEffect\" then trackTween(effect, { Size = 0 }) end\n\t\tend\n\tend\n\ttask.delay(TRANSITION + 0.05, function()\n\t\tif token ~= generation then return end\n\t\tfor className in pairs(createdEffects) do\n\t\t\tlocal effect = effects[className]\n\t\t\tif effect then effect:Destroy() end\n\t\t\teffects[className] = nil\n\t\t\tindexEffect(className, nil)\n\t\tend\n\tend)\nend\n\nlocal function ensureEffects()\n\tlocal ready = true\n\tfor _, className in ipairs(requiredEffects) do\n\t\tlocal parent = className == \"Clouds\" and terrain or Lighting\n\t\tif not ensureEffect(className, parent) then ready = false end\n\tend\n\treturn ready\nend\n\nlocal function clearEvent(restore)\n\tgeneration += 1\n\tcancelTweens()\n\tfadeWeatherSounds()\n\tif followConnection then followConnection:Disconnect(); followConnection = nil end\n\tif runtime then runtime:Destroy(); runtime = nil end\n\tfor sky, moonSize in pairs(skyMoonSnapshots) do\n\t\tif sky.Parent then sky.MoonAngularSize = moonSize end\n\tend\n\tskyMoonSnapshots = {}\n\tif DEBUG_VISUALS and activeEventId then print(\"[WeatherVisuals] Clearing previous effects\") end\n\tif DEBUG_VISUALS and activeEventId then print(\"[WeatherVisuals] Clearing \" .. activeEventId) end\n\tif DEBUG_VISUALS and restore and activeEventId then print(\"[WeatherVisuals] Restoring defaults\") end\n\tactiveKey = nil\n\tactiveEventId = nil\n\tif restore then restoreOriginal(generation) end\nend\n\nlocal function makePart(name, parent, size, tint, transparency)\n\tlocal part = Instance.new(\"Part\")\n\tpart.Name = name\n\tpart.Anchored = true\n\tpart.CanCollide = false\n\tpart.CanTouch = false\n\tpart.CanQuery = false\n\tpart.CastShadow = false\n\tpart.Material = Enum.Material.Neon\n\tpart.Color = tint\n\tpart.Transparency = transparency or 0\n\tpart.Size = size\n\tpart.Parent = parent\n\treturn part\nend\n\nlocal particleStyles = {\n\tRain = { rate = 380, speed = NumberRange.new(75, 95), life = NumberRange.new(0.7, 1), size = 0.35, squash = 2.5, color = color(192, 217, 247), spread = 7, acceleration = Vector3.new(3, -55, 0) },\n\tHeavyRain = { rate = 560, speed = NumberRange.new(95, 120), life = NumberRange.new(0.65, 0.95), size = 0.42, squash = 3, color = color(202, 224, 255), spread = 12, acceleration = Vector3.new(12, -75, 0) },\n\tSnow = { rate = 210, speed = NumberRange.new(14, 22), life = NumberRange.new(2.2, 3.4), size = 0.55, color = color(244, 250, 255), spread = 35, acceleration = Vector3.new(5, -4, 2) },\n\tLeaves = { rate = 95, speed = NumberRange.new(35, 55), life = NumberRange.new(1.1, 1.8), size = 0.43, color = color(167, 197, 105), spread = 20, direction = Enum.NormalId.Right, acceleration = Vector3.new(35, 1, 5) },\n\tWindStreaks = { rate = 105, speed = NumberRange.new(70, 105), life = NumberRange.new(0.55, 0.95), size = 0.38, squash = 2.8, color = color(212, 235, 246), spread = 12, direction = Enum.NormalId.Right, acceleration = Vector3.new(30, 0, 0) },\n\tHaze = { rate = 20, speed = NumberRange.new(2, 5), life = NumberRange.new(1.5, 2.5), size = 0.42, color = color(255, 201, 130), spread = 35, acceleration = Vector3.new(0, 3, 0) },\n\tStars = { rate = 22, speed = NumberRange.new(1, 3), life = NumberRange.new(1.5, 2.8), size = 0.18, color = color(185, 230, 255), spread = 55, acceleration = Vector3.new(0, 1, 0) },\n\tAsh = { rate = 24, speed = NumberRange.new(2, 5), life = NumberRange.new(2, 3), size = 0.2, color = color(202, 95, 119), spread = 55, acceleration = Vector3.new(1, 2, 0) },\n\tSpiritMist = { rate = 35, speed = NumberRange.new(2, 6), life = NumberRange.new(2, 3), size = 0.26, color = color(134, 241, 229), spread = 60, acceleration = Vector3.new(0, 3, 0) },\n\tSparkles = { rate = 42, speed = NumberRange.new(2, 7), life = NumberRange.new(1, 2), size = 0.18, color = color(255, 218, 244), spread = 70, acceleration = Vector3.new(0, 2, 0) },\n\tChaos = { rate = 35, speed = NumberRange.new(5, 13), life = NumberRange.new(1, 2), size = 0.2, color = color(255, 133, 211), spread = 90, acceleration = Vector3.new(0, 2, 0) },\n\tInverted = { rate = 32, speed = NumberRange.new(3, 8), life = NumberRange.new(1, 2), size = 0.2, color = color(122, 255, 211), spread = 70, acceleration = Vector3.new(0, 5, 0) },\n\tVoid = { rate = 43, speed = NumberRange.new(2, 6), life = NumberRange.new(2, 3), size = 0.3, color = color(162, 84, 255), spread = 75, acceleration = Vector3.new(0, 4, 0) },\n\tGold = { rate = 50, speed = NumberRange.new(3, 8), life = NumberRange.new(1.2, 2.2), size = 0.2, color = color(255, 213, 85), spread = 75, acceleration = Vector3.new(0, 2, 0) },\n\tAdmin = { rate = 55, speed = NumberRange.new(4, 12), life = NumberRange.new(1, 2), size = 0.22, color = color(255, 216, 104), spread = 80, acceleration = Vector3.new(0, 3, 0) },\n}\n\nlocal function addParticles(styleName, rig)\n\tlocal style = particleStyles[styleName]\n\tif not style then return end\n\tlocal emitter = Instance.new(\"ParticleEmitter\")\n\temitter.Name = styleName .. \"Particles\"\n\temitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n\temitter.Shape = Enum.ParticleEmitterShape.Box\n\temitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\temitter.EmissionDirection = style.direction or Enum.NormalId.Bottom\n\temitter.Rate = style.rate\n\temitter.Lifetime = style.life\n\temitter.Speed = style.speed\n\temitter.SpreadAngle = Vector2.new(style.spread, style.spread)\n\temitter.Acceleration = style.acceleration\n\temitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, style.size), NumberSequenceKeypoint.new(1, 0) })\n\tif style.squash then emitter.Squash = NumberSequence.new(style.squash) end\n\tif style.squash then emitter.Orientation = Enum.ParticleOrientation.VelocityParallel end\n\temitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.08), NumberSequenceKeypoint.new(0.8, 0.22), NumberSequenceKeypoint.new(1, 1) })\n\temitter.Color = ColorSequence.new(style.color)\n\temitter.LightEmission = (styleName == \"Rain\" or styleName == \"HeavyRain\") and 0.08 or 0.55\n\temitter.LightInfluence = 0.15\n\temitter.Enabled = true\n\temitter.Parent = rig\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Created \" .. styleName .. \" effect; enabled=\" .. tostring(emitter.Enabled) .. \" rate=\" .. tostring(emitter.Rate)) end\nend\n\nlocal function skyAnchor(name, position)\n\tlocal anchor = makePart(name, runtime, Vector3.new(1, 1, 1), Color3.new(1, 1, 1), 1)\n\tanchor.Position = position\n\tanchor:SetAttribute(\"FixedWorldPosition\", position)\n\treturn anchor\nend\n\nlocal function attachment(parent, name, position, axis)\n\tlocal point = Instance.new(\"Attachment\")\n\tpoint.Name = name\n\tpoint.Position = position\n\tpoint.Axis = axis\n\tpoint.Parent = parent\n\treturn point\nend\n\nlocal function skyBeam(parent, name, from, to, tint, width, curve0, curve1)\n\tlocal beam = Instance.new(\"Beam\")\n\tbeam.Name = name\n\tbeam.Attachment0 = from\n\tbeam.Attachment1 = to\n\tbeam.Color = ColorSequence.new(tint)\n\tbeam.Width0 = width\n\tbeam.Width1 = width\n\tbeam.CurveSize0 = curve0\n\tbeam.CurveSize1 = curve1\n\tbeam.Segments = 32\n\tbeam.FaceCamera = true\n\tbeam.LightEmission = 1\n\tbeam.LightInfluence = 0\n\tbeam.Transparency = NumberSequence.new(0.26)\n\tbeam.Parent = parent\n\treturn beam\nend\n\nlocal function moonDisc(parent, name, size, position, tint, transparency)\n\tlocal disc = Instance.new(\"Frame\")\n\tdisc.Name = name\n\tdisc.AnchorPoint = Vector2.new(0.5, 0.5)\n\tdisc.Size = UDim2.fromScale(size, size)\n\tdisc.Position = position\n\tdisc.BackgroundColor3 = tint\n\tdisc.BackgroundTransparency = transparency or 0\n\tdisc.BorderSizePixel = 0\n\tdisc.Parent = parent\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(1, 0)\n\tcorner.Parent = disc\n\treturn disc\nend\n\nlocal function addSky(eventId)\n\tif eventId == \"Aurora\" then\n\t\tlocal anchor = skyAnchor(\"AuroraAnchor\", WORLD_SKY.Aurora)\n\t\tlocal auroraColors = { color(72, 255, 179), color(77, 228, 255), color(125, 164, 255), color(196, 117, 255), color(93, 255, 214) }\n\t\tfor index = 1, 5 do\n\t\t\tlocal from = attachment(anchor, \"RibbonStart\" .. index, Vector3.new(-750, index * 40, index * 80), Vector3.new(1, 1, 0).Unit)\n\t\t\tlocal to = attachment(anchor, \"RibbonEnd\" .. index, Vector3.new(750, index * 25, index * 80), Vector3.new(1, -1, 0).Unit)\n\t\t\tlocal ribbon = skyBeam(anchor, \"AuroraRibbon\", from, to, auroraColors[index], 55, 850, 850)\n\t\t\tribbon.Segments = 64\n\t\t\tribbon.Transparency = NumberSequence.new({\n\t\t\t\tNumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.26),\n\t\t\t\tNumberSequenceKeypoint.new(0.8, 0.26), NumberSequenceKeypoint.new(1, 1),\n\t\t\t})\n\t\tend\n\telseif eventId == \"BloodMoon\" then\n\t\tlocal anchor = skyAnchor(\"BloodMoonAnchor\", WORLD_SKY.BloodMoon)\n\t\t-- A world-space billboard remains at its anchored point and is occluded\n\t\t-- by buildings. Its scale is in STUDS, not fixed screen pixels.\n\t\tlocal moon = Instance.new(\"BillboardGui\")\n\t\tmoon.Name = \"BloodMoonDisc\"\n\t\tmoon.Adornee = anchor\n\t\tmoon.Size = UDim2.fromScale(1900, 1900)\n\t\tmoon.AlwaysOnTop = false\n\t\tmoon.LightInfluence = 0\n\t\tmoon.Brightness = 2\n\t\tmoon.MaxDistance = 0\n\t\tmoon.Parent = anchor\n\t\tmoonDisc(moon, \"Halo\", 1, UDim2.fromScale(0.5, 0.5), color(246, 60, 54), 0.83)\n\t\tlocal face = moonDisc(moon, \"MoonFace\", 0.88, UDim2.fromScale(0.5, 0.5), color(255, 118, 84))\n\t\tlocal gradient = Instance.new(\"UIGradient\")\n\t\tgradient.Color = ColorSequence.new(color(255, 186, 122), color(130, 24, 38))\n\t\tgradient.Rotation = 35\n\t\tgradient.Parent = face\n\t\tfor index, crater in ipairs({ {0.31, 0.35, 0.18}, {0.65, 0.30, 0.12}, {0.59, 0.64, 0.23}, {0.30, 0.65, 0.09}, {0.74, 0.50, 0.08} }) do\n\t\t\tmoonDisc(face, \"Crater\" .. index, crater[3], UDim2.fromScale(crater[1], crater[2]), color(108, 30, 37), 0.55)\n\t\tend\n\t\tfor _, sky in ipairs(Lighting:GetChildren()) do\n\t\t\tif sky:IsA(\"Sky\") then\n\t\t\t\tskyMoonSnapshots[sky] = sky.MoonAngularSize\n\t\t\t\tsky.MoonAngularSize = 0\n\t\t\tend\n\t\tend\n\telseif eventId == \"Rainbow\" then\n\t\tlocal anchor = skyAnchor(\"RainbowAnchor\", WORLD_SKY.Rainbow)\n\t\t-- Two cubic quarter-circle Beams per color make a smooth semicircle.\n\t\t-- The endpoints and arch stay fixed in the same world plane for everyone.\n\t\tlocal arcColors = { color(255, 90, 103), color(255, 177, 80), color(255, 237, 104), color(114, 227, 147), color(110, 188, 255), color(114, 123, 243), color(186, 132, 255) }\n\t\tfor index, tint in ipairs(arcColors) do\n\t\t\tlocal radius = 1204 - (index - 1) * 24.64\n\t\t\tlocal curve = radius * 0.5522847498\n\t\t\tlocal left = attachment(anchor, \"Left\" .. index, Vector3.new(-radius, 0, 0), Vector3.yAxis)\n\t\t\tlocal top = attachment(anchor, \"Top\" .. index, Vector3.new(0, radius, 0), Vector3.xAxis)\n\t\t\tlocal right = attachment(anchor, \"Right\" .. index, Vector3.new(radius, 0, 0), -Vector3.yAxis)\n\t\t\tfor _, beam in ipairs({\n\t\t\t\tskyBeam(anchor, \"RainbowArc\", left, top, tint, 24.08, curve, curve),\n\t\t\t\tskyBeam(anchor, \"RainbowArc\", top, right, tint, 24.08, curve, curve),\n\t\t\t}) do\n\t\t\t\tbeam.Segments = 64\n\t\t\t\tbeam.LightEmission = 0\n\t\t\t\tbeam.Transparency = NumberSequence.new(0.15)\n\t\t\tend\n\t\tend\n\telseif eventId == \"Void\" then\n\t\tlocal anchor = skyAnchor(\"VoidAnchor\", WORLD_SKY.Void)\n\t\tfor index = 1, 7 do\n\t\t\tlocal orb = makePart(\"VoidWisp\", anchor, Vector3.new(7, 7, 7), color(161, 77, 244), 0.32)\n\t\t\torb.Shape = Enum.PartType.Ball\n\t\t\torb.Position = WORLD_SKY.Void + Vector3.new((index - 4) * 55, math.sin(index) * 23, math.cos(index) * 30)\n\t\tend\n\tend\nend\n\nlocal function lightning(token, rig, preset)\n\tif token ~= generation or not runtime then return end\n\ttask.delay(rng:NextNumber(0.25, 0.55), function()\n\t\tif token == generation then playWeatherSound(\"Thunder\", 0.6, false) end\n\tend)\n\ttrackTween(Lighting, { ExposureCompensation = preset.exposure + 0.85 }, 0.07)\n\ttrackTween(effects.ColorCorrectionEffect, { Brightness = 0.24 }, 0.07)\n\ttask.delay(0.13, function()\n\t\tif token ~= generation then return end\n\t\ttrackTween(Lighting, { ExposureCompensation = preset.exposure }, 0.42)\n\t\ttrackTween(effects.ColorCorrectionEffect, { Brightness = 0 }, 0.42)\n\tend)\n\tlocal boltRoot = WORLD_SKY.Lightning + Vector3.new(rng:NextNumber(-700, 700), 0, rng:NextNumber(-300, 300))\n\tfor segment = 1, 3 do\n\t\tlocal bolt = makePart(\"DistantLightning\", runtime, Vector3.new(5, 120, 5), color(221, 239, 255), 0.08)\n\t\tbolt.CFrame = CFrame.new(boltRoot + Vector3.new((segment - 1) * 30, -(segment - 1) * 115, 0)) * CFrame.Angles(0, 0, math.rad(15))\n\t\ttrackTween(bolt, { Transparency = 1 }, 0.45)\n\t\ttask.delay(0.5, function() bolt:Destroy() end)\n\tend\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Lightning flash\") end\nend\n\nlocal function meteor(token, rig)\n\tif token ~= generation or not runtime then return end\n\tlocal count = 0\n\tfor _, child in ipairs(runtime:GetChildren()) do\n\t\tif child.Name == \"Meteor\" then count += 1 end\n\tend\n\tif count >= 8 then return end -- local quality cap\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Creating meteor shower VFX\") end\n\tlocal startPosition = WORLD_SKY.Meteors + Vector3.new(rng:NextNumber(-1100, 300), rng:NextNumber(0, 450), rng:NextNumber(-600, 600))\n\tlocal endPosition = startPosition + Vector3.new(rng:NextNumber(700, 1300), -rng:NextNumber(480, 760), rng:NextNumber(120, 360))\n\tlocal diameter = rng:NextNumber(16, 26)\n\tlocal meteorPart = makePart(\"Meteor\", runtime, Vector3.new(diameter, diameter, diameter), color(255, 139, 62), 0.05)\n\tmeteorPart.Shape = Enum.PartType.Ball\n\tmeteorPart.CFrame = CFrame.lookAt(startPosition, endPosition)\n\tlocal fire = Instance.new(\"Fire\")\n\tfire.Size = math.min(30, diameter * 1.8)\n\tfire.Heat = 5\n\tfire.Color = color(255, 183, 76)\n\tfire.SecondaryColor = color(255, 75, 47)\n\tfire.Parent = meteorPart\n\tlocal glow = Instance.new(\"PointLight\")\n\tglow.Color = color(255, 129, 61)\n\tglow.Brightness = 2.5\n\tglow.Range = 24\n\tglow.Parent = meteorPart\n\tlocal trail = Instance.new(\"Trail\")\n\ttrail.Name = \"MeteorTrail\"\n\ttrail.Color = ColorSequence.new(color(255, 226, 151), color(255, 107, 74))\n\ttrail.Lifetime = 0.55\n\ttrail.MinLength = 0.1\n\tlocal a = Instance.new(\"Attachment\")\n\ta.Position = Vector3.new(0, 0, -diameter * 0.5)\n\ta.Parent = meteorPart\n\tlocal b = Instance.new(\"Attachment\")\n\tb.Position = Vector3.new(0, 0, diameter * 0.5)\n\tb.Parent = meteorPart\n\ttrail.Attachment0 = a\n\ttrail.Attachment1 = b\n\ttrail.Parent = meteorPart\n\ttrackTween(meteorPart, { Position = endPosition, Transparency = 0.25 }, 0.9)\n\ttask.delay(0.85, function()\n\t\tif token ~= generation or not rig.Parent then return end\n\t\tlocal burst = makePart(\"MeteorBurst\", runtime, Vector3.new(30, 30, 30), color(255, 169, 74), 0.18)\n\t\tburst.Shape = Enum.PartType.Ball\n\t\tburst.Position = endPosition\n\t\ttrackTween(burst, { Size = Vector3.new(110, 110, 110), Transparency = 1 }, 0.38)\n\t\ttask.delay(0.4, function() burst:Destroy() end)\n\tend)\n\ttask.delay(1, function() meteorPart:Destroy() end)\nend\n\nlocal function spirit(token, rig)\n\tif token ~= generation or not runtime then return end\n\tlocal orb = makePart(\"SpiritOrb\", rig, Vector3.new(0.7, 0.7, 0.7), color(142, 255, 236), 0.18)\n\torb.Shape = Enum.PartType.Ball\n\torb.Position = rig.CFrame:PointToWorldSpace(Vector3.new(rng:NextNumber(-19, 19), rng:NextNumber(-4, 4), rng:NextNumber(-27, -8)))\n\ttrackTween(orb, { Position = orb.Position + Vector3.new(rng:NextNumber(-3, 3), 8, 0), Transparency = 1 }, 3.2)\n\ttask.delay(3.3, function() orb:Destroy() end)\nend\n\nlocal function startLoop(kind, token, rig, preset)\n\tif not kind then return end\n\ttask.spawn(function()\n\t\tlocal step = 0\n\t\twhile token == generation and runtime do\n\t\t\tif kind == \"Lightning\" then\n\t\t\t\tlightning(token, rig, preset)\n\t\t\telseif kind == \"Meteors\" then\n\t\t\t\tmeteor(token, rig)\n\t\t\t\tmeteor(token, rig)\n\t\t\t\tif rng:NextNumber() > 0.55 then meteor(token, rig) end\n\t\t\t\tplayWeatherSound(\"Meteor\", 0.26, false)\n\t\t\telseif kind == \"Spirits\" then\n\t\t\t\tspirit(token, rig)\n\t\t\telseif kind == \"Wind\" then\n\t\t\t\tlocal gusts = rig:FindFirstChild(\"WindStreaksParticles\")\n\t\t\t\tif gusts then gusts:Emit(55) end\n\t\t\t\ttrackTween(effects.Clouds, { Cover = rng:NextNumber(0.58, 0.9) }, 2)\n\t\t\telseif kind == \"Chaos\" then\n\t\t\t\tstep += 1\n\t\t\t\ttrackTween(effects.ColorCorrectionEffect, { TintColor = Color3.fromHSV((step * 0.17) % 1, 0.46, 1), Saturation = 0.28 + (step % 2) * 0.15 }, 2)\n\t\t\t\ttrackTween(effects.Atmosphere, { Color = Color3.fromHSV((step * 0.13) % 1, 0.4, 1) }, 2)\n\t\t\t\tif step % 3 == 0 then lightning(token, rig, preset) end\n\t\t\telseif kind == \"Nightmare\" then\n\t\t\t\ttrackTween(effects.BloomEffect, { Intensity = step % 2 == 0 and 0.34 or preset.bloom }, 1.5)\n\t\t\t\tstep += 1\n\t\t\telseif kind == \"Admin\" then\n\t\t\t\tstep += 1\n\t\t\t\ttrackTween(effects.ColorCorrectionEffect, { TintColor = Color3.fromHSV((step * 0.12) % 1, 0.34, 1) }, 2)\n\t\t\t\tif step % 3 == 0 then lightning(token, rig, preset) end\n\t\t\t\tif step % 2 == 0 then meteor(token, rig) end\n\t\t\tend\n\t\t\tlocal pause = kind == \"Lightning\" and rng:NextNumber(4, 8)\n\t\t\t\tor kind == \"Meteors\" and rng:NextNumber(1.4, 2.3)\n\t\t\t\tor kind == \"Spirits\" and rng:NextNumber(1.2, 2.1)\n\t\t\t\tor kind == \"Wind\" and rng:NextNumber(2, 3.4)\n\t\t\t\tor 3\n\t\t\t-- Short waits let a replaced event stop promptly without another connection.\n\t\t\tlocal elapsed = 0\n\t\t\twhile elapsed < pause and token == generation do\n\t\t\t\telapsed += task.wait(math.min(0.25, pause - elapsed))\n\t\t\tend\n\t\tend\n\tend)\nend\n\nlocal function applyEvent(eventId, key)\n\tlocal preset = presets[eventId]\n\tif not preset or not definitions[eventId] then return end\n\tclearEvent(false)\n\tif not ensureEffects() then\n\t\twarn(\"[WeatherVisuals] Preset \" .. eventId .. \" skipped: required visual effect missing\")\n\t\treturn\n\tend\n\tactiveKey = key\n\tactiveEventId = eventId\n\tlocal token = generation\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Applying preset: \" .. eventId) end\n\truntime = Instance.new(\"Folder\")\n\truntime.Name = \"WeatherVFX\"\n\truntime:SetAttribute(\"EventId\", eventId)\n\truntime.Parent = workspace\n\tlocal rig = makePart(\"WeatherEmitterRig\", runtime, Vector3.new(52, 2, 52), Color3.new(1, 1, 1), 1)\n\tlocal function followPrecipitation()\n\t\tlocal camera = workspace.CurrentCamera\n\t\tif camera and rig.Parent then\n\t\t\t-- Keep rain/snow vertical when the player tilts or turns the camera.\n\t\t\trig.CFrame = CFrame.new(camera.CFrame.Position + Vector3.new(0, 16, 0))\n\t\tend\n\tend\n\tfollowPrecipitation()\n\tif preset.particles or preset.extraParticles or preset.loop == \"Spirits\" then\n\t\tlocal elapsed = 0\n\t\tfollowConnection = RunService.Heartbeat:Connect(function(delta)\n\t\t\telapsed += delta\n\t\t\tif elapsed < 0.05 then return end\n\t\t\telapsed = 0\n\t\t\tfollowPrecipitation()\n\t\tend)\n\tend\n\tlocal tint = preset.tint\n\ttrackTween(Lighting, {\n\t\tClockTime = preset.clock, Brightness = preset.brightness,\n\t\tExposureCompensation = preset.exposure, FogStart = preset.fogStart or math.min(25, preset.fog * 0.1), FogEnd = preset.fog,\n\t\tFogColor = tint, Ambient = tint:Lerp(color(85, 92, 111), 0.65),\n\t\tOutdoorAmbient = tint:Lerp(color(136, 142, 157), 0.5),\n\t\tColorShift_Top = tint:Lerp(Color3.new(0, 0, 0), 0.72),\n\t\tColorShift_Bottom = tint:Lerp(Color3.new(0, 0, 0), 0.84),\n\t})\n\ttrackTween(effects.Atmosphere, { Density = preset.atmosphere, Color = tint, Decay = tint:Lerp(color(69, 73, 102), 0.6), Haze = preset.atmosphere * 4, Glare = 0.12 })\n\ttrackTween(effects.Clouds, { Cover = preset.clouds, Density = math.clamp(preset.clouds * 0.8, 0, 1), Color = tint })\n\teffects.Clouds.Enabled = true\n\tlocal correction = effects.ColorCorrectionEffect\n\tcorrection.Enabled = true\n\ttrackTween(correction, { Brightness = 0, TintColor = tint, Saturation = preset.saturation, Contrast = (eventId == \"Nightmare\" or eventId == \"BloodMoon\" or eventId == \"Inverted\") and 0.23 or 0.08 })\n\tlocal bloom = effects.BloomEffect\n\tbloom.Enabled = true\n\ttrackTween(bloom, { Intensity = preset.bloom, Size = 24, Threshold = 1.15 })\n\tlocal rays = effects.SunRaysEffect\n\trays.Enabled = preset.rays > 0\n\tif rays.Enabled then trackTween(rays, { Intensity = preset.rays, Spread = 0.75 }) end\n\tlocal blur = effects.BlurEffect\n\tblur.Enabled = (preset.blur or 0) > 0\n\tif blur.Enabled then trackTween(blur, { Size = preset.blur }) end\n\tif DEBUG_VISUALS then\n\t\tprint(\"[WeatherVisuals] FogStart: \" .. tostring(preset.fogStart or math.min(25, preset.fog * 0.1)) .. \" FogEnd: \" .. tostring(preset.fog))\n\t\tprint(\"[WeatherVisuals] ClockTime: \" .. tostring(preset.clock))\n\t\tprint(\"[WeatherVisuals] Atmosphere Density: \" .. tostring(preset.atmosphere))\n\t\ttask.delay(TRANSITION + 0.05, function()\n\t\t\tif token ~= generation then return end\n\t\t\tprint(\"[WeatherVisuals] Applied values: FogStart=\" .. tostring(Lighting.FogStart)\n\t\t\t\t.. \" FogEnd=\" .. tostring(Lighting.FogEnd)\n\t\t\t\t.. \" ClockTime=\" .. tostring(Lighting.ClockTime)\n\t\t\t\t.. \" Atmosphere Density=\" .. tostring(effects.Atmosphere.Density))\n\t\tend)\n\tend\n\tif preset.particles then addParticles(preset.particles, rig) end\n\tif preset.extraParticles then addParticles(preset.extraParticles, rig) end\n\tlocal ambient = ambientSounds[eventId]\n\tif ambient then playWeatherSound(ambient[1], ambient[2], true) end\n\tif preset.sky then\n\t\taddSky(preset.sky)\n\tend\n\tstartLoop(preset.loop, token, rig, preset)\nend\n\nlocal function refreshFromState()\n\tlocal phase = state:GetAttribute(\"Phase\")\n\tif phase == \"Break\" then\n\t\tif activeKey then clearEvent(true) end\n\t\treturn\n\tend\n\tif phase ~= \"Event\" then\n\t\tif activeKey then clearEvent(true) end\n\t\treturn\n\tend\n\tlocal id = state:GetAttribute(\"EventId\")\n\tif type(id) == \"string\" then id = aliases[id] or id end\n\tlocal startedAt = state:GetAttribute(\"StartedAt\")\n\tlocal endsAt = state:GetAttribute(\"EndsAt\")\n\tif type(id) ~= \"string\" or not definitions[id] or not presets[id]\n\t\tor type(startedAt) ~= \"number\" or type(endsAt) ~= \"number\"\n\t\tor startedAt <= 0 or endsAt <= startedAt or endsAt <= workspace:GetServerTimeNow() then\n\t\tif type(id) == \"string\" and id ~= \"\" and not definitions[id] and DEBUG_VISUALS then\n\t\t\twarn(\"[WeatherVisuals] Unknown event: \" .. id)\n\t\tend\n\t\tif activeKey then clearEvent(true) end\n\t\treturn\n\tend\n\tlocal key = id .. \":\" .. tostring(startedAt)\n\tif key ~= activeKey then applyEvent(id, key) end\nend\n\nstate.AttributeChanged:Connect(function(attribute)\n\tif attribute ~= \"Phase\" and attribute ~= \"EventId\" and attribute ~= \"StartedAt\" and attribute ~= \"EndsAt\" then return end\n\tif refreshQueued then return end\n\trefreshQueued = true\n\ttask.defer(function()\n\t\trefreshQueued = false\n\t\trefreshFromState()\n\tend)\nend)\nrefreshFromState()\nif DEBUG_VISUALS then print(\"[WeatherVisuals] Initialized\") end\n"}]]====])
for _,r in ipairs(changes) do local o=game for _,n in ipairs(r.path) do o=assert(o:FindFirstChild(n),"Missing source "..n) end assert(o:IsA("LuaSourceContainer")); if o.Source~=r.source then o.Source=r.source end print("[MapAudit] Source verified "..o:GetFullName()) end
local tests=game.ServerStorage:FindFirstChild("AK_AuditTests") or Instance.new("Folder");tests.Name="AK_AuditTests";tests.Parent=game.ServerStorage
do local t=Instance.new("ModuleScript");t.Name="SystemAudit.studio.server.lua";t.Source=[====[-- Run in the SERVER Command Bar during a fresh Studio Play session.
-- Moves one test player through the existing safe-landing code, then restores
-- their starting area. Does not change saved data, ownership, or authorization.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerScriptService = game:GetService("ServerScriptService")
assert(game:GetService("RunService"):IsRunning(), "Start a Studio Play session first")
local PlotLocator = require(ServerScriptService.PlotLocator)
local PlotStatus = require(ServerScriptService.AdminCommandCenter.PlotStatus)
local Teleports = require(ServerScriptService.AdminCommandCenter.Teleports)
local Profiles = require(ServerScriptService.ServerSource.Server.ProfileService)
local Admin = require(ServerScriptService.ServerSource.Server.WeatherAdminService)
local player = assert(Players:GetPlayers()[1], "No test player is connected")
local character = assert(player.Character, "Wait for the character to spawn")
local root = assert(character:FindFirstChild("HumanoidRootPart"), "Wait for the character root")
local original = root.CFrame
local failures = {}
local function check(name, passed, detail)
	print("[SystemAudit] " .. (passed and "PASS " or "FAIL ") .. name .. (detail and " | " .. tostring(detail) or ""))
	if not passed then table.insert(failures, name) end
end
local plots = PlotLocator.getPlots()
check("real plot floors discovered", #plots > 0, #plots)
local seen = {}
for _, plot in ipairs(plots) do
	local claimed = plot:GetAttribute("Claimed") == true
	local owner = plot:GetAttribute("OwnerUserId")
	check("ownership " .. plot.Name, not claimed or (type(owner) == "number" and not seen[owner]), owner)
	if claimed then seen[owner] = true end
	local spawn = PlotStatus.GetSpawn(plot)
	local ok, reason = false, "spawn missing"
	if spawn then ok, reason = Teleports.Near(player, spawn.CFrame) end
	check("safe plot landing " .. plot.Name, ok, reason)
	if ok then
		check("plot landing clears velocity " .. plot.Name, root.AssemblyLinearVelocity.Magnitude < 0.01)
	end
end
check("player owns one real plot", PlotStatus.GetPlayerPlot(player, plots) ~= nil, player:GetAttribute("PlotId"))
local loaded = Profiles.Profiles[player]
check("profile loaded", loaded ~= nil)
if loaded then
	check("ProfileStore session active", loaded:IsActive())
	check("profile data reconciled", type(loaded.Data.UnlockedBiomes) == "table" and loaded.Data.UnlockedBiomes.Meadow == true)
end
local points = workspace:FindFirstChild("AK_AdminCameraPoints")
local definitions = require(ReplicatedStorage.Shared.AdminCameraDefinitions)
for _, definition in ipairs(definitions) do
	local point = points and points:FindFirstChild(definition.Id)
	check("camera point " .. definition.Id, point ~= nil and point:IsA("BasePart"))
end
local room = workspace:FindFirstChild("WeatherAdminRoom")
check("admin room exists", room ~= nil)
local panels = room and room:FindFirstChild("CameraWallPanels")
if panels then
	local names = {}
	for _, panel in ipairs(panels:GetChildren()) do
		local id = panel:GetAttribute("CameraId")
		if id then
			check("camera label " .. id, type(panel:GetAttribute("CameraDisplayName")) == "string" and panel:GetAttribute("CameraDisplayName") ~= "")
			names[id] = true
		end
	end
	for _, definition in ipairs(definitions) do check("camera button " .. definition.Id, names[definition.Id] == true) end
else
	check("camera wall panels", false)
end
if Admin:IsAuthorized(player) then
	check("admin entry safe landing", Admin:EnterAdminRoom(player))
	check("admin entry room membership", Admin:IsInsideRoom(player))
	check("admin entry clears velocity", root.AssemblyLinearVelocity.Magnitude < 0.01)
else
	print("[SystemAudit] WARNING admin entry requires the existing authorized creator/admin test account")
end
local restored, reason = Teleports.Near(player, original)
check("return to starting area", restored, reason)
print("[SystemAudit] Finished: " .. #failures .. " failures; actual connected players=" .. #Players:GetPlayers())
if #Players:GetPlayers() < 2 then
	print("[SystemAudit] WARNING multiplayer admission/release still requires a separate two-client Studio test")
end
]====];t.Parent=tests end
do local t=Instance.new("ModuleScript");t.Name="WeatherAudit.studio.client.lua";t.Source=[====[-- Run in the CLIENT Command Bar in a fresh Studio Play session during Break.
-- Local replicated-state injection exercises the shipped visual/UI controllers.
-- Server timing/queue/authorization are tested separately by the admin suite.
assert(game:GetService("RunService"):IsStudio() and game:GetService("RunService"):IsClient(), "Studio client required")
task.spawn(function()
	local storage = game:GetService("ReplicatedStorage")
	local lighting = game:GetService("Lighting")
	local sounds = game:GetService("SoundService")
	local state = storage:WaitForChild("WeatherState")
	assert(state:GetAttribute("Phase") == "Break", "Start this test during the initial production Break")
	local definitions = require(storage.Shared.EventDefinitions)
	local savedState = state:GetAttributes()
	local camera = workspace.CurrentCamera
	local savedCamera, savedType, savedSubject = camera.CFrame, camera.CameraType, camera.CameraSubject
	local failures, tested = 0, 0
	local properties = {
		Lighting = { "Brightness", "ClockTime", "ExposureCompensation", "FogStart", "FogEnd", "FogColor", "Ambient", "OutdoorAmbient", "ColorShift_Top", "ColorShift_Bottom" },
		Atmosphere = { "Density", "Color", "Decay", "Haze", "Glare", "Offset" },
		Clouds = { "Cover", "Density", "Color", "Enabled" },
		ColorCorrectionEffect = { "Brightness", "Contrast", "Saturation", "TintColor", "Enabled" },
		BloomEffect = { "Intensity", "Size", "Threshold", "Enabled" },
		SunRaysEffect = { "Intensity", "Spread", "Enabled" },
		BlurEffect = { "Size", "Enabled" },
		Sky = { "MoonAngularSize", "MoonTextureId" },
	}
	local baseline = {}
	local function capture(instance)
		local values = {}
		for _, name in ipairs(properties[instance.ClassName] or {}) do values[name] = instance[name] end
		baseline[instance] = values
	end
	capture(lighting)
	for _, object in ipairs(lighting:GetChildren()) do if properties[object.ClassName] then capture(object) end end
	for _, object in ipairs(workspace.Terrain:GetChildren()) do if object:IsA("Clouds") then capture(object) end end
	local function check(ok, description)
		if not ok then failures += 1 end
		print("AK_WEATHER_AUDIT " .. (ok and "PASS " or "FAIL ") .. description)
	end
	local function phase(id)
		local now = workspace:GetServerTimeNow()
		state:SetAttribute("EventId", id or "")
		state:SetAttribute("StartedAt", id and now or 0)
		state:SetAttribute("EndsAt", id and now + 420 or 0)
		state:SetAttribute("Phase", id and "Event" or "Break")
	end
	local function verifyRestored(id)
		check(workspace:FindFirstChild("WeatherVFX") == nil, id .. " runtime destroyed")
		local soundCount = 0
		for _, object in ipairs(sounds:GetChildren()) do
			if string.sub(object.Name, 1, 10) == "AK_Weather" then soundCount += 1 end
		end
		check(soundCount == 0, id .. " weather sounds destroyed")
		local restored = true
		for instance, values in pairs(baseline) do
			for name, expected in pairs(values) do
				local actual = instance[name]
				local same = typeof(actual) == "number" and math.abs(actual - expected) < 0.0001 or actual == expected
				if not same then restored = false; warn(id .. " unrestored " .. instance.Name .. "." .. name) end
			end
		end
		for _, parent in ipairs({ lighting, workspace.Terrain }) do
			for _, object in ipairs(parent:GetChildren()) do
				if properties[object.ClassName] and not baseline[object] then restored = false end
			end
		end
		check(restored, id .. " Lighting/Atmosphere/Clouds/Sky restored")
	end
	local ok, err = pcall(function()
		camera.CameraType = Enum.CameraType.Scriptable
		local ids = {}
		for id in pairs(definitions) do table.insert(ids, id) end
		table.sort(ids)
		for _, id in ipairs(ids) do
			phase(id)
			task.wait(0.35)
			local runtime = workspace:FindFirstChild("WeatherVFX")
			check(runtime ~= nil and runtime:GetAttribute("EventId") == id, id .. " applies")
			check(definitions[id].Duration == 420, id .. " metadata duration 420")
			local ui = game.Players.LocalPlayer.PlayerGui:FindFirstChild("WeatherEventUI")
			local timer = ui and ui:FindFirstChild("Countdown", true)
			check(timer ~= nil and string.match(timer.Text, "Time Left: %d:%d%d") ~= nil, id .. " authoritative countdown visible")
			if runtime then
				local safe = true
				for _, object in ipairs(runtime:GetDescendants()) do
					if object:IsA("BasePart") and (not object.Anchored or object.CanCollide or object.CanTouch or object.CanQuery) then safe = false end
				end
				check(safe, id .. " effects anchored and noncolliding")
				local anchor = runtime:FindFirstChild(id .. "Anchor")
				if anchor then
					local fixed = anchor.CFrame
					camera.CFrame = CFrame.lookAt(Vector3.new(-338, 30, 248), anchor.Position)
					task.wait(0.1)
					local _, towards = camera:WorldToViewportPoint(anchor.Position)
					camera.CFrame *= CFrame.Angles(0, math.pi, 0)
					task.wait(0.1)
					local _, away = camera:WorldToViewportPoint(anchor.Position)
					camera.CFrame += Vector3.new(60, 0, 80)
					task.wait(0.1)
					check(anchor.CFrame == fixed and towards and not away, id .. " fixed world position across camera rotation/translation " .. tostring(anchor.Position))
				end
				if id == "Rainbow" then
					local beams = 0
					for _, object in ipairs(runtime:GetDescendants()) do if object:IsA("Beam") then beams += 1 end end
					check(beams == 14, "Rainbow smooth seven-color arch / 14 Beams")
				end
			end
			phase(nil)
			task.wait(2.2)
			verifyRestored(id)
			tested += 1
		end
		-- Rapid replacement must invalidate old tweens, particles, delayed bursts,
		-- sound cleanup and moon restore callbacks without touching the new event.
		for _, id in ipairs({ "Thunderstorm", "BloodMoon", "Rainbow", "MeteorShower", "Void" }) do
			phase(id)
			task.wait(0.12)
		end
		phase(nil)
		task.wait(2.3)
		verifyRestored("rapid replacement")
	end)
	if not ok then check(false, "runtime exception " .. tostring(err)) end
	phase(nil)
	task.wait(2.2)
	for name, value in pairs(savedState) do state:SetAttribute(name, value) end
	camera.CFrame, camera.CameraType, camera.CameraSubject = savedCamera, savedType, savedSubject
	print("AK_WEATHER_AUDIT_DONE events=" .. tested .. " failures=" .. failures)
end)
]====];t.Parent=tests end
do local t=Instance.new("ModuleScript");t.Name="BiomeTeleport.studio.lua";t.Source=[====[local server=game.ServerScriptService.BiomeTeleport
